// Original bilingual core chapters. These introduce every listed module; they are not a claim of expert-reviewed degree equivalence.
import {lessons as starter} from './computing.mjs';
const b=(en,zh)=>({en,zh});
// Chapter bodies are deliberately concise; examples and counterconditions carry the explanation.
const src={
 cpp:['C++ Core Guidelines','https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines'],
 algo:['MIT: Introduction to Algorithms','https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/'],
 advanced:['MIT: Design and Analysis of Algorithms','https://ocw.mit.edu/courses/6-046j-design-and-analysis-of-algorithms-spring-2015/'],
 os:['Operating Systems: Three Easy Pieces, authors’ edition','https://pages.cs.wisc.edu/~remzi/OSTEP/'],
 net:['IETF: Internet Protocol, RFC 8200','https://www.rfc-editor.org/rfc/rfc8200'],
 db:['PostgreSQL: SQL and database documentation','https://www.postgresql.org/docs/current/'],
 software:['MIT: Software Construction','https://ocw.mit.edu/courses/6-005-software-construction-spring-2016/'],
 theory:['MIT: Automata, Computability, and Complexity','https://ocw.mit.edu/courses/6-045j-automata-computability-and-complexity-spring-2011/'],
 compiler:['LLVM: My First Language Frontend','https://llvm.org/docs/tutorial/'],
 ml:['Stanford CS229: Machine Learning','https://cs229.stanford.edu/'],
 security:['NIST: Introduction to Information Security','https://csrc.nist.gov/pubs/sp/800/12/r1/final'],
 graphics:['Physically Based Rendering, fourth edition','https://www.pbr-book.org/4ed/contents'],
 hci:['W3C: Introduction to Web Accessibility','https://www.w3.org/WAI/fundamentals/accessibility-intro/'],
 distributed:['MIT: Distributed Systems','https://pdos.csail.mit.edu/6.824/'],
 numerical:['MIT: Introduction to Numerical Analysis','https://ocw.mit.edu/courses/18-330-introduction-to-numerical-analysis-spring-2012/'],
 statistics:['NIST/SEMATECH: Engineering Statistics Handbook','https://www.itl.nist.gov/div898/handbook/'],
 signals:['MIT: Signals and Systems','https://ocw.mit.edu/courses/res-6-007-signals-and-systems-spring-2011/'],
 research:['National Academies: Reproducibility and Replicability in Science','https://nap.nationalacademies.org/catalog/25303/reproducibility-and-replicability-in-science']
};
export const lessons=[];
export const outlines={};
export const titles={};
const courseSource={S01:'cpp',S02:'algo',S03:'algo',S04:'advanced',S05:'advanced',S06:'algo',S07:'advanced',S08:'advanced',S09:'advanced',S10:'algo',S11:'os',S12:'os',S13:'net',S14:'db',S15:'software',S16:'theory',S17:'compiler',S18:'ml',S19:'security',S20:'graphics',S21:'hci',S22:'distributed',X01:'numerical',X02:'statistics',X03:'signals',X04:'research'};
const roots={S01:['cs.instructions'],S02:['cs.arrays','math.proof'],S03:['cs.arrays','cs.complexity'],S04:['cs.invariants','cs.complexity'],S05:['cs.arrays','cs.invariants'],S06:['cs.graphs'],S07:['cs.arrays','cs.complexity'],S08:['cs.modular'],S09:['module.S05.06','module.S06.06'],S10:['cs.complexity','cs.invariants'],S11:['cs.conditionals','math.powers-roots'],S12:['module.S11.05'],S13:['module.S11.01'],S14:['cs.arrays'],S15:['cs.functions'],S16:['math.proof','cs.instructions'],S17:['module.S16.03','cs.functions'],S18:['math.functions','math.vectors','math.derivatives'],S19:['module.S13.04','cs.variables'],S20:['math.vectors','math.functions'],S21:[],S22:['module.S12.02','module.S13.03'],X01:['math.derivatives','cs.arrays'],X02:['math.ratios','math.functions'],X03:['math.derivatives','math.integrals'],X04:['physics.units','cs.instructions']};
const sec=(type,title,en,zh)=>({type,title,body:b(en,zh)});
const n=(en,zh,answer,he,hz,ee,ez)=>({type:'numeric',prompt:b(en,zh),answer,tolerance:1e-8,hints:[b(he,hz)],explanation:b(ee,ez)});
const q=(en,zh,truth,he,hz,ee,ez)=>({type:'choice',prompt:b(en,zh),options:[{id:'true',text:b('True','正确')},{id:'false',text:b('False','错误')}],answer:truth?'true':'false',hints:[b(he,hz)],explanation:b(ee,ez)});
function add(id,en,zh,concepts,paragraphs,exercises,extra=[]){
 const courseId=id.split('.')[0], order=Number(id.split('.')[1]);
 titles[id]=b(en,zh);
 outlines[id]={concepts:concepts.map(([a,z])=>b(a,z)),check:b(`Explain ${concepts[0][0].toLowerCase()}, then justify the worked calculation and its assumptions.`,`解释${concepts[0][1]}，说明例题计算及其成立条件。`)};
 const prerequisite=order===1?roots[courseId]:[`module.${courseId}.${String(order-1).padStart(2,'0')}`];
 const source=src[courseSource[courseId]];
 lessons.push({id:`module.${id}`,courseId,moduleId:id,title:b(en,zh),summary:b(paragraphs[0][0].split('. ')[0]+'.',paragraphs[0][1].split('。')[0]+'。'),prerequisites:[...new Set([...prerequisite,...extra])],minutes:25,objectives:[b(`Explain ${concepts[0][0].toLowerCase()} with its conditions.`,`说明${concepts[0][1]}及其条件。`),b(`Use ${concepts[1][0].toLowerCase()} in a worked problem.`,`在问题中应用${concepts[1][1]}。`)],sections:paragraphs.map(([e,z],i)=>sec(['concept','concept','example','pitfall'][i],b(['Meaning and model','Mechanism and reasoning','Worked example','Conditions and connections'][i],['概念与模型','机制与推理','推演例题','条件与联系'][i]),e,z)),exercises:exercises.map((e,i)=>({...e,id:`module.${id}.q${i+1}`})),sources:[{title:source[0],url:source[1]}],contentStatus:'original-core-chapter',visual:null});
}
function adapt(id,en,zh,concepts,ids,extraSections=[]){
 const base=ids.map(x=>starter.find(l=>l.id===x));
 if(base.some(x=>!x))throw Error('Missing starter '+id);
 add(id,en,zh,concepts,base[0].sections.slice(0,4).map(s=>[s.body.en,s.body.zh]),base[0].exercises);
 const l=lessons.at(-1);
 l.sections=[...base.flatMap(x=>x.sections),...extraSections.map(([e,z])=>sec('concept',b('Extend the idea','拓展理解'),e,z))];
 l.exercises=base.flatMap(x=>x.exercises).map((x,i)=>({...x,id:`module.${id}.q${i+1}`}));
 if(base[0].code)l.code=base[0].code;
}

adapt('S01.01','Programs, input and output','程序、输入与输出', [['Specification','规范'],['Execution trace','执行跟踪'],['Compilation','编译']],['cs.instructions']);
adapt('S01.02','Types, expressions and control flow','类型、表达式与控制流',[['Types and assignment','类型与赋值'],['Boolean conditions','布尔条件'],['Loops and termination','循环与终止']],['cs.variables','cs.conditionals','cs.loops']);
adapt('S01.03','Functions, scope and recursion','函数、作用域与递归',[['Function contract','函数约定'],['Local scope','局部作用域'],['Recursion and base cases','递归与边界']],['cs.functions'],[
 ['Recursion means that a function calls itself on a smaller instance. To compute factorial for a nonnegative integer n, return 1 when n is zero; otherwise return n times factorial(n−1). Each call has its own local n. The decreasing nonnegative argument proves termination. There are n+1 calls, so time and call-stack space are both O(n); integer overflow limits which factorials fit in a fixed-width type.','递归是函数对更小的问题调用自身。非负整数 n 的阶乘：n=0 返回 1，否则返回 n×factorial(n−1)。每次调用有自己的局部 n；非负参数递减保证终止。共有 n+1 次调用，时间和调用栈空间均为 O(n)；固定宽度整数还受溢出限制。']
]);
adapt('S01.04','Arrays, strings and standard containers','数组、字符串与标准容器',[['Indexed sequence','下标序列'],['String characters','字符串字符'],['Container choice','容器选择']],['cs.arrays'],[
 ['A string stores a sequence of character units. The number of UTF-8 bytes need not equal the number of visible Chinese characters, so byte indexing is not a general text cursor. A vector supports contiguous random access; a map associates ordered keys with values; an unordered_map uses hashing and provides expected constant-time lookup under suitable conditions. Choose the container from its required operations, not from its name.','字符串保存字符编码单元。UTF-8 字节数不一定等于可见汉字数，因此字节下标不是通用文本光标。vector 连续存储并支持随机访问；map 按序关联键和值；unordered_map 使用散列，在适当条件下具有期望常数查询时间。应根据操作需求选择容器。']
]);
add('S01.05','References, memory and value semantics','引用、内存与值语义',[['Object lifetime','对象生存期'],['Reference alias','引用别名'],['Value ownership','值与所有权']], [
 ['An object is storage with a type and a lifetime. An integer variable owns an integer value; a reference names an existing object rather than creating another copy. A pointer stores an address and may be null. These distinctions determine whether an operation changes the original value and whether accessing it is valid.','对象是具有类型和生存期的存储。整数变量拥有整数值；引用为已有对象提供别名，不会复制对象。指针保存地址，也可能为空。区别决定操作是否改变原值，以及访问是否有效。'],
 ['Passing an int by value initializes a separate parameter. Passing int& permits modification of the caller’s integer; const int& permits observation without modification through that reference. A local object usually dies when its block ends. Returning a reference to that dead object creates a dangling reference, even if its former bytes temporarily appear unchanged.','按值传递 int 会建立独立参数；int& 允许修改调用者的整数，const int& 只允许通过该引用观察。局部对象通常在代码块结束时销毁；返回它的引用会悬空，即使原字节暂时未变也不能合法访问。'],
 ['Start with a=7, then copy b=a and bind int& r=a. Assigning b=10 changes only b. Assigning r=12 changes a to 12 because r aliases a. A vector owns its elements, but growing it may move its storage and invalidate references into that storage. Copying a vector normally copies its elements.','从 a=7 开始，复制 b=a，再绑定 int& r=a。b=10 只改变 b；r=12 会让 a 变为 12，因为二者指同一对象。vector 拥有元素，但扩容可能移动存储并使元素引用失效；复制 vector 通常复制其元素。'],
 ['Prefer automatic objects and owning containers before manual allocation. Resource acquisition is initialization ties cleanup to object destruction, including exception paths. Ownership answers who must release a resource; borrowing answers who may temporarily access it. Neither a nonnull pointer nor a successful earlier access proves that the object is still alive.','先使用自动对象和拥有资源的容器，再学习手动分配。RAII 把清理绑定到对象析构，包括异常路径。所有权回答谁负责释放，借用回答谁可暂时访问。指针非空或之前访问成功，都不能证明对象仍然存活。']
], [n('After a=7; int& r=a; r=12;, what is a?','a=7; int& r=a; r=12; 后 a 是多少？',12,'A reference is an alias.','引用是别名。','r and a designate one object, so the assignment changes a to 12.','r 与 a 指同一对象，赋值后 a=12。'),q('A reference to a destroyed local object is safe if its bytes have not changed.','局部对象销毁后，只要字节未变，其引用仍安全。',false,'Validity depends on lifetime.','有效性取决于生存期。','The lifetime has ended; unchanged storage does not revive the object.','生存期已结束，字节未变不能让对象复活。')]);
add('S01.06','Debugging, testing and robust input','调试、测试与稳健输入',[['Reproduction','复现'],['Boundary testing','边界测试'],['Input validation','输入验证']], [
 ['A defect is a mismatch between intended and actual behavior. Debugging starts by reproducing the mismatch with a small input and a precise expected result. A test supplies input and checks an observable property. A compiler checks language rules, while a debugger exposes execution state; neither replaces an algorithm’s correctness argument.','缺陷是预期行为与实际行为不一致。调试先用小输入复现，并明确期望结果。测试提供输入并检查可观察性质；编译器检查语言规则，调试器显示执行状态，二者都不能代替算法正确性论证。'],
 ['Read structured input into initialized variables and verify whether extraction succeeded before using the values. Check counts before allocating arrays, ranges before indexing, and divisors before division. During development, assertions express conditions that should hold internally. Invalid external input needs an explicit error path rather than reliance on an assertion that may be disabled.','把结构化输入读入已初始化变量，并在使用前检查读取成功。分配数组前检查数量，访问前检查下标，除法前检查除数。断言表达内部应满足的条件；外部非法输入需要明确错误处理，不能依赖可能关闭的断言。'],
 ['Suppose a maximum routine starts best=0. It passes [2,5] but fails [−3,−1], returning zero although zero is absent. Reducing the failure to [−1] reveals the wrong initialization. For a nonempty array, initialize best from its first element and inspect the remainder. Decide separately what an empty input means.','若求最大值时 best=0，则 [2,5] 正常，[−3,−1] 却错误返回不存在的 0。缩小为 [−1] 就能发现初始化错误。非空数组应从首元素初始化，再检查剩余元素；空输入要单独定义。'],
 ['Design tests around empty, single-element, duplicate, extreme, and boundary cases. Sanitizers can detect some invalid memory operations or undefined behavior in instrumented runs, but only on exercised paths. Keep a failing example as a regression test after fixing it. Random tests become useful evidence when paired with an independent oracle and a saved seed.','测试应覆盖空、单元素、重复、极值和边界。检测工具可在实际执行路径中发现部分非法内存操作或未定义行为，但不是穷尽证明。修复后保留失败样例作为回归测试；随机测试应配独立答案程序并保存种子。']
], [n('What is the maximum of [−7,−2,−9]?','[−7,−2,−9] 的最大值是多少？',-2,'Compare actual elements, not an artificial zero.','比较真实元素，不引入零。','−2 is greater than −7 and −9; initializing the candidate to zero would be wrong.','−2 大于 −7 和 −9，以零初始化会出错。'),q('A program passing ten tests is mathematically proved correct for every valid input.','程序通过十个测试就证明了所有合法输入都正确。',false,'Tests examine selected executions.','测试只检查选定执行。','Untested inputs may fail; a general proof must cover all cases under the specification.','未测试输入仍可能失败，普遍证明必须覆盖规范下所有情况。')]);

adapt('S02.01','Specifications and invariants','规范与不变量',[['Precondition','前置条件'],['Loop invariant','循环不变量'],['Postcondition','后置条件']],['cs.invariants']);
add('S02.02','Correctness proofs','正确性证明',[['Induction','归纳法'],['Partial correctness','部分正确性'],['Termination measure','终止度量']], [
 ['Correctness means that every permitted input produces a required output. Partial correctness says that if the algorithm terminates, its output is valid. Total correctness also proves termination. A proof must use the actual preconditions: binary search needs an ordered array, while a shortest-path method may need nonnegative edge weights.','正确性要求每个允许输入都产生规定输出。部分正确性指若终止则输出正确；完全正确性还证明终止。证明必须使用真实前提，例如二分查找要求有序数组，一些最短路算法要求非负边权。'],
 ['For a loop, prove initialization of an invariant, preservation by one iteration, and how the invariant plus the stopping condition implies the result. Then choose a nonnegative integer measure that strictly decreases on every continuing iteration. For recursive algorithms, use induction on the input size and show that every recursive call has smaller size.','循环证明分为不变量初始成立、每轮保持、退出时推出答案；再找每轮严格递减的非负整数证明终止。递归算法按规模归纳，且每次调用规模必须更小。'],
 ['To sum the first n array elements, maintain s equal to the sum of positions before i. Initially i=0 and the empty sum is zero. Adding a[i] and incrementing i preserves the claim. At i=n, s is the required full sum. The measure n−i decreases by one, assuming bounds and arithmetic remain valid.','求前 n 个数组元素之和，保持 s 等于 i 之前元素的和。初始 i=0，空和为零；加入 a[i] 后增加 i，性质保持。i=n 时得到全和。度量 n−i 每轮减少一，前提是下标和算术有效。'],
 ['Examples suggest a theorem but cannot substitute for its universal step. A proof about mathematical integers does not automatically prove fixed-width C++ arithmetic safe. State how overflow is excluded or handled. When a proof fails, search for the earliest invalid implication; this often identifies a missing precondition more quickly than rewriting the entire algorithm.','例子能启发定理，但不能替代普遍推理。数学整数的证明不自动保证固定宽度 C++ 整数安全，需要说明如何排除或处理溢出。证明失败时，寻找最早不成立的一步，往往能发现遗漏前提。']
], [n('For n=9 and i=4, what is the loop termination measure n−i?','n=9、i=4 时，终止度量 n−i 是多少？',5,'Count the unprocessed positions.','计算尚未处理的位置数。','9−4=5 remaining iterations under the stated loop.','9−4=5，在该循环中还剩五轮。'),q('Partial correctness alone guarantees the program eventually returns.','部分正确性本身保证程序最终返回。',false,'It is conditional on termination.','它以终止为条件。','A separate decreasing measure or equivalent argument must establish termination.','还需要递减度量或其他论证来证明终止。')]);
adapt('S02.03','Time and space complexity','时间与空间复杂度',[['Input size','输入规模'],['Asymptotic bounds','渐近界'],['Auxiliary space','辅助空间']],['cs.complexity']);
add('S02.04','Recursion and recurrence analysis','递归与递推复杂度分析',[['Recursion tree','递归树'],['Recurrence relation','递推关系'],['Stack depth','栈深度']], [
 ['A running-time recurrence describes work on an input through smaller inputs. For merge sort, splitting into two halves and merging in linear time gives T(n)=2T(n/2)+Θ(n), with constant work at size one. This equation models operations rather than exact wall-clock seconds and assumes the subproblem sizes are balanced.','运行时间递推用较小输入的工作量描述当前输入。归并排序分成两半，再线性合并，得到 T(n)=2T(n/2)+Θ(n)，规模一时为常数。该式描述操作量而非精确秒数，并假定划分平衡。'],
 ['Expand calls as a tree. At depth d, merge sort has 2^d calls of size n/2^d; their combined merging work is Θ(n). There are Θ(log n) levels, giving Θ(n log n) time. In contrast, a recurrence T(n)=T(n−1)+Θ(n) adds n+(n−1)+…+1 and therefore grows quadratically.','把调用展开为树。第 d 层有 2^d 个规模 n/2^d 的调用，总合并工作仍为 Θ(n)。共有 Θ(log n) 层，所以时间为 Θ(n log n)。T(n)=T(n−1)+Θ(n) 累加 n 到 1，因而是二次增长。'],
 ['With eight elements, a balanced split has sizes 8, then 4, then 2, then 1 along a root-to-leaf path. There are three splitting steps and eight leaves. Even though the tree contains many calls, the maximum simultaneous recursive depth is four calls. Space additionally depends on whether arrays are copied or buffers are reused.','八个元素的平衡划分路径为 8、4、2、1，有三次划分、八个叶子。虽然总调用多，同时递归深度只有四层。空间还取决于是否复制数组或复用缓冲区。'],
 ['Do not apply a recurrence formula without checking its form. Unequal branches, input-dependent partition sizes, and memoized repeated states need different reasoning. Naive Fibonacci recursion repeats subproblems exponentially; memoization computes each distinct argument once. Time follows the number of evaluated states and transitions, while stack space follows a longest active chain.','不能不检查形式就套公式。不等分支、依赖输入的划分和记忆化重复状态需要不同分析。朴素斐波那契递归重复计算，记忆化则每个参数只算一次；时间看状态和转移数，栈空间看最长活动调用链。']
], [n('How many leaves arise when 16 elements are split evenly to singleton subproblems?','16 个元素均分直到单元素，会有多少叶子？',16,'Each original element belongs to one leaf.','每个原元素对应一个叶子。','Singleton subproblems partition the 16 elements, so there are 16 leaves.','单元素子问题划分了16个元素，因此有16个叶子。'),q('Two recursive calls always imply exponential time.','每次有两个递归调用就一定是指数时间。',false,'Track how quickly the argument shrinks.','观察参数缩小的速度。','Merge sort has two half-size calls and Θ(n log n) time; duplicated almost-full calls behave differently.','归并排序两次半规模调用只有 Θ(n log n)，重复近乎全规模调用则不同。')]);
add('S02.05','Brute force, pruning and lower-bound intuition','暴力枚举、剪枝与下界直觉',[['Exhaustive search','穷举搜索'],['Safe pruning','安全剪枝'],['Information lower bound','信息下界']], [
 ['Brute force enumerates a finite set containing every possible solution, checks validity, and chooses the best valid candidate. Its value is clarity: a slow complete solver can become an oracle for a faster implementation. Counting candidates before coding prevents confusing a small-looking input with a manageable search space.','暴力方法枚举包含所有可能解的有限集合，检查合法性，再选择最优合法候选。清晰完整的慢算法可以成为快算法的答案程序。编码前计算候选数量，避免把看似小的输入误认为容易搜索。'],
 ['There are 2^n subsets of n independently selectable items and n! orderings of n distinct items. Pruning removes a partial search state only after proving that no extension can improve the incumbent or satisfy the constraints. A lower bound for a minimization branch is useful because a branch whose bound exceeds the best known cost cannot win.','n 个独立可选元素有 2^n 个子集，n 个不同元素有 n! 种排列。只有证明某部分状态的所有延伸都不能改善答案或满足约束，才能剪枝。最小化搜索中，分支下界超过当前最好值时可以舍弃。'],
 ['For subset sum with nonnegative weights [2,4,7] and target 6, a branch already totaling 7 can be pruned: adding remaining nonnegative values cannot decrease it. The subset {2,4} succeeds. If a remaining item could be −3, pruning total 7 would become invalid because a later addition could restore feasibility.','非负权 [2,4,7] 的子集和目标为 6。当前和已为 7 的分支可以剪掉，因为以后非负加法不会降低它；{2,4} 成功。若剩余元素可能为 −3，和为 7 时剪枝就不合法，因为后续可能重新可行。'],
 ['A comparison decision tree with height h distinguishes at most 2^h outcomes. Sorting n distinct keys requires distinguishing n! orders, motivating an Ω(n log n) comparison lower bound. This does not forbid linear-time counting sort under bounded-integer assumptions: it uses operations and information beyond pairwise comparisons. Lower bounds belong to a specified computational model.','高度 h 的二叉比较决策树最多区分 2^h 个结果。排序不同键需区分 n! 种次序，得到比较模型下 Ω(n log n) 下界。它不排斥有界整数计数排序的线性时间，因为计算模型不同。']
], [n('How many subsets does a set of six distinct items have?','六个不同元素有多少子集？',64,'Each item has two independent choices.','每项有选或不选两种选择。','2^6=64, including the empty set and the full set.','2^6=64，包括空集和全集。'),q('In subset-sum search with negative weights, exceeding the target always permits pruning.','含负权的子集和搜索，只要超过目标就总能剪枝。',false,'A later negative weight can reduce the total.','后面的负权可以降低总和。','The monotonicity argument requires nonnegative remaining weights; without it, the pruning can discard solutions.','单调性要求剩余权非负，否则剪枝可能丢解。')]);
add('S02.06','Counterexamples and differential testing','反例与对拍测试',[['Counterexample','反例'],['Independent oracle','独立答案程序'],['Failure reduction','失败用例化简']], [
 ['A counterexample is one permitted input that contradicts a claimed universal property. Differential testing runs two implementations on the same input and compares their results. One is often a small, slow exhaustive oracle. Agreement increases confidence; disagreement proves at least one implementation, comparison rule, or shared specification is wrong.','反例是一个违反普遍断言的合法输入。对拍把相同输入交给两个实现并比较结果，其中一个常是小规模穷举答案程序。一致增加信心，不一致则证明某个实现、比较规则或共同规范出了问题。'],
 ['Generate inputs from the actual legal domain, including deliberately biased families: duplicates, sorted values, isolated vertices, and boundary capacities. Save the seed and full failing input. A test with many optimal answers must compare objective values and validity, rather than require the two programs to print identical but equally valid solutions.','应在合法域内生成输入，并主动覆盖重复、已排序、孤立点、边界容量等结构。保存种子和完整失败输入。若最优解不唯一，应比较目标值和合法性，而不能要求两个正确程序输出完全相同方案。'],
 ['Suppose a greedy coin solver disagrees with dynamic programming for denominations [1,3,4] and amount 6. Greedy takes 4+1+1, using three coins; the oracle takes 3+3, using two. This tiny example disproves the claim that choosing the largest coin always minimizes the number of coins for arbitrary denominations.','面额 [1,3,4]、金额 6 时，贪心选 4+1+1，共三枚；动态规划选 3+3，只需两枚。这个小反例否定“任意面额下优先选最大硬币总能最少”的说法。'],
 ['Reduction repeatedly removes irrelevant input pieces while preserving the failure. Keep the legality constraints intact during reduction. Two fast programs copied from the same mistaken recurrence are not independent evidence. Combine differential tests with metamorphic properties: renaming graph vertices should preserve distances under the same renaming, and permuting a multiset should preserve its sum.','化简逐步删除无关部分，同时保持失败和输入合法性。两个照抄错误递推的快程序不是独立证据。还可用变形性质辅助：重命名图顶点不应改变对应距离，重新排列多重集不应改变总和。']
], [n('For coins [1,3,4], what is the minimum number needed for amount 6?','面额 [1,3,4] 凑 6 最少需多少枚？',2,'Try using the same middle denomination twice.','尝试两枚中间面额。','3+3 uses two coins; no single available coin has value 6.','3+3 用两枚，没有面额6，所以一枚不可能。'),q('Different output order proves an error even when the problem permits any order.','即使题目允许任意顺序，输出顺序不同也一定证明错误。',false,'Check the specification before comparing strings.','比较字符串前先看规范。','Both outputs can be valid; normalize order or verify the required mathematical result.','两个输出都可能正确，应规范化顺序或验证数学结果。')]);

add('S03.01','Arrays, linked structures, stacks and queues','数组、链式结构、栈与队列',[['Random access','随机访问'],['Linked nodes','链式节点'],['LIFO and FIFO','后进先出与先进先出']], [
['A data structure represents information together with operations. An array places elements consecutively, so an index computes an element address directly. A linked list stores nodes connected by references; finding the kth node normally follows k links. Equal logical contents can therefore have very different access costs.','数据结构同时规定信息表示和操作。数组连续存放，可由下标直接算出地址；链表通过引用连接节点，找第 k 个节点通常要沿链走 k 步。相同内容可以有完全不同的访问代价。'],
['A stack removes the most recently inserted item: last in, first out. A queue removes the oldest item: first in, first out. Both can use arrays or linked nodes. An array queue needs head and tail positions; a circular buffer reuses consumed slots without shifting every remaining element.','栈删除最近加入者，即后进先出；队列删除最早加入者，即先进先出。二者都可用数组或链表。数组队列保存头尾位置，循环缓冲区复用空位，无需移动所有剩余元素。'],
['Push 4, then 8, then 2. A stack pop returns 2 and leaves [4,8]; a queue dequeue returns 4 and leaves [8,2]. Stack behavior matches nested function calls, while a queue maintains the discovery order used by breadth-first search. Empty removal must be checked explicitly.','依次加入 4、8、2，栈弹出 2，剩 [4,8]；队列取出 4，剩 [8,2]。栈对应嵌套函数调用，队列维持广度优先搜索的发现顺序。删除前必须检查是否为空。'],
['Inserting after an already known linked node is constant time, but locating that node may be linear. Array insertion in the middle shifts a suffix. Big-O alone ignores cache locality and allocation overhead, so benchmark realistic operations after establishing correctness. Store indices instead of raw addresses when container movement would invalidate references.','在已知链表节点后插入是常数时间，但寻找节点可能线性。数组中间插入要移动后缀。渐近复杂度不反映缓存和分配开销，应先证明正确，再测真实操作；容器移动可能使地址失效时可保存下标。']
], [n('A queue receives 4,8,2. What is removed first?','队列依次加入4、8、2，先删除什么？',4,'FIFO removes the oldest entry.','先进先出。','4 was inserted first, so it leaves first.','4最先加入，所以最先离开。'),q('Linked-list access to an arbitrary index is always constant time.','链表按任意下标访问总是常数时间。',false,'The target must first be reached.','必须先走到目标。','Without an auxiliary index, traversal may visit linearly many nodes.','没有辅助索引时，可能要遍历线性数量节点。')]);
add('S03.02','Binary search and ordered containers','二分查找与有序容器',[['Partition boundary','分界位置'],['Lower bound','下界位置'],['Ordered dictionary','有序字典']], [
['Binary search locates a boundary in a monotone predicate, not merely an exact value. For a sorted array and target x, the predicate a[i] >= x changes from false to true at most once. The lower bound is its first true position, or the array length if no position qualifies.','二分查找寻找单调谓词的分界，而不只是找相等值。有序数组中 a[i]>=x 至多从假变真一次；第一个真位置是 lower bound，若不存在则为数组长度。'],
['Maintain a half-open candidate interval [l,r). Set m=l+(r−l)/2. If a[m]<x, all positions through m fail, so set l=m+1; otherwise set r=m. Each step preserves the boundary inside the possible range and shortens the interval. When l=r, the common endpoint is the answer.','维护半开候选区间 [l,r)。取 m=l+(r−l)/2。若 a[m]<x，则到 m 都不满足，令 l=m+1；否则令 r=m。每步保持分界并缩短区间，l=r 时得到答案。'],
['For [2,4,4,9] and x=4, start [0,4). Testing index 2 gives true, so r=2; testing 1 gives true, so r=1; testing 0 gives false, so l=1. The returned index is 1, identifying the first duplicate rather than an arbitrary equal element.','[2,4,4,9] 找 x=4：从 [0,4) 开始，测下标2为真，r=2；测1为真，r=1；测0为假，l=1。答案1是第一个重复值，而不是任意相等元素。'],
['A balanced ordered tree supports logarithmic search and insertion, whereas inserting into a sorted vector may require linear movement. An unordered hash table does not support ordered predecessor queries directly. Binary search assumes a consistent comparator; changing stored keys without restoring order destroys the invariant even if the search code itself is correct.','平衡有序树支持对数查询与插入；有序 vector 插入可能需要线性移动。散列表不直接支持有序前驱。比较器必须一致；改变键而不恢复顺序，会破坏二分前提。']
], [n('Using zero-based indexing, what is lower_bound([2,4,4,9],4)?','零基下标下，lower_bound([2,4,4,9],4) 是多少？',1,'Find the first value at least 4.','找第一个不小于4的值。','Index 1 is the first qualifying position.','下标1是第一个满足的位置。'),q('Binary search is valid on any unsorted sequence if all values are distinct.','只要元素互异，任意无序序列都能二分。',false,'Distinctness does not imply monotonicity.','互异不代表单调。','The discarded half is justified by order, not uniqueness.','舍弃一半的依据是有序，不是互异。')]);
add('S03.03','Heaps and disjoint-set union','堆与并查集',[['Heap order','堆序'],['Representative','代表元'],['Path compression','路径压缩']], [
['A binary min-heap is a nearly complete binary tree whose parent key is no greater than either child key. The root is therefore minimal, but unrelated subtrees need not be sorted. An array stores children of index i at 2i+1 and 2i+2, allowing compact priority-queue operations.','二叉小根堆是近乎完全的二叉树，父键不大于孩子，所以根最小，但不同子树不一定有序。数组中下标 i 的孩子是2i+1和2i+2，可紧凑实现优先队列。'],
['Heap insertion bubbles a new leaf upward; deleting the minimum moves the last leaf to the root and pushes it downward. Both take logarithmic time. Disjoint-set union solves a different task: maintain a partition into connected groups. Each item follows parent links to a root representative; union links two different roots.','堆插入把新叶向上调整；删除最小值把末叶放到根并向下调整，均为对数时间。并查集解决分组问题：每个元素沿父指针找到根代表，合并把不同根连接起来。'],
['Begin with four singleton sets. Union(0,1) and union(2,3) leave two groups; union(1,2) leaves one group. Comparing representatives now establishes that 0 and 3 are connected. Path compression redirects visited parents to the root, and union by size attaches the smaller root below the larger group.','四个单元素集合，合并(0,1)、(2,3)后剩两组，再合并(1,2)剩一组。代表元相同说明0与3连通。路径压缩把访问节点指向根，按大小合并让小组根接到大组。'],
['With both optimizations, a sequence of disjoint-set operations has near-constant amortized cost, expressed using the inverse Ackermann function. Ordinary DSU does not support arbitrary edge deletion or list actual graph paths. Heap order likewise does not make binary search valid on its backing array. Always match the representation to its guaranteed operations.','两项优化下，并查集操作序列具有用反阿克曼函数表示的近常数均摊代价。普通并查集不支持任意删边，也不直接给出图路径；堆序同样不允许在底层数组直接二分。']
], [n('Starting with five singleton groups, how many remain after three successful unions of different groups?','五个单元素组，三次成功合并不同组后剩几组？',2,'Each successful union reduces the count by one.','每次成功合并减少一组。','5−3=2 groups remain.','5−3=2组。'),q('Every min-heap array is globally sorted.','每个小根堆数组都全局有序。',false,'Only ancestor-to-child comparisons are constrained.','只有父子之间受堆序约束。','Sibling subtrees may interleave arbitrarily while preserving the root minimum.','兄弟子树可交错，根仍然最小。')]);
add('S03.04','Trees and search trees','树与搜索树',[['Tree structure','树结构'],['Search-tree invariant','搜索树不变量'],['Balancing','平衡']], [
['A tree is a connected undirected graph without cycles. Choosing a root assigns every other vertex a unique parent; children lie one edge farther from the root. A subtree contains a vertex and all its descendants. These structural definitions support recursive traversal because subtrees are disjoint and individually remain trees.','树是连通且无环的无向图。选根后，其余顶点有唯一父亲，孩子离根更远一条边。子树包含节点及所有后代；子树互不交叠且仍是树，因此适合递归遍历。'],
['A binary search tree stores keys so every left-subtree key precedes the root key and every right-subtree key follows it, under a stated duplicate policy. Searching compares once and descends into only one subtree. Inorder traversal visits left subtree, root, then right subtree, producing sorted keys by induction on subtree size.','二叉搜索树要求左子树键小于根、右子树键大于根，并明确重复键规则。查询比较后只进入一个子树。中序遍历按左、根、右访问，由子树规模归纳可知输出有序。'],
['Insert keys 4,2,6,1,3 into an initially empty search tree. Searching for 3 compares with 4, then 2, then 3. Inserting sorted keys 1,2,3,4 without balancing instead creates a chain. Height determines operation cost: a chain has linear height, while a balanced tree has logarithmic height.','插入4、2、6、1、3后，查找3依次比较4、2、3。若不平衡地插入1、2、3、4，会形成链。操作代价由高度决定：链为线性高度，平衡树为对数高度。'],
['Rotations rearrange a local parent-child relationship while preserving inorder order. Balanced search trees use extra information, such as heights or colors, to decide when rotations are required. A rotation is not permission to violate ordering. When deleting a node with two children, replacing it with its inorder successor preserves ordering only if that successor is removed from its old position.','旋转调整局部父子关系，同时保持中序次序。平衡树利用高度或颜色决定旋转时机，但不能破坏排序。删除双孩子节点时，可用中序后继替换，同时必须从后继原位置删除它。']
], [n('How many edges does a tree with seven vertices contain?','七个顶点的树有多少条边？',6,'Every nonroot vertex has one parent edge.','每个非根顶点有一条父边。','There are seven vertices and six nonroot vertices, hence six edges.','七个顶点中六个非根，因此六条边。'),q('Inorder traversal of a valid binary search tree lists keys in sorted order.','合法二叉搜索树的中序遍历按序列出键。',true,'Apply the ordering rule recursively.','递归应用有序规则。','All left keys precede the root, which precedes all right keys.','所有左键先于根，根先于所有右键。')]);
add('S03.05','Fenwick and segment trees','树状数组与线段树',[['Prefix decomposition','前缀分解'],['Associative aggregation','结合性聚合'],['Lazy propagation','延迟标记']], [
['Range-query structures summarize intervals so repeated queries avoid scanning every element. A Fenwick tree stores selected binary-sized blocks of prefix sums. At one-based index i, lowbit(i)=i&−i gives the block length. Removing this low bit moves to the previous disjoint block when computing a prefix sum.','区间数据结构汇总区间，避免每次扫描。树状数组保存特定二进制长度的前缀块；一基下标 i 的 lowbit(i)=i&−i 表示块长，查询时减去最低位，转到前一个不交叠块。'],
['A Fenwick point update visits indices i, i+lowbit(i), and onward; a prefix query repeatedly subtracts lowbit. Both use logarithmic steps. A segment tree recursively splits an interval and stores an aggregate at each node. Associativity permits combining child summaries; an identity value handles disjoint pieces without changing the result.','树状数组单点更新沿 i+lowbit(i) 前进，前缀查询沿 i−lowbit(i) 后退，都是对数步。线段树递归划分区间，节点保存聚合值；结合律允许合并孩子，单位元处理无交集。'],
['For values [3,1,4,2], the sum on zero-based positions [1,3] is prefix(3)−prefix(0)=10−3=7. A sum segment tree stores 4 for its left half and 6 for its right half. Updating the third value from 4 to 9 increases all containing sums by five, including the root from 10 to 15.','[3,1,4,2] 零基闭区间[1,3]之和为 prefix(3)−prefix(0)=10−3=7。线段树左右半区和为4和6。第三项4改为9，所有包含它的和增加5，根从10变15。'],
['Lazy propagation postpones a range update while maintaining a correct summary and a composable pending tag. For adding d to a sum segment of length k, its sum increases by dk. Tag order matters for assignment combined with addition. Prefix subtraction works for sums because an inverse exists; it does not directly turn prefix minima into arbitrary range minima.','延迟标记推迟区间更新，但必须保持汇总正确且标记可复合。长 k 的和区间每项加 d，总和加 dk。赋值与加法的标记顺序重要。前缀相减依赖可逆性，不能直接用前缀最小值得到任意区间最小值。']
], [n('What is the sum of positions 1 through 3 in [3,1,4,2], using zero-based indices?','零基下标下，[3,1,4,2] 的位置1到3之和是多少？',7,'Add 1,4,2.','加1、4、2。','1+4+2=7.','1+4+2=7。'),n('Adding 3 to every element of a length-5 segment increases its sum by how much?','长度5区间每项加3，总和增加多少？',15,'Each of the five elements contributes 3.','五个元素各增加3。','The increment is 3×5=15.','增量为3×5=15。')]);
add('S03.06','Amortization and data-structure design','均摊分析与数据结构设计',[['Aggregate cost','总量分析'],['Potential function','势能函数'],['Operation contract','操作约定']], [
['Amortized analysis bounds the total cost of a sequence of operations without assuming a random input distribution. One expensive operation can be balanced by many cheap operations. This differs from average-case analysis, which needs a probability model. Worst-case cost per operation and amortized cost can both be correct but answer different questions.','均摊分析不假定随机输入，而是限制一串操作的总代价。一次昂贵操作可被许多便宜操作分担；平均复杂度则需要概率模型。单次最坏和均摊复杂度可以同时正确，只是回答不同问题。'],
['A dynamic array doubles capacity when full. Copying at capacities 1,2,4,…,2^k moves fewer than 2^(k+1) elements altogether. Across n insertions, total copying is O(n), so insertion is amortized O(1), although a particular growth operation costs O(n). The unused capacity trades extra memory for fewer future reallocations.','动态数组满时容量翻倍。容量1、2、4到2^k的复制总量小于2^(k+1)。n次插入总复制量为O(n)，所以均摊O(1)，但一次扩容仍可能O(n)。预留空间换取更少重分配。'],
['A queue built from two stacks pushes into an input stack. To dequeue, if the output stack is empty, transfer every input element into it, reversing order. Each element is pushed into the input once, moved once, and popped once. Thus a long transfer does not invalidate the constant amortized operation cost.','双栈队列向输入栈压入；出队时若输出栈空，就把输入栈全部倒入以反转顺序。每个元素入输入栈一次、转移一次、弹出一次，所以一次很长的转移不影响常数均摊代价。'],
['A potential function stores analytical credit in the current state. Define amortized cost as actual cost plus the change in potential; telescoping sums bound total actual work if the potential is nonnegative. Choose a potential tied to future expensive work, such as untransferred queue elements. This mathematical credit is not stored money and need not be implemented in code.','势能函数把分析用的“积蓄”放在当前状态，均摊代价等于实际代价加势能变化；非负势能让求和抵消后限制总工作量。势能应对应未来昂贵工作，如尚未转移元素；它无需在代码中实际保存。']
], [n('How many total elements are copied when full capacities 1,2,4,8 each grow once?','容量1、2、4、8各扩容一次，总共复制多少元素？',15,'Add the geometric sequence.','相加等比序列。','1+2+4+8=15.','1+2+4+8=15。'),q('Amortized constant time guarantees every individual operation takes constant time.','均摊常数时间保证每次操作都是常数时间。',false,'The guarantee covers the sequence total.','保证针对操作序列总量。','A growth or transfer operation may be linear while the sequence total remains linear.','一次扩容或转移可能线性，但整个序列总代价仍线性。')]);

add('S04.01','Enumeration and state-space search','枚举与状态空间搜索',[['State representation','状态表示'],['Search transition','搜索转移'],['Completeness','完备性']], [
['A search state records exactly the information needed to continue a partial solution. A transition makes one legal choice. The start state contains no choices, and accepting states meet the goal. Search is complete only if every valid solution corresponds to a path that the algorithm can explore.','搜索状态记录继续部分解所需的信息，转移执行一个合法选择。初始状态尚未选择，接受状态达到目标。只有每个合法解都对应可探索路径，搜索才完备。'],
['Depth-first search follows one branch until it ends, then backtracks. Breadth-first search expands states in increasing numbers of transitions and finds shortest paths when every transition has equal cost. If multiple paths reach equivalent states, a visited set avoids repeated expansion. State equivalence must preserve future possibilities, not merely a convenient visible feature.','深搜沿分支到底再回退；广搜按转移次数分层，等代价时找到最短路径。若多条路径到达等价状态，可用访问集合去重；等价必须保持未来可能性，而不是只看方便的表面特征。'],
['To enumerate binary strings of length three, a state is the chosen prefix. Append zero or one until length three, producing eight leaves. If exactly two ones are required, accepting leaves are 011,101,110. Storing only prefix length would merge prefixes with different numbers of ones and lose information needed for acceptance.','枚举长三的二进制串，状态是已选前缀，追加0或1直到长度三，产生八个叶子。要求恰有两个1时接受011、101、110。只存长度会合并1的数量不同的前缀，丢失判断所需信息。'],
['Separate generation, validity checking, and objective evaluation before optimizing. A recursion depth bound estimates stack space, while the number of visited states estimates time only after accounting for work per state. Graph search must distinguish a vertex from a path-dependent state: having collected a key can change which doors are reachable from the same location.','优化前分开生成、合法性和目标评价。递归深度估算栈空间，状态数乘每状态工作量才是时间。图上的位置不一定是完整状态：是否拿到钥匙会改变同一地点能进入哪些门。']
], [n('How many length-four binary strings exist?','长度四的二进制串有多少？',16,'There are two choices at each position.','每个位置两种选择。','2^4=16 distinct strings.','2^4=16种。'),q('BFS guarantees minimum total cost even when transition costs differ.','即使转移代价不同，BFS也保证最小总代价。',false,'It minimizes edge count under equal costs.','它在等代价时最小化边数。','A one-edge path can cost more than a two-edge path; weighted search needs another method.','一条边可能比两条边更贵，加权搜索需要其他方法。')]);
add('S04.02','Backtracking and branch pruning','回溯与分支剪枝',[['Choose and undo','选择与撤销'],['Feasibility bound','可行性界'],['Symmetry reduction','对称消除']], [
['Backtracking constructs a solution incrementally and restores state after exploring each choice. The restoration step is part of correctness: a sibling branch must begin from exactly the same parent state. One implementation copies small states; another mutates a shared state and explicitly undoes every change when returning.','回溯逐步构造解，并在探索选择后恢复状态。恢复是正确性的一部分，兄弟分支必须从相同父状态开始。可以复制小状态，也可修改共享状态并返回时撤销每个改变。'],
['Feasibility pruning rejects a partial choice that cannot extend to a valid solution. Optimization pruning rejects one whose best possible completion cannot beat the incumbent. These require proofs of impossibility or bounds. Symmetry reduction chooses one representative among equivalent configurations, but must account for multiplicity if the task counts labeled solutions.','可行性剪枝排除无法延伸成合法解的部分选择；最优化剪枝排除最理想完成也不能改善当前最优者，都需要证明。对称消除只搜等价配置代表，但计数有标签解时必须处理重数。'],
['For choosing exactly three items from five, track position i and selected count k. If k exceeds three, reject. If k plus the number remaining is below three, reject as well. At i=5, accept exactly when k=3. The second bound detects failure before exploring every remaining include/exclude sequence.','五选三时记录位置 i 与已选数 k。k>3 则排除；k加剩余数小于3也排除；i=5时恰好k=3才接受。第二个界可在枚举所有剩余选择前判定失败。'],
['For queens, occupied columns and two diagonal identifiers give constant-time conflict checks per placement. After recursion, clear precisely the marks created by that placement. Sorting choices to find good solutions earlier can improve pruning speed, but does not prove the bound. Report worst-case exponential behavior even if a heuristic is fast on friendly examples.','八皇后可记录占用列和两类对角线编号，常数时间查冲突；递归后只撤销本次新增标记。优先尝试好选择能加速剪枝，但不能替代界的证明。即使常见输入很快，也应承认最坏指数行为。']
], [n('A branch must choose 4 items, has chosen 1, and has 2 items left. What is its maximum possible final count?','需要选4项，已选1项，剩2项；最终最多能选几项？',3,'Choose every remaining item.','把剩下的都选上。','1+2=3, so the branch cannot reach four and is safely pruned.','1+2=3，达不到4，可以安全剪枝。'),q('Forgetting to undo a visited mark can remove valid sibling-branch solutions.','忘记撤销访问标记可能删掉兄弟分支中的合法解。',true,'Sibling branches share the mutable state.','兄弟分支共用可变状态。','The leftover mark incorrectly forbids a choice that the sibling should be allowed to make.','残留标记会错误禁止兄弟分支本可作出的选择。')]);
adapt('S04.03','Binary search on answers','答案二分',[['Monotone feasibility','单调可行性'],['Boundary invariant','边界不变量'],['Decision optimization','判定到优化']],['cs.binary-search'],[
['To minimize a feasible integer answer, construct a predicate feasible(x) that is false below the optimum and true at or above it. For machines processing jobs by time T, count how many jobs fit by T, using saturating addition if counts might overflow. Search the first feasible T inside proved bounds. This reduction is valid only after establishing monotonicity of the predicate and correctness of the feasibility calculation.','最小化可行整数答案时，构造低于最优值为假、达到及超过最优值为真的 feasible(x)。例如机器在时间T内完成多少工作，计数可能溢出时使用截断加法。证明范围、单调性与判定正确后，二分第一个可行T。']
]);
add('S04.04','Greedy choice and exchange arguments','贪心选择与交换论证',[['Local choice','局部选择'],['Exchange proof','交换证明'],['Optimal substructure','最优子结构']], [
['A greedy algorithm commits to a locally chosen action without reconsidering it later. Correctness requires more than an appealing intuition: prove that some optimal solution begins with the selected action, then show that the remaining task has the same form. This is a stronger claim than merely finding good answers on examples.','贪心选择局部动作后不再反悔。必须证明存在一个最优解以该动作开始，并且剩余任务同型；直觉或例子中的好表现都不足以保证正确。'],
['For selecting the maximum number of nonoverlapping intervals, choose the interval that finishes earliest, discard conflicts, and repeat. In an optimal schedule, replace its first interval by this earliest-finishing interval. The replacement finishes no later, so every later scheduled interval remains feasible. The number selected is unchanged, establishing a safe first choice.','最多选择互不重叠区间时，选结束最早者，删除冲突后重复。把最优安排的首区间换成结束最早者，不会推迟结束，因此后续仍可行，数量不变，首选安全。'],
['For intervals [0,3), [1,2), [2,4), earliest finish chooses [1,2) then [2,4), giving two intervals. Choosing the longest interval first may select [0,3) and block both others. Half-open endpoint convention means that finishing at time two is compatible with starting at time two.','对[0,3)、[1,2)、[2,4)，最早结束策略选后两项，得到两个。优先最长可能选[0,3)并阻挡其余。半开区间约定允许时刻2结束与时刻2开始相接。'],
['Weighted interval scheduling does not obey the same greedy rule: one long valuable interval can outweigh many short cheap intervals. That variant usually needs dynamic programming. Exchange arguments must preserve every constraint and the objective value; exchanging feasible objects while accidentally changing a weight sum is not a proof of optimality.','加权区间安排不服从相同贪心：一个长且高价值区间可能优于多个短低价值区间，通常要用动态规划。交换必须保持所有约束和目标值；只保持可行却改变权值，不算最优证明。']
], [n('How many compatible intervals does earliest-finish choose from [0,3), [1,2), [2,4)?','最早结束策略在[0,3)、[1,2)、[2,4)中选几项？',2,'Choose [1,2) first.','先选[1,2)。','It can then choose [2,4), yielding two nonoverlapping intervals.','然后可选[2,4)，共两项不重叠。'),q('An unweighted greedy proof automatically proves the weighted version.','无权贪心证明自动适用于加权版本。',false,'The objective changes from count to total weight.','目标从数量变成总权。','An exchange preserving count may reduce total weight, breaking optimality.','保持数量的交换可能降低总权，从而破坏最优性。')]);
add('S04.05','Divide-and-conquer algorithms','分治算法',[['Partition','划分'],['Recursive solution','递归求解'],['Merge cost','合并代价']], [
['Divide and conquer separates a problem into smaller instances, solves those recursively, and combines their answers. The split and combine steps must account for interactions crossing subproblem boundaries. Independent subproblem answers alone are insufficient when a global solution can use objects from both sides.','分治把问题分成较小实例，递归求解再合并。划分和合并必须处理跨越子问题边界的联系；若全局解能同时使用两边对象，只有独立子问题答案并不足够。'],
['Merge sort sorts each half, then repeatedly takes the smaller front element of the two sorted halves. The invariant is that the output prefix contains the smallest elements already consumed in sorted order. Remaining elements in an exhausted comparison are appended. Linear merge work over logarithmically many balanced levels yields O(n log n) time.','归并排序先排左右，再反复取两边当前较小首元素。不变量是输出前缀有序且恰含已消耗的最小元素；一边空后追加另一边。每层线性、共对数层，得到O(n log n)。'],
['Merge [1,5,8] and [2,3,9]: take 1,2,3,5,8, then append 9. Counting inversions uses the same merge: if the right front is smaller, it forms an inversion with every still-unconsumed left element. Adding that count processes all cross-half inversions without enumerating every pair individually.','合并[1,5,8]和[2,3,9]依次取1、2、3、5、8，再追加9。数逆序对时，右首小于左首，就与所有未消耗左元素构成逆序，累计其数量即可处理跨区间逆序。'],
['Choose a base case that actually decreases toward termination, and specify how equal keys are handled when stability matters. Repeated copying or concatenation can silently change the recurrence. Quicksort partitions around a pivot and has expected O(n log n) time under suitable randomization, but unbalanced deterministic partitions can take quadratic time.','基础情况必须可达；需要稳定性时要明确相等键顺序。反复复制或拼接可能改变复杂度。快速排序按枢轴划分，合适随机化下期望O(n log n)，但失衡确定性划分可能达到二次时间。']
], [n('How many inversions are in [3,1,2]?','[3,1,2] 有多少逆序对？',2,'Count earlier elements larger than later elements.','数前大后小的数对。','The pairs (3,1) and (3,2) are inversions; (1,2) is not.','(3,1)、(3,2)是逆序，(1,2)不是。'),q('Every divide-and-conquer algorithm runs in O(n log n).','所有分治算法都是O(n log n)。',false,'Subproblem sizes and combine costs determine the recurrence.','规模与合并成本决定递推。','Different branching, imbalance, or expensive merging can yield other growth rates.','分支数、失衡和昂贵合并会产生其他增长率。')]);
add('S04.06','Meet-in-the-middle and mixed methods','折半搜索与混合方法',[['Split enumeration','折半枚举'],['Join condition','连接条件'],['Time-memory trade-off','时间空间权衡']], [
['Meet-in-the-middle reduces an exponential search by enumerating two halves separately and combining compatible summaries. For subset sum on n items, full enumeration uses 2^n subsets. Each half has about 2^(n/2) subsets, and a searchable list of half sums can replace a quadratic comparison of all left-right pairs.','折半搜索分别枚举两半，再结合兼容汇总。n项子集和全枚举需2^n个子集，每半约2^(n/2)个；把半和存成可查询表，避免左右笛卡尔积逐一比较。'],
['Generate every left-half sum and every right-half sum. To reach target T, a left sum L needs right sum T−L. Sort the right sums and binary-search the complement, or use a hash table with understood collision behavior. Counting solutions requires retaining multiplicities; deduplicating equal sums would destroy the number of distinct subsets.','枚举左右所有子集和。目标T下，左和L需右和T−L；可对右和排序后二分，或用散列表。若要求方案数，必须保留重数；去掉相同和会丢失不同子集方案。'],
['For [2,5,3,7] and T=10, split [2,5] and [3,7]. Left sums are 0,2,5,7; right sums are 0,3,7,10. The left sum 7 pairs with right sum 3, producing subset {2,5,3}. The left sum 0 also pairs with right sum 10, producing {3,7}.','[2,5,3,7]目标10，拆[2,5]与[3,7]，左和0、2、5、7，右和0、3、7、10。左7配右3得{2,5,3}；左0配右10得{3,7}。'],
['The method trades memory for a smaller exponent and is useful when n is moderate but numeric targets are huge. Small targets may instead favor pseudo-polynomial knapsack DP. For inequalities such as total sum at most T, sort summaries and use upper bounds or two pointers. Negative numbers are compatible with enumeration, but invalidate some naive monotone pruning rules.','该方法用内存换较小指数，适合n中等而目标巨大；目标小时伪多项式背包DP可能更好。总和不超过T可用排序、上界查找或双指针。负数可正常枚举，但会破坏某些朴素单调剪枝。']
], [n('A split of 20 items into two groups of ten generates how many subsets per half?','20项拆成两组10项，每半有多少子集？',1024,'Compute 2^10.','计算2^10。','Each half independently generates 1024 sums.','每半独立产生1024个和。'),q('When counting subsets, equal half sums may always be collapsed into one without a frequency.','数子集方案时，相同半和总能不记频次地合并。',false,'Distinct subsets may have the same sum.','不同子集可能有相同和。','Their multiplicities contribute distinct combinations and must be preserved.','重数贡献不同组合，必须保留。')]);

adapt('S05.01','States, transitions and base cases','状态、转移与边界',[['Sufficient state','充分状态'],['Transition','转移'],['Base case','边界']],['cs.dp']);
add('S05.02','Sequence and grid DP','序列与网格动态规划',[['Prefix state','前缀状态'],['Dependency order','依赖顺序'],['Rolling storage','滚动存储']], [
['Sequence DP summarizes a prefix or a position together with any history relevant to future decisions. For the longest increasing subsequence, let dp[i] be the longest strictly increasing subsequence ending exactly at i. The ending condition matters: a best subsequence somewhere in the prefix may end with a value too large to extend.','序列DP汇总前缀或位置及未来所需历史。最长严格上升子序列定义dp[i]为恰好以i结尾的最优长度；“以i结尾”重要，因为前缀最优可能以过大元素结尾而不能延伸。'],
['The recurrence is dp[i]=1+max dp[j] over j<i with a[j]<a[i], using zero when no predecessor qualifies. Testing every earlier j gives O(n²) time and O(n) space. Grid DP similarly uses topological movement: if moves are only right or down, a cell can depend on its upper and left neighbors.','递推为dp[i]=1+max dp[j]，限制j<i且a[j]<a[i]，没有前驱时最大值取0。枚举前驱为O(n²)时间、O(n)空间。网格若只能右或下，可依赖上方和左方。'],
['For [3,1,2,5], the ending lengths are [1,1,2,3], and the answer is three from 1,2,5. On a 2-by-3 obstacle-free grid, starting at the upper-left and moving right/down yields three paths to the lower-right. Initialize the start to one; blocked cells contribute zero regardless of their neighbors.','[3,1,2,5]的结尾长度为[1,1,2,3]，答案是1、2、5。无障碍2行3列网格从左上到右下有三条右下路径；起点置1，障碍格无论邻居如何都置0。'],
['Rolling arrays discard a row only after no future transition needs it. Updating left-to-right may intentionally reuse the current row’s left value while retaining the old upper value. For reconstruction, store predecessor choices or recompute them later. Strictly increasing and nondecreasing subsequences use different comparisons, so duplicate-value tests are essential.','滚动数组只能在未来不再需要旧行时覆盖。由左至右更新时可有意使用当前行左值和旧行上值。重建路径要存前驱或重算；严格上升和不下降比较条件不同，必须测重复值。']
], [n('What is the length of the longest strictly increasing subsequence in [3,1,2,5]?','[3,1,2,5]最长严格上升子序列长度是多少？',3,'Use 1,2,5.','使用1、2、5。','These three increase; all four do not because 3 precedes 1.','这三项递增，四项不行因为3在1之前。'),q('A blocked grid cell may retain the sum of its incoming path counts.','障碍格可以保留到达它的路径数之和。',false,'No legal path passes through it.','合法路径不能经过障碍。','Its state must be zero so it contributes no outgoing paths.','其状态必须为0，不能贡献后续路径。')]);
add('S05.03','Knapsack and resource allocation','背包与资源分配',[['Capacity state','容量状态'],['Zero-one choice','零一选择'],['Loop direction','循环方向']], [
['In zero-one knapsack, each item has a weight and value and may be taken at most once. The goal is maximum total value within capacity W. Define dp[i][c] as the best value using the first i items with capacity at most c. Including the item is possible only when its weight fits.','零一背包每项有重量和价值，至多取一次，求容量W内最大总价值。dp[i][c]表示前i项、容量不超过c的最优值；重量放得下时才可选当前项。'],
['For weight w and value v, compare skipping with taking: dp[i][c]=max(dp[i−1][c],dp[i−1][c−w]+v). Compressing away i requires iterating capacities downward, preserving the previous row’s smaller-capacity values. Upward iteration instead permits reusing the current item and solves the unbounded variant when that reuse is intended.','递推比较不选与选：dp[i][c]=max(dp[i−1][c],dp[i−1][c−w]+v)。压掉i后必须倒序容量以保持上一行；正序会复用当前物品，在允许无限件时才正确。'],
['With items (weight 2,value 3) and (weight 3,value 4), capacity five admits both, value seven. Capacity four admits only one of them, best value four. If the weight-two item is processed upward, capacity four could incorrectly reuse it twice and claim value six in the zero-one problem.','物品(重2值3)、(重3值4)，容量5可都取，总值7；容量4只能取一个，最优4。若重2物品正序更新，容量4可能错误复用两次，得到6。'],
['An at-most-capacity state often starts at zero because choosing nothing is valid. An exact-weight state instead sets unreachable weights to negative infinity and only weight zero to zero. Complexity O(nW) is pseudo-polynomial: W is a numeric magnitude, not its binary encoding length. Large capacities may favor value-based DP, sparse states, or meet-in-the-middle.','不超过容量时，空选择合法，可初始化为0。恰好重量时，只有重量0为0，其他不可达置负无穷。O(nW)为伪多项式，因为W是数值而非二进制位数；大容量可用价值DP、稀疏状态或折半。']
], [n('For items (2,3),(3,4) with capacity 5, what is the best zero-one value?','物品(重量,价值)为(2,3)、(3,4)，容量5最优值是多少？',7,'Both weights fit together.','两件重量之和正好能装下。','Weights sum to 5 and values to 7.','重量和5，价值和7。'),q('One-dimensional zero-one knapsack normally updates capacities upward.','一维零一背包通常正序更新容量。',false,'Prevent using the same item twice.','需要防止同件重复使用。','Descending updates retain the preceding item layer for every source state.','倒序更新使每个来源仍属于上一物品层。')]);
add('S05.04','Interval, tree and DAG DP','区间、树与DAG动态规划',[['Interval state','区间状态'],['Subtree state','子树状态'],['Topological evaluation','拓扑求值']], [
['DP applies whenever dependencies form an acyclic graph of states. Interval states describe contiguous subranges; tree states describe subtrees; DAG states follow a topological order. The visible input need not be a sequence. What matters is that every source state is available before the transition that consumes it.','只要状态依赖无环，就可按序DP。区间状态描述连续子段，树状态描述子树，DAG状态按拓扑序计算。输入不必是序列，关键是使用状态前其来源已算好。'],
['For matrix-chain multiplication, dp[l][r] is the cheapest way to multiply matrices l through r. Split after k, combine the two optimal subchains, and add the scalar cost determined by the endpoint dimensions. Iterate increasing interval lengths so both shorter subintervals are ready. Trying every split gives cubic time in the number of matrices.','矩阵连乘dp[l][r]表示乘完l到r最少代价。枚举断点k，合并左右最优子链，再加由端点维度决定的乘法成本。按区间长度递增计算，枚举断点使总时间立方级。'],
['For matrices of dimensions 10×30, 30×5, and 5×60, multiplying the first pair costs 1500, then the result by the third costs 3000, total 4500. Multiplying the last pair first costs 9000 then 18000, total 27000. Associativity preserves the mathematical result but not computational cost.','维度10×30、30×5、5×60，先乘前两项代价1500，再乘第三项3000，共4500；先后两项则9000加18000，共27000。结合律保持结果，却不保持计算量。'],
['Tree DP often uses postorder traversal so children are solved before parents. For a maximum-weight independent set, store separate values for selecting or excluding each vertex; selecting it forces every child excluded. A graph with cycles needs another state formulation or structural decomposition, since naive recursive dependence can loop forever.','树DP常后序处理，先孩子后父亲。最大权独立集保存选与不选节点两种状态；选父亲就强制孩子不选。含环图需要其他状态或结构分解，否则递归依赖可能永远循环。']
], [n('For the three matrix dimensions in the example, what is the better multiplication cost?','例题三矩阵较优连乘成本是多少？',4500,'Compare the two parenthesizations.','比较两种括号方案。','1500+3000=4500 is less than 27000.','1500+3000=4500，小于27000。'),q('A topological DP order requires all dependency cycles to be handled or removed.','拓扑DP要求处理或消除所有依赖环。',true,'A cycle has no first state.','环中没有可先求的状态。','Without additional mathematics, cyclic states cannot all wait for one another.','没有额外数学方法时，循环状态不能彼此等待。')]);
add('S05.05','Bitmask, digit and counting DP','状压、数位与计数动态规划',[['Subset mask','子集位掩码'],['Tight prefix','受限前缀'],['Counting multiplicity','计数重数']], [
['A bitmask stores a subset of a small universe: bit j records whether item j is present. Subset DP may additionally store an endpoint, as in shortest Hamiltonian paths. The number of masks is 2^n, so the method exploits small n rather than removing exponential complexity. Transitions must preserve the exact meaning of each state.','位掩码用第j位表示元素j是否在子集中。子集DP可额外记录终点，如最短哈密顿路径。掩码数为2^n，因此依赖n较小，而不是消除指数复杂度。转移必须保持状态含义。'],
['Digit DP counts integers bounded by a given digit string. A state tracks digit position, whether the chosen prefix still equals the bound, and relevant properties such as digit sum. A tight prefix restricts the next digit to the bound’s digit; a smaller prefix permits every digit. Leading zeros may require a separate started flag.','数位DP计数不超过给定数字串的整数，状态记录位置、前缀是否仍等于上界及数字和等性质。贴住上界时下一位受限制，已较小时可任选。前导零有时需要started标志。'],
['To count two-bit strings with exactly one set bit, start count[0][0]=1. Each position adds either zero or one to the set-bit count. After two positions, counts for zero, one, and two ones are 1,2,1. The middle value counts two distinct strings, 01 and 10, even though they share a summary state.','数两位二进制串恰有一个1，初始count[0][0]=1，每位选择0或1。两位后，含0、1、2个1的数量为1、2、1；中间2代表01与10，虽汇总状态相同仍是不同方案。'],
['Counting recurrences add mutually exclusive cases. If the same construction reaches a state through multiple descriptions, the sum overcounts. Decide whether leading-zero representations describe the same integer and whether the integer zero is included. Modular arithmetic prevents huge integer growth only when the question asks for a residue; it does not preserve probabilities or ordering automatically.','计数递推应相加互斥情况；同一对象多种描述会重计。明确前导零是否表示同一整数及是否包括零。模运算仅在要求余数时控制数值增长，不会自动保持概率和大小关系。']
], [n('How many three-bit strings contain exactly two ones?','三位二进制串恰有两个1的有多少？',3,'Choose the position of the zero.','选择唯一0的位置。','011,101,110 give three strings.','011、101、110，共三种。'),q('Merging states means that distinct counted constructions should lose their multiplicities.','合并状态意味着不同构造的数量可以丢失。',false,'The state summarizes properties, while its value records the count.','状态汇总性质，数值记录数量。','Compatible histories add their counts rather than becoming one history.','兼容历史应相加计数，而不是变成一种历史。')]);
add('S05.06','Optimization and reconstruction','优化与方案重建',[['Predecessor choice','前驱选择'],['Monotone queue','单调队列'],['Optimization precondition','优化前提']], [
['After obtaining a DP value, reconstruction recovers an actual sequence of decisions attaining it. Store a predecessor whenever a transition improves the state. Begin at the final state and follow predecessors backward, then reverse the resulting sequence if necessary. Specify a tie rule when multiple optimal solutions are permitted.','求出DP值后，重建恢复达到它的决策序列。转移改善时保存前驱，从终态反向追踪，必要时翻转序列。多个最优方案都允许时，也应规定一致的平局规则。'],
['Optimization reduces transition work only when additional structure is proved. For dp[i]=a[i]+min dp[j] over a sliding window, maintain candidate indices in a deque with increasing values. Remove expired indices from the front and dominated candidates from the back. Each index enters and leaves at most once, giving linear total deque work.','优化需要额外结构证明。若dp[i]=a[i]+滑动窗口内min dp[j]，可用按值递增的双端队列保存下标；从前端删过期项，从后端删被支配项。每项各进出一次，总工作线性。'],
['For values [5,2,4,1] and a window of length three, the first minimum is two and the second is one. When one arrives, older larger candidates cannot become the minimum before they expire, so they are discarded. Retaining indices instead of values is necessary to know when an equal-valued candidate leaves the window.','[5,2,4,1]长三窗口最小值依次为2和1。1到来后，较老较大候选到过期前都不可能最小，可舍弃。必须保存下标而不只是值，才能判断相等候选何时离开窗口。'],
['Rolling memory can destroy the predecessor information needed for reconstruction. Preserve decisions, checkpoint layers, or recompute subproblems with an explicit time-space trade-off. Convex-hull and divide-and-conquer DP optimizations have stronger algebraic or monotonicity assumptions; an observed pattern on random examples does not establish those assumptions for every legal input.','滚动内存可能破坏重建所需前驱；可存决策、检查点或重算子问题，并明确时间空间权衡。凸包与分治DP优化需要更强代数或单调性条件，随机样例中的规律不等于普遍证明。']
], [n('What is the minimum of the final length-three window in [5,2,4,1]?','[5,2,4,1]最后一个长三窗口最小值是多少？',1,'The final window is [2,4,1].','最后窗口为[2,4,1]。','Its minimum is one.','其最小值为1。'),q('A rolling value array always preserves enough information to reconstruct an optimal path.','滚动值数组总能保留足够信息重建最优路径。',false,'Past decisions may have been overwritten.','过去决策可能已覆盖。','Reconstruction needs saved predecessors or a planned recomputation method.','重建需要保存前驱或设计重算方法。')]);

adapt('S06.01','Graph representations and traversal','图的表示与遍历',[['Adjacency list','邻接表'],['DFS and BFS','深搜与广搜'],['Reachability','可达性']],['cs.graphs']);
add('S06.02','Topological order and DAG reasoning','拓扑序与有向无环图推理',[['Indegree','入度'],['Topological order','拓扑序'],['Cycle certificate','环的证据']], [
['A directed acyclic graph has no directed cycle. A topological order lists vertices so every edge points from an earlier vertex to a later one. It represents legal scheduling when an edge means one task must precede another. More than one order can satisfy the same dependency graph; the graph need not define a total order.','有向无环图没有有向环。拓扑序使每条边从较早顶点指向较晚顶点，可表示任务先后约束。相同依赖图可以有多种合法拓扑序，不必确定唯一总顺序。'],
['Kahn’s algorithm repeatedly removes a vertex of indegree zero and decrements the indegrees of its outgoing neighbors. A removed vertex has no remaining prerequisite, so appending it is safe. If vertices remain but none has indegree zero, following remaining incoming edges must eventually revisit a vertex, proving a directed cycle.','Kahn算法反复取入度0顶点，删除它并降低出边邻居入度。它已无剩余前提，可安全加入序列。如果仍有顶点却无入度0者，沿入边追踪必重访顶点，证明存在环。'],
['For edges A→C, B→C, C→D, both A and B initially have indegree zero. Either A,B,C,D or B,A,C,D is valid. The longest prerequisite chain to D has three vertices. A DP can compute completion times by taking the maximum predecessor completion plus the current task duration.','边A→C、B→C、C→D中，A和B初始入度0，A,B,C,D与B,A,C,D都合法。到D最长依赖链有三顶点；可用前驱最晚完成时间加当前工期计算完成时间。'],
['A BFS discovery order is not generally a topological order because a vertex may be discovered before another prerequisite is processed. Detect failure explicitly rather than silently outputting a partial schedule. Topological shortest-path and longest-path recurrences work with negative edge weights because acyclic dependencies prevent repeated relaxation cycles.','BFS发现序不一定是拓扑序，发现节点时其他前提可能尚未处理。必须显式报告环，不能悄悄输出部分安排。DAG最短路或最长路可处理负边，因为无环避免反复松弛依赖。']
], [n('In A→C, B→C, C→D, what is the initial indegree of C?','A→C、B→C、C→D中，C初始入度是多少？',2,'Count incoming arrows.','数指向C的箭头。','A and B each contribute one incoming edge.','A、B各贡献一条入边。'),q('Every directed graph has a topological order.','所有有向图都有拓扑序。',false,'A cycle would require each vertex to precede itself.','环会要求顶点间接先于自己。','Exactly directed acyclic graphs admit such an ordering.','恰好有向无环图才存在拓扑序。')]);
add('S06.03','Shortest paths','最短路径',[['Relaxation','松弛'],['Settled distance','已确定距离'],['Negative cycles','负环']], [
['A path cost is the sum of its edge weights. Relaxing edge u→v means replacing d[v] by min(d[v],d[u]+w) when u is reachable. Distances begin at infinity except the source, which starts at zero. Infinity is a sentinel and must not be blindly added to a weight in fixed-width arithmetic.','路径代价是边权和。松弛u→v就是在u可达时令d[v]=min(d[v],d[u]+w)。除源点为0外初始化无穷；无穷是标记，固定宽度运算中不能盲目与权值相加。'],
['BFS handles equal unit weights. Dijkstra repeatedly settles the smallest tentative distance; nonnegative weights ensure no later route can improve that settled vertex. Bellman–Ford relaxes every edge repeatedly and supports negative edges. An improvement after n−1 full rounds identifies a reachable negative cycle or its downstream effect, where finite shortest-walk values may fail to exist.','单位权用BFS。Dijkstra每次确定最小暂定距离，非负权保证以后无法改善它。Bellman–Ford反复松弛全部边，支持负边；n−1轮后仍改善说明可达负环或其影响，此时部分最短游走无有限值。'],
['For edges A→B of weight four, A→C of weight one, and C→B of weight two, initialize B=4 and C=1. Settling C relaxes B to three. Settling B then finalizes that distance. The direct edge is not always the shortest route; the route through C costs 1+2=3.','A→B权4，A→C权1，C→B权2，先得B=4、C=1。确定C后把B松弛到3，再确定B。直达边不一定最短，经C成本1+2=3。'],
['With a binary heap and adjacency lists, Dijkstra runs in O((n+m) log n) using a standard implementation. Heap entries may become stale; compare the popped distance with the current stored one. Store predecessors to recover paths, and distinguish unreachable vertices from vertices affected by a reachable negative cycle. These are different mathematical outcomes.','邻接表配二叉堆的Dijkstra通常O((n+m)log n)。堆条目可能过期，弹出时检查是否等于当前距离。保存前驱可恢复路径；不可达与受可达负环影响是不同数学结果。']
], [n('In the example, what is the shortest distance from A to B?','例题A到B最短距离是多少？',3,'Compare the direct edge with A→C→B.','比较直达与经C路径。','min(4,1+2)=3.','min(4,1+2)=3。'),q('Ordinary Dijkstra is guaranteed correct with arbitrary negative edges.','普通Dijkstra对任意负边都保证正确。',false,'Its settled-distance proof uses nonnegative weights.','确定距离的证明依赖非负权。','A later negative edge may improve an already settled vertex.','后续负边可能改善已确定顶点。')]);
add('S06.04','Minimum spanning trees','最小生成树',[['Spanning tree','生成树'],['Cut property','割性质'],['Kruskal and Prim','Kruskal与Prim']], [
['A spanning tree connects every vertex of a connected undirected graph without cycles. A minimum spanning tree minimizes the total weight of its chosen edges. It solves a network-connection objective, not shortest distances from a source. Negative edge weights are allowed because the tree constraint limits the number of selected edges.','生成树在无向连通图中无环连接全部顶点。最小生成树最小化选边总权，解决连接网络问题，不是单源最短距离。允许负边，因为树约束限制了选边数量。'],
['The cut property says a lightest edge crossing a cut that respects current chosen components can be added safely to some optimal tree. If an optimal tree lacks that edge, adding it creates a cycle; remove a no-lighter crossing edge on the cycle. Connectivity survives and total weight does not increase.','割性质：在不拆开当前已选连通块的割中，最轻跨割边可安全加入某最优树。若最优树没有它，加入后成环，删去环上另一条不更轻跨割边，保持连通且总权不增。'],
['Kruskal sorts edges and uses DSU to add only edges joining different components. For a triangle with weights one, two, and five, it adds one and two, total three; the weight-five edge would create a cycle. Prim instead grows one connected region by repeatedly taking a cheapest edge leaving that region.','Kruskal排序后用并查集只加入连接不同块的边。三角形权1、2、5，选1和2，总权3；权5会成环。Prim则从一个连通区域出发，反复选最便宜的出区域边。'],
['Kruskal takes O(m log m) time dominated by sorting. A disconnected input has a minimum spanning forest rather than one spanning tree; verify the final edge count before claiming full connectivity. Equal weights may produce several different optimal trees. Uniqueness is a separate property and must not be inferred merely from obtaining one deterministic output.','Kruskal时间O(m log m)，主要来自排序。非连通输入得到最小生成森林，声称全连通前应检查边数。相等权可能有多个最优树；算法输出确定并不证明最优树唯一。']
], [n('What is the MST weight of a triangle whose edges weigh 1,2,5?','三角形边权1、2、5，最小生成树总权是多少？',3,'Choose two edges that connect all three vertices.','选两条连接全部三个点的边。','Weights 1 and 2 suffice, totaling 3.','选1和2即连通，总权3。'),q('A minimum spanning tree necessarily preserves every source-to-vertex shortest distance.','最小生成树必然保留某源点到各点的最短距离。',false,'Its objective is the sum of chosen edge weights.','它优化选边总权。','Connecting everything cheaply differs from minimizing each individual path.','廉价连接全部点与最小化每条路径不同。')]);
add('S06.05','Connectivity, bridges and components','连通性、桥与连通分量',[['Bridge','桥'],['Low-link value','低链接值'],['Strong component','强连通分量']], [
['An undirected bridge is an edge whose removal increases the number of connected components. An articulation vertex similarly disconnects additional parts when removed. These concepts measure vulnerability of connectivity. In directed graphs, strong connectivity means that each pair can reach one another in both directions, a stricter property than weak undirected connectivity.','无向桥是删除后连通分量数增加的边；割点删除后同样造成额外分离，它们描述连通脆弱性。有向强连通要求每对顶点双向可达，比忽略方向的弱连通更强。'],
['During DFS, tin[v] records discovery time and low[v] the earliest ancestor reachable from v’s subtree using tree edges plus at most one back edge. A tree edge v→child is a bridge exactly when low[child]>tin[v]. Equality means the subtree can return to v without that tree edge, so the edge lies on a cycle.','DFS中tin[v]记录发现时间，low[v]为其子树经树边加至多一条返祖边能到达的最早祖先。树边v→child为桥当且仅当low[child]>tin[v]；等号表示可绕回v，边位于环上。'],
['Take a triangle A-B-C-A with an extra edge C-D. Triangle edges have alternate routes and are not bridges. C-D is a bridge because D becomes isolated after removal. Vertex C is an articulation point. Contracting each strongly connected component of a directed graph produces a DAG, enabling later topological analysis.','三角形A-B-C-A外接C-D，三角形每边有绕路，不是桥；C-D删除后D孤立，因此是桥，C是割点。有向图把强连通分量缩点后得到DAG，可继续拓扑分析。'],
['With parallel edges, skip the exact parent edge identifier rather than every edge leading to the parent vertex; another parallel edge is a valid alternative connection. Run DFS from every unvisited vertex on disconnected inputs. Bridge detection, articulation detection, and SCC algorithms use related timestamps but different stack and inequality rules, so their conditions are not interchangeable.','有重边时应跳过具体父边编号，而不是所有指向父顶点的边；另一条重边是合法绕路。非连通图要从每个未访问点出发。桥、割点、强连通虽都用时间戳，但栈与不等式条件不可混用。']
], [n('How many bridges are in a triangle with one pendant edge attached?','一个三角形外接一条悬挂边，共有几条桥？',1,'Only the pendant edge lacks an alternate route.','只有悬挂边无替代路线。','The three cycle edges are not bridges; the pendant edge is.','三条环边都不是桥，悬挂边是桥。'),q('Contracting strongly connected components creates an acyclic directed graph.','把强连通分量缩点后得到有向无环图。',true,'A cycle among components would make them mutually reachable.','分量间若有环就会彼此可达。','Those vertices would belong to one larger strongly connected component, contradicting maximality.','它们应属于同一更大强连通分量，与极大性矛盾。')]);
add('S06.06','Matching and network-flow introduction','匹配与网络流入门',[['Capacity and conservation','容量与守恒'],['Residual edge','残量边'],['Augmenting path','增广路']], [
['A flow network is a directed graph with nonnegative edge capacities, a source, and a sink. Feasible flow never exceeds capacity and conserves incoming and outgoing flow at other vertices. A maximum flow sends the largest possible total amount from source to sink. Capacities model simultaneous resource limits, not travel distances.','流网络是有非负容量、源点和汇点的有向图。流量不超过容量，其余点满足流入等于流出。最大流把尽可能多的总量从源送到汇；容量表示同时资源限制，不是距离。'],
['The residual graph records how the current flow can change. A forward residual edge permits extra flow; a reverse edge permits undoing previously sent flow. An augmenting path increases total flow by its smallest residual capacity. Reverse edges are essential because an early path choice may need rearrangement to reach the optimum.','残量图记录当前流如何改变：正向边允许增加，反向边允许撤销已送流。增广路按最小残量容量增加总流。反向边不可缺少，因为早先选路可能必须重新分配才能最优。'],
['For bipartite matching, connect source to every left vertex with capacity one, each allowed left-right pair with capacity one, and every right vertex to sink with capacity one. An integral unit flow selects a pair. The surrounding capacity-one edges ensure that no vertex participates in more than one selected pair.','二分匹配可令源到左点容量1，允许配对的左右边容量1，右点到汇容量1。整数单位流选中配对；两侧容量1限制每点至多参加一个配对。'],
['A cut separates source from sink; its capacity bounds every feasible flow because all sent flow must cross it. When no augmenting path remains, reachable vertices in the residual graph identify a cut whose capacity equals the flow. This proves optimality. For general integer capacities, naive augmentation count can depend on flow magnitude; algorithm choice matters.','割把源汇分开，所有流都必须跨割，所以割容量是上界。没有增广路时，残量可达点给出容量等于当前流的割，从而证明最优。整数容量下朴素增广次数可能依赖流量数值，需合理选算法。']
], [n('A path has residual capacities 5,2,7. How much flow can be augmented along it?','残量路径容量5、2、7，一次最多增广多少？',2,'The narrowest edge is the bottleneck.','最窄边是瓶颈。','Sending more than two violates the middle capacity.','超过2会违反中间边容量。'),q('Residual reverse edges mean that the original network must have had reverse edges.','残量反向边意味着原网络必有反向边。',false,'They encode the ability to undo flow.','它们表示撤销已有流的能力。','Residual reverse edges are bookkeeping operations, even when no original reverse arc exists.','即使原图无反向弧，也需要残量反向边记录撤销。')]);

add('S07.01','String representation and matching','字符串表示与匹配',[['Alphabet','字母表'],['Substring','子串'],['Naive matching','朴素匹配']], [
['An alphabet is a set of symbols, and a string is a finite ordered sequence of them. A substring uses consecutive positions; a subsequence can skip positions while preserving order. Pattern matching asks which text positions begin an occurrence of the complete pattern. Decide separately whether the empty pattern is permitted.','字母表是符号集合，字符串是其有限有序序列。子串占连续位置，子序列可跳过位置但保持顺序。模式匹配寻找完整模式出现的文本起点；空模式是否允许需单独说明。'],
['Naive matching tries every possible start and compares symbols until a mismatch or completion. For text length n and pattern length m≤n, there are n−m+1 starts and at most m comparisons per start. This gives O(nm) worst-case time, even though many ordinary inputs fail a comparison early.','朴素匹配枚举每个起点，比较直到失败或完成。文本n长、模式m≤n长时，有n−m+1个起点，每处至多m次比较，最坏O(nm)，尽管普通输入可能很早失配。'],
['In aaaaa, pattern aaa occurs at positions 0,1,2. Advancing by three after the first occurrence misses valid overlaps. A comparison unit also matters: a UTF-8 byte is not necessarily a visible character. The number of bytes, Unicode code points, and user-perceived characters can differ for the same displayed text.','aaaaa中aaa出现在0、1、2，第一次成功后跳三位会漏重叠。比较单位也重要，UTF-8字节未必是可见字符，同一显示文本的字节数、码点数和用户感知字符数可能不同。'],
['State whether matching is byte-exact, normalized Unicode, or case-insensitive. These are different problems, not implementation details to change silently. Later linear-time methods reuse comparisons while keeping the matching definition fixed. Test repeated characters, a pattern longer than the text, boundary matches, and overlaps before replacing a simple oracle with a faster implementation.','应明确字节精确、Unicode规范化还是忽略大小写，这些是不同问题，不能悄悄改变。后续线性算法在语义不变下复用比较。优化前测试重复字符、模式更长、边界和重叠，并保留简单答案程序。']
], [n('How many overlapping occurrences of aa occur in aaaa?','aaaa中可重叠的aa有多少？',3,'Check starts zero through two.','检查起点0到2。','Three starts fit a two-symbol pattern.','三个起点均容纳两字符模式。'),q('Every subsequence must be a substring.','每个子序列必是子串。',false,'A subsequence may skip a position.','子序列可以跳过位置。','ac is a subsequence of abc but is not consecutive.','ac是abc的子序列，但不连续。')]);
add('S07.02','Prefix function and KMP','前缀函数与KMP',[['Border','边界'],['Failure link','失配链接'],['Linear matching','线性匹配']], [
['A border is a proper prefix that is also a suffix. The prefix function pi[i] gives the longest border length of the prefix ending at i. Proper excludes the entire prefix itself. Borders identify which already matched characters remain useful after a mismatch, avoiding repeated comparisons with the same text positions.','边界是同时为后缀的真前缀。pi[i]给出以i结尾前缀的最长边界长度，真前缀排除整个自身。边界说明失配后哪些已匹配字符仍可利用，避免反复比较相同文本位置。'],
['Start the next prefix computation with j=pi[i−1]. While j>0 and characters differ, replace j by pi[j−1], choosing the next shorter possible border. When characters agree, increment j. Every skipped candidate is already excluded by the border structure, so fallback does not discard a potentially valid continuation.','计算下一前缀先令j=pi[i−1]。j>0且字符不同就令j=pi[j−1]转到更短边界；相等则j加一。边界结构已排除所有跳过的候选，因此不漏可能延伸。'],
['For ababa, prefix values are 0,0,1,2,3. The full pattern’s longest border is aba. After a complete match, falling back to length three preserves overlapping occurrences. KMP scans the text forward while maintaining this matched prefix length; it does not rewind the text cursor to retry each potential start.','ababa的前缀值是0、0、1、2、3，最长边界为aba。完整匹配后退到长度三可保留重叠。KMP向前扫描文本并维护已匹配前缀长度，不回退文本游标逐起点重试。'],
['The total time is O(n+m): the matched length increases at most once per processed symbol, and every fallback strictly decreases it. Distinguish pattern indices from text indices. After reporting a full match, follow its border before reading another pattern symbol; otherwise an access at the pattern length would be out of bounds.','总时间O(n+m)：每符号匹配长度至多增一，每次回退严格减少。要区分模式与文本下标；报告完整匹配后，先沿边界回退再读下一模式字符，否则会越界。']
], [n('What is the longest proper border length of ababa?','ababa最长真边界长度是多少？',3,'aba occurs at both ends.','aba同时出现在两端。','aba has length three; no longer proper prefix is also a suffix.','aba长三，没有更长真前缀也是后缀。'),q('KMP must move its text cursor backward on a mismatch.','KMP失配时必须回退文本游标。',false,'The matched pattern length changes instead.','改变的是已匹配模式长度。','Failure links reuse previous comparison information while text scanning stays forward.','失配链接复用比较信息，文本扫描保持向前。')]);
add('S07.03','Z algorithm and rolling hashes','Z算法与滚动哈希',[['Prefix match','前缀匹配'],['Z interval','Z区间'],['Collision','碰撞']], [
['Z[i] is the length of the longest string prefix matching the substring starting at i. Maintain an interval [l,r) already known to match the prefix. For a position inside that interval, previous Z values provide a safe initial match length without comparing every character again. This is structural reuse, not probabilistic guessing.','Z[i]是从i开始子串与全串前缀的最长匹配长度。维护已知匹配前缀的[l,r)，区间内位置可用旧Z值初始化，而不重比每字。这是结构复用，不是概率猜测。'],
['When i<r, begin with min(r−i,Z[i−l]), then compare beyond that initial match as needed. The right boundary only moves forward, bounding total extension work linearly. Pattern matching can use pattern plus a separator outside the alphabet plus text; a Z value at least the pattern length signals a match.','i<r时从min(r−i,Z[i−l])开始，必要时继续比较。右边界只向前，总扩展量线性。对模式、字母表外分隔符、文本的拼接求Z，达到模式长度即匹配。'],
['A rolling polynomial hash uses H=Σc[i]B^(k−1−i) modulo M. With digits 1,2,3, base ten, and modulus 101, the result is 22. Prefix hashes and precomputed powers obtain a substring hash by removing the earlier prefix’s shifted contribution, enabling fast repeated substring comparisons after preprocessing.','滚动多项式哈希H=Σc[i]B^(k−1−i) mod M。数字1、2、3取底10、模101，得22。前缀哈希与预计算幂可减掉先前前缀的移位贡献，预处理后快速比较子串。'],
['Equal hashes do not prove equal strings: a finite hash range cannot encode every possible string uniquely. Several moduli or randomized bases reduce collision risk under stated assumptions. Exact results need verification or a deterministic method. Modular multiplication must avoid invalid intermediate signed overflow, even when the final reduced residue fits the chosen type.','哈希相等不证明串相等，有限范围无法唯一编码所有串。多模数或随机底数在条件下减少风险。精确结果需复核或确定算法；即使最终余数可表示，中间模乘也必须避免有符号溢出。']
], [n('What is Z[2] for ababa?','ababa的Z[2]是多少？',3,'The suffix from index two is aba.','下标2开始的后缀是aba。','It agrees with the first three symbols.','它与前三个字符一致。'),q('A rolling-hash collision is impossible for arbitrary strings.','任意字符串都不可能发生滚动哈希碰撞。',false,'Compare the finite range with the unbounded input set.','比较有限输出和无限输入集合。','Different strings can map to the same residue, so equality is not a proof.','不同串可映射为同一余数，因此相等不是证明。')]);
add('S07.04','Tries and Aho-Corasick','字典树与AC自动机',[['Shared prefix','共享前缀'],['Failure suffix','失配后缀'],['Output reporting','输出报告']], [
['A trie stores many strings by sharing common prefixes. Every edge adds a symbol, and terminal marks indicate complete stored patterns. A terminal node may have descendants because one word can prefix another. Searching a stored word follows its symbols from the root and checks the final terminal mark.','字典树通过共享前缀保存多个串，每条边增加符号，终止标记表示完整模式。终止点仍可有后代，因为一个词可为另一个词的前缀。查词沿字符从根走并检查末点标记。'],
['Aho–Corasick adds failure links to the longest proper suffix that is also a trie prefix. Construct links breadth-first so shorter suffix information is ready. During text scanning, mismatches follow failure links until a usable transition appears or the root is reached. Output links or accumulated terminal information report suffix patterns as well.','AC添加到最长真后缀且为字典树前缀的失配链接。按广搜建立，保证短后缀信息已就绪。失配时沿链接找到可转移处或根；输出链接或终止信息累积还需报告后缀模式。'],
['For patterns he, she, hers, scanning ushers reaches the end of she. The failure chain also exposes he ending at the same position. Continuing the scan finds hers. Reporting only the current node’s pattern would miss he, while discarding the active suffix after she would obstruct the later longer continuation.','he、she、hers匹配ushers，到she末点时失配链也显示同位置结束的he，继续可找到hers。只报告当前节点会漏he；she后丢弃活动后缀又可能妨碍后续延伸。'],
['Dense transition tables use nodes times alphabet-size storage; sparse maps save space but add lookup costs. Reporting all matches requires time proportional to the number reported, which may exceed text length greatly. Duplicate inserted patterns need an explicit counting policy. Separate transition-processing time from output cost when analyzing the algorithm’s total complexity.','稠密转移表空间为节点数乘字母表大小，稀疏映射省空间但增加查询代价。全部输出耗时至少与匹配数成正比，可能远超文本长。重复模式需明确计数政策，复杂度应区分转移与输出。']
], [n('How many patterns among he, she, hers occur in ushers?','he、she、hers中多少个出现在ushers？',3,'Allow overlapping matches.','允许重叠匹配。','All three occur, with he and she sharing an ending position.','三者均出现，he与she结束位置相同。'),q('A trie terminal node must always be a leaf.','字典树终止节点总是叶子。',false,'A word can be a prefix of another word.','一个词可为另一词前缀。','he is terminal even if descendants spell hers.','即使后代拼出hers，he节点仍是终止点。')]);
add('S07.05','Suffix arrays and LCP','后缀数组与最长公共前缀',[['Suffix order','后缀序'],['Rank doubling','排名倍增'],['Adjacent LCP','相邻LCP']], [
['A suffix array lists suffix starting indices in lexicographic order. Each suffix is the complete tail from its starting position. Suffixes beginning with a fixed pattern occupy one contiguous interval, enabling binary searches for occurrences. The array stores positions; it need not copy every suffix, which would require quadratic total character storage.','后缀数组按字典序列出后缀起点，每个后缀为起点后的完整尾部。同模式开头的后缀占连续区间，可二分查询。只存位置，不必复制所有后缀，否则字符总空间为二次。'],
['Doubling ranks substrings of lengths one, two, four, and onward. A length-2k substring is described by ranks of its two k-length halves, with a special smaller rank beyond the end. Sorting these pairs refines the order until complete suffixes are distinguished. Efficient rank-pair sorting determines the construction’s precise running time.','倍增给长1、2、4等子串排名，长2k由两个k半段排名描述，越界用更小特殊排名。排序排名对不断细化直到区分后缀；排名对排序方法决定具体复杂度。'],
['For banana, suffix order is [5,3,1,0,4,2]: a, ana, anana, banana, na, nana. Adjacent LCP lengths are 1,3,0,0,2. There are 21 positional nonempty substrings, but subtracting repeated-prefix contributions gives 21−6=15 distinct substrings. Each new suffix contributes only prefixes longer than its LCP with its predecessor.','banana后缀序[5,3,1,0,4,2]对应a、ana、anana、banana、na、nana，相邻LCP为1、3、0、0、2。按位置非空子串21个，减重复前缀6后不同子串15个；新后缀只贡献超过前驱LCP的前缀。'],
['The LCP of two suffixes equals the minimum adjacent LCP across the interval between their ranks. This reduces repeated common-prefix queries to range minima. A linear LCP algorithm reuses the fact that dropping one initial character decreases a known common prefix by at most one. Keep string positions separate from suffix ranks throughout every index calculation.','两后缀LCP等于其排名区间相邻LCP最小值，因此转成区间最小查询。线性LCP算法利用去掉首字符使已知公共前缀至多减一。所有下标计算都要区分原串位置和后缀排名。']
], [n('How many distinct nonempty substrings does banana have?','banana有多少不同非空子串？',15,'Subtract the adjacent LCP sum from 21.','用21减相邻LCP之和。','21−(1+3+0+0+2)=15.','21−(1+3+0+0+2)=15。'),q('Suffixes sharing a fixed prefix form a contiguous suffix-array block.','共享固定前缀的后缀在后缀数组中连续。',true,'Apply lexicographic comparison at the first differing symbol.','看字典序首次不同的字符。','A different earlier prefix cannot fall between two suffixes with the full common prefix.','较早字符已不同的后缀不能夹在完整共享前缀的两者间。')]);
add('S07.06','Suffix automata and string problem synthesis','后缀自动机与字符串综合',[['End-position class','结束位置类'],['Suffix link','后缀链接'],['Substring counting','子串计数']], [
['A suffix automaton groups substrings with identical sets of ending positions in the text. One state can represent several substring lengths. Its maximum length is len[v], while its suffix link points toward the next shorter ending-position class. Character transitions extend represented substrings and permit recognition of every substring starting from the initial state.','后缀自动机把文本中结束位置集合相同的子串归类。状态可表示多个长度，最大为len[v]，后缀链接指向下一较短结束位置类。字符转移延长子串，从初态可识别所有子串。'],
['A noninitial state represents lengths len[link[v]]+1 through len[v]. Therefore it contributes len[v]−len[link[v]] distinct substrings. Online extension adds transitions along suffix links. When one class would incorrectly combine incompatible length ranges, cloning splits it while preserving existing accepted paths; the clone is structural, not a newly observed text ending.','非初态表示len[link[v]]+1至len[v]，贡献两者差个不同子串。在线扩展沿后缀链接补转移；若类错误混合长度范围，就克隆拆分并保持旧路径。克隆是结构调整，不是新增文本结束位置。'],
['In aba, distinct nonempty substrings are a,b,ab,ba,aba, giving five. To test a query pattern, follow its characters from the initial state; a missing transition rejects it. To count occurrences, initialize direct ending contributions and propagate them through suffix links from longer states to shorter states, so suffix occurrences accumulate correctly.','aba不同非空子串是a、b、ab、ba、aba，共五个。查询从初态沿字符走，缺转移即不存在。计出现次数时初始化直接结束贡献，再按长度递减沿后缀链接累加，使后缀正确接收次数。'],
['For a fixed alphabet, automaton size and construction work are linear; associative containers introduce their own lookup costs. Choose the simplest sufficient tool: KMP for one pattern, Aho–Corasick for many patterns, suffix structures for many substring queries. Their similarly named links encode different equivalence relations, so construction rules and correctness arguments cannot be exchanged casually.','固定字母表下规模和建造线性，关联容器另有查询代价。单模式可选KMP、多模式AC、大量子串查询用后缀结构。相似名称的链接编码不同等价关系，不能随意交换构造与证明。']
], [n('How many distinct nonempty substrings does aba have?','aba有多少不同非空子串？',5,'List lengths one, two, and three.','按长度一、二、三列举。','Two one-letter, two two-letter, and one three-letter substring give five.','一字两种、两字两种、三字一种，共五种。'),q('Each suffix-automaton state represents exactly one substring length.','后缀自动机每状态恰代表一个长度。',false,'Its represented lengths form an interval.','它代表一个长度区间。','The interval can contain several lengths with the same ending-position set.','相同结束位置集合的区间可含多个长度。')]);


adapt('S08.01','Modular arithmetic and safe implementation','模运算与安全实现',[['Residue','剩余类'],['Inverse','逆元'],['Overflow','溢出']],['cs.modular'],[['Binary exponentiation squares a power repeatedly and multiplies it into the answer for each set exponent bit, using O(log k) multiplications for exponent k. An inverse of a modulo m exists exactly when gcd(a,m)=1. Normalize negative remainders, and use sufficiently wide intermediate products; a final small residue does not make an overflowing multiplication valid.','快速幂反复平方，在指数位为1时乘入答案，指数k需O(log k)次乘法。a模m逆元存在当且仅当gcd(a,m)=1。负余数需规范化，中间乘积要足够宽，最终余数小不能使溢出合法。']]);
add('S08.02','Sieves, arithmetic functions and inversion','筛法、算术函数与反演',[['Prime sieve','素数筛'],['Totient','欧拉函数'],['Möbius inversion','莫比乌斯反演']], [
['The sieve of Eratosthenes crosses out multiples of each unmarked prime. Starting at p² is sufficient because smaller multiples have already met a smaller prime factor. A table through N supports queries only inside its proved range; it is not a universal primality test for larger inputs.','埃氏筛划去未标记素数的倍数，从p²开始即可，因为更小倍数已遇到更小素因子。筛到N只支持证明范围内查询，并非任意大数素性测试。'],
['Euler’s phi(n) counts integers from one through n coprime to n. Its formula is n∏(1−1/p) over distinct prime divisors. The Möbius function mu is zero when a prime square divides n; otherwise it is (−1)^k for k distinct prime factors, with mu(1)=1.','φ(n)统计1到n中互素者，公式为不同素因子上的n∏(1−1/p)。含素数平方因子时μ(n)=0，否则为(−1)^k，k是不同素因子数，μ(1)=1。'],
['For twelve, phi(12)=12×(1/2)×(2/3)=4, corresponding to 1,5,7,11. Also mu(12)=0 because four divides twelve, whereas mu(6)=1. Multiplicativity means f(ab)=f(a)f(b) only for coprime a and b; applying it without that condition gives incorrect values even for small integers.','φ(12)=12×1/2×2/3=4，对应1、5、7、11；μ(12)=0，因为4整除12，而μ(6)=1。积性仅在a、b互素时保证f(ab)=f(a)f(b)，缺条件会算错。'],
['If F(n)=Σd|n f(d), inversion gives f(n)=Σd|n mu(d)F(n/d). Expanding and regrouping works because the divisor sum of mu equals one at n=1 and zero otherwise. Preserve the divisor relation carefully: a sum over divisors is different from a sum over all smaller integers or a prefix-sum array.','若F(n)=Σd|n f(d)，则f(n)=Σd|n μ(d)F(n/d)。展开重组利用μ的约数和：n=1为1，否则为0。约数和不同于对所有较小整数求和，不能误换成前缀和。']
], [n('What is phi(12)?','φ(12)是多少？',4,'List the coprime integers.','列出互素整数。','1,5,7,11 give four.','1、5、7、11共四个。'),n('What is mu(18)?','μ(18)是多少？',0,'Nine divides eighteen.','9整除18。','A squared prime factor forces zero.','含素数平方因子，所以为0。')]);
add('S08.03','Combinatorial counting and generating functions','组合计数与生成函数',[['Counting rules','计数原理'],['Coefficient encoding','系数编码'],['Convolution','卷积']], [
['Define precisely which objects are distinct and whether order matters. Add counts for disjoint alternatives and multiply counts for successive choices with fixed continuation counts. A generating function stores a sequence as coefficients of powers of a formal variable. It is an algebraic record, not necessarily a function requiring numerical evaluation.','先定义对象如何区分、顺序是否重要。互斥方案相加，后续数量固定的连续选择相乘。生成函数把序列存为形式变量幂的系数，是代数记录，不一定需要数值代入。'],
['An item of weight w usable once contributes the factor 1+x^w, representing omission or inclusion. Multiplying factors combines choices; the coefficient of x^t counts subsets of total weight t. Unlimited indistinguishable copies contribute 1+x^w+x^(2w)+… instead. Changing this factor changes the combinatorial model, not merely an optimization.','重量w至多一次对应1+x^w，分别表示不选与选。乘因子组合选择，x^t系数数总重t的子集。无限不可区分副本对应1+x^w+x^(2w)+⋯；改变因子就是改变计数模型。'],
['For weights one, two, three, the product (1+x)(1+x²)(1+x³) has x³ coefficient two. One contribution chooses the weight-three item; another chooses one and two. Polynomial coefficient multiplication is convolution, the same operation used by a counting DP when combining independently chosen groups with additive totals.','重量1、2、3的积(1+x)(1+x²)(1+x³)中x³系数为2，来自选3或选1和2。系数乘法就是卷积，也是计数DP合并独立组、累加总量时的操作。'],
['Binomial coefficients satisfy C(n,k)=C(n−1,k)+C(n−1,k−1), partitioning subsets by whether they contain a distinguished item. Modular factorial division requires invertible denominators and may fail for composite moduli. An integer recurrence avoids that issue. Implemented formal series must also specify truncation so discarded degrees cannot later influence any coefficient being requested.','按是否含指定元素分割得C(n,k)=C(n−1,k)+C(n−1,k−1)。模阶乘除法要求分母可逆，合数模可能失败，整数递推可避免。实现幂级数还需指定截断，保证丢掉高次不会影响所求系数。']
], [n('What is the x³ coefficient in (1+x)(1+x²)(1+x³)?','该乘积的x³系数是多少？',2,'Find subsets totaling three.','找总和3的子集。','{3} and {1,2} each contribute one.','{3}和{1,2}各贡献1。'),q('Division modulo every positive modulus is always valid.','任意正整数模数下除法总合法。',false,'Check whether the divisor has an inverse.','检查除数是否有逆元。','A divisor sharing a factor with the modulus is not invertible.','除数与模数有公因子时不可逆。')]);
add('S08.04','Matrices, recurrences and linear bases','矩阵、递推与线性基',[['Transition matrix','转移矩阵'],['Matrix powers','矩阵幂'],['XOR span','异或张成']], [
['A linear recurrence can be encoded as a state vector transformed by a matrix. Fibonacci updates [F(n),F(n−1)] to [F(n)+F(n−1),F(n)] using rows [1,1] and [1,0]. The state must contain every quantity needed for the next update; missing history cannot be repaired by matrix multiplication alone.','线性递推可编码为矩阵变换状态向量。矩阵行[1,1]和[1,0]把[F(n),F(n−1)]变为[F(n)+F(n−1),F(n)]。状态必须包含下一更新全部信息，缺少历史不能靠矩阵自动补救。'],
['Exponentiation by squaring computes the nth power in O(log n) matrix multiplications. Elementary dense multiplication costs O(k³) for dimension k. Multiplication order matters because matrices generally do not commute. Include auxiliary sums as additional coordinates when they themselves update linearly, and choose the identity matrix as the zero-power base case.','快速幂用O(log n)次矩阵乘法求n次幂，普通k维乘法O(k³)。矩阵通常不交换，顺序重要。若辅助和也线性更新可增加坐标，零次幂以单位矩阵为基。'],
['An XOR linear basis treats bit vectors as vectors over the two-element field. Eliminate the highest set bit with an existing pivot; retain a remaining new pivot as independent. For 3=011 and 5=101, their XOR equals 6=110. Thus adding six to these two vectors does not increase rank.','异或线性基把位向量当二元域向量，用已有主元消最高1位，剩新主元才独立。3=011与5=101异或为6=110，所以加入6不增加秩。'],
['A rank-r XOR span contains 2^r distinct vectors, including zero. This uses XOR, not ordinary integer addition. A basis supports representation and optimization tasks only after its pivot invariant is established. Nonlinear recurrences, such as squaring the preceding value, do not automatically become linear by choosing a larger matrix without a closed finite state representation.','秩r的异或空间有2^r个向量，包括零，运算是异或而非整数加法。必须建立主元不变量才可表示或优化。前项平方等非线性递推，若无封闭有限状态，不能随意用大矩阵线性化。']
], [n('What is the XOR rank of {3,5,6}?','{3,5,6}的异或秩是多少？',2,'3 XOR 5 is 6.','3异或5等于6。','Only two vectors are independent.','只有两个向量独立。'),n('How many vectors belong to a rank-three XOR span?','秩3异或空间有多少向量？',8,'Each coefficient is zero or one.','每系数为0或1。','2^3=8 independent coefficient choices produce distinct vectors.','2^3=8种独立系数选择对应不同向量。')]);
add('S08.05','Polynomial convolution, FFT and NTT','多项式卷积、FFT与NTT',[['Convolution','卷积'],['Evaluation','求值'],['Roots of unity','单位根']], [
['Polynomial multiplication yields c[k]=Σa[i]b[k−i], called convolution. Each coefficient pair contributes to the sum of its degrees. Direct multiplication is quadratic for equal-length arrays. Evaluating both polynomials at sufficiently many distinct points turns the multiplication into pointwise products; interpolation then recovers the coefficient representation.','多项式乘法得到卷积c[k]=Σa[i]b[k−i]，系数对贡献于次数之和。等长数组直接乘为二次时间。足够多不同点求值后逐点相乘，再插值恢复系数。'],
['FFT evaluates at structured complex roots of unity by recursively splitting even and odd coefficients. NTT uses corresponding roots in a finite field for exact modular operations. Under prime modulus p, transform length L must divide p−1 and the chosen root must have exact order L. Not every convenient modulus supports every length.','FFT在复单位根上按奇偶系数递归求值，NTT在有限域对应根上精确模运算。素数模p下L须整除p−1，根的阶须恰为L。并非任意模数都支持任意长度。'],
['Multiplying (1+2x)(3+4x) gives coefficients [3,10,8]. The transform length must be at least three, commonly padded to four. Without enough zeros, high-degree coefficients wrap around through cyclic convolution. The inverse transform reverses the root direction and includes multiplication by the inverse of the transform length in the modular setting.','(1+2x)(3+4x)得[3,10,8]，变换长度至少3，常补到4。不足补零会让高次系数经循环卷积绕回。逆变换反向用根，并在模环境乘以长度的逆元。'],
['Complex FFT introduces rounding error, so rounding back to integers needs a justified precision bound. NTT returns residues, not unrestricted integer coefficients. Exact large-integer reconstruction may need several compatible moduli with a product exceeding the coefficient bound. Both approaches still require safe intermediate multiplication and explicit treatment of input length, padding, and normalization.','复FFT有舍入误差，恢复整数需精度界。NTT只返回余数，不是无限整数系数；精确恢复大系数可能需要多个兼容模数，乘积超过系数界。二者都要安全中间乘法并明确长度、补零和归一化。']
], [n('What is the coefficient of x in (1+2x)(3+4x)?','乘积的x系数是多少？',10,'Add cross products.','相加交叉乘积。','1×4+2×3=10.','1×4+2×3=10。'),q('Insufficient padding can cause cyclic convolution to alias coefficients.','补零不足可能使循环卷积混叠系数。',true,'High degrees wrap modulo transform length.','高次按变换长度绕回。','Padding to at least the ordinary product length prevents this overlap.','补到至少普通乘积长度可防止重叠。')]);
add('S08.06','Probability, games and mathematical synthesis','概率、博弈与数学综合',[['Expectation','期望'],['Winning state','必胜态'],['Grundy number','SG值']], [
['Expected value is a probability-weighted sum of numerical outcomes. Linearity says E(X+Y)=E(X)+E(Y) whenever expectations exist, even if variables are dependent. Indicator variables, equal to one when an event occurs and zero otherwise, turn a complicated count into a sum whose expectation can often be calculated term by term.','期望是结果按概率加权的和。存在期望时E(X+Y)=E(X)+E(Y)，不要求独立。事件发生为1否则为0的指示变量，可把复杂计数变为逐项求期望的和。'],
['In finite impartial normal-play games, both players have the same available moves and a player with no move loses. A state is winning if some move reaches a losing state; it is losing if every move reaches a winning state. This recursion requires termination, usually ensured by a strictly decreasing resource.','有限无偏正常玩法中双方操作相同，无步可走者输。可一步到必败则当前必胜；所有步到必胜则当前必败。递推要求终止，通常用严格递减资源保证。'],
['If each move removes one or two stones, zero is losing, one and two are winning, and three is losing. Induction makes every multiple of three losing. In a separate probability example, two fair coin tosses have expected one head because the two indicators each contribute one-half, regardless of how their expectations are added.','每次拿一或两石，0必败，1和2必胜，3必败；归纳得3的倍数必败。另看两次公平抛硬币，每次正面指示变量期望1/2，总正面数期望1。'],
['The Grundy number of an impartial terminating state is the mex, the smallest absent nonnegative integer, of successor values. Independent component games combine by XOR. Partisan moves, reversed winning rules, and cyclic games need different analysis. Always translate the actual move and ending rules before applying a remembered Nim formula or probabilistic shortcut.','终止无偏状态的SG值为后继值的mex，即最小未出现非负整数；独立分量用异或合并。双方不同操作、反常胜负和含环游戏需另析。套Nim公式或概率捷径前，必须先翻译真实规则。']
], [n('What is mex({0,1,3})?','mex({0,1,3})是多少？',2,'Find the smallest missing nonnegative integer.','找最小未出现非负整数。','Zero and one occur; two is absent.','0、1出现，2缺失。'),n('What is the expected number of heads in four fair tosses?','四次公平抛硬币，正面数期望多少？',2,'Add four one-half expectations.','相加四个1/2。','4×1/2=2 by linearity.','由线性性4×1/2=2。')]);

add('S09.01','Advanced DP optimization','进阶动态规划优化',[['Transition geometry','转移几何'],['Monotone optimum','决策单调性'],['Li Chao tree','李超线段树']], [
['An expensive DP often minimizes expressions over earlier states. Before optimizing, write the exact recurrence and separate terms depending only on the new state from terms depending on a candidate predecessor. Algebra can reveal geometric structure, but only if the coefficients and query order satisfy the method’s preconditions.','昂贵DP常对前驱取最小。优化前写精确递推，分离仅依赖新状态和依赖候选前驱的项。代数可揭示几何结构，但系数与查询顺序必须满足方法前提。'],
['For dp[i]=min over j<i of dp[j]+(x[i]−x[j])², expand the square. The term x[i]² is independent of j; each predecessor supplies the line y=−2x[j]t+dp[j]+x[j]², queried at t=x[i]. Maintaining the lower envelope replaces scanning every predecessor with a line-query data structure.','dp[i]=minj<i{dp[j]+(x[i]−x[j])²}展开后，x[i]²与j无关，前驱提供直线y=−2x[j]t+dp[j]+x[j]²，在t=x[i]查询。维护下包络替代枚举全部前驱。'],
['Lines y=2t+1 and y=−t+7 intersect at t=2. At t=1, the first gives three and wins; at t=4, the second gives three and wins. A Li Chao tree exploits that two lines change their relative order at most once, retaining the better midpoint line and recursing where the other may improve.','y=2t+1与y=−t+7在t=2相交。t=1时前者值3更优，t=4时后者值3更优。李超树利用两线相对次序至多变一次，保留中点较优线，另一条递归到可能改善的区间。'],
['Deque convex-hull methods may require monotone slopes and queries; Li Chao variants require a specified query domain. Divide-and-conquer DP needs monotone optimal split positions, often derived from a quadrangle inequality. Test an optimized recurrence against the quadratic version, but keep the structural proof: passing random cases does not establish monotonicity.','队列凸包法可能要求斜率和查询单调，李超树需指定查询域。分治DP需最优断点单调，常由四边形不等式推出。应与平方算法对拍，但随机通过不能替代结构证明。']
], [n('At t=4, what is min(2t+1,−t+7)?','t=4时min(2t+1,−t+7)是多少？',3,'Evaluate both lines.','分别代入。','The values are nine and three.','两值为9和3。'),q('Observed optimal-index monotonicity on a few inputs proves a DP optimization valid.','少数输入的决策单调现象足以证明优化。',false,'A theorem must cover all permitted inputs.','定理需覆盖全部合法输入。','A counterexample outside the sample can invalidate the optimized search range.','样本外反例可使缩小的搜索范围漏解。')]);
add('S09.02','Flow, cuts and matching','网络流、割与匹配',[['Level graph','分层图'],['Blocking flow','阻塞流'],['Residual optimality','残量最优性']], [
['A maximum-flow algorithm searches the residual graph, where reverse edges represent undoing earlier choices. Dinic first uses BFS to assign residual distances from the source, then keeps edges advancing exactly one level. This level graph is acyclic with respect to levels, enabling structured depth-first flow pushes.','最大流在残量图上搜索，反向边代表撤销旧选择。Dinic先BFS分层，只保留前进一层的边；层次使图按层无环，可有序深搜推流。'],
['A blocking flow saturates at least one edge on every source-to-sink path in the current level graph. Afterward, any remaining augmenting path has greater level distance. Current-edge pointers avoid repeatedly revisiting edges already proved unable to send more flow in that phase. Capacity integrality guarantees an integral result from integral augmentations.','阻塞流使当前分层图每条源汇路至少一边饱和，此后剩余增广路层数增加。当前弧指针避免本阶段反复访问已无法推流的边。整数容量配整数增广保证整数结果。'],
['In bipartite matching, source-left and right-sink capacities one enforce unique partners. An alternating path switches unmatched and matched edges, increasing matching size by one. If a greedy match chose L1-R1 while L2 only allows R1 and L1 also allows R2, the path rearranges to L1-R2 and L2-R1, reaching size two.','二分匹配两侧容量1限制唯一配偶。交错路切换未匹配与匹配边，规模增一。若贪心选L1-R1，而L2只可R1、L1还可R2，则重排为L1-R2、L2-R1，得到规模2。'],
['The max-flow min-cut theorem certifies optimality, but reductions need their own proof that feasible objects correspond to flows. Lower bounds on edges require demand balancing before ordinary maximum flow. Min-cost flow adds a cost objective and must handle residual negative costs correctly. A large artificial capacity should exceed a proved feasible bound without overflowing its storage type.','最大流最小割给最优证书，但归约还要证明对象与流对应。有下界需先平衡需求；最小费用流另有费用目标并须正确处理残量负费用。人为大容量应超过证明的可行界且不溢出。']
], [n('In the worked two-left-vertex matching example, what is the maximum matching size?','例题两个左点的最大匹配规模是多少？',2,'Reassign L1 to R2.','将L1改配R2。','Then L2 uses R1, matching both left vertices.','L2再配R1，两个左点均匹配。'),q('A blocking flow must already be a maximum flow in the entire residual network.','阻塞流必是整个残量网络的最大流。',false,'It blocks only the current level graph.','它只阻塞当前分层图。','Longer residual augmenting paths can remain for later phases.','后续阶段仍可能存在更长增广路。')]);
add('S09.03','Tree decompositions and dynamic trees','树分解与动态树',[['Heavy path','重链'],['Path aggregation','路径聚合'],['Dynamic forest','动态森林']], [
['Heavy-light decomposition converts tree paths into a small number of array intervals. At each vertex, designate a largest-subtree child as heavy; other child edges are light. Moving down a light edge at least halves the remaining subtree size, so any root-to-vertex path crosses only O(log n) light edges.','重链剖分把树路径变为少量数组区间。每点选最大子树孩子为重儿子，其余边轻。向下过轻边子树规模至少减半，所以根到点至多O(log n)条轻边。'],
['Assign consecutive positions along each heavy chain and use a segment tree for interval aggregates. To query a path, repeatedly process the endpoint whose chain head is deeper, then move that endpoint to the head’s parent. Once both endpoints share a chain, one final interval completes the path query.','沿重链连续编号，用线段树维护区间聚合。查询路径时反复处理链头更深的一端，再跳到链头父亲；两端同链后用最后一个区间完成查询。'],
['For an additive vertex-weight path, add each disjoint chain interval exactly once. With O(log n) intervals and O(log n) segment queries, the total is O(log² n). Noncommutative aggregates, such as matrix products along a directed path, need separate forward and backward summaries so climbing from opposite endpoints does not reverse the intended order.','点权路径和把不交链区间各加一次，O(log n)区间乘O(log n)查询，总O(log² n)。矩阵乘积等不交换聚合需保存正反方向，避免两端向上跳时颠倒路径顺序。'],
['Heavy-light decomposition assumes a fixed tree structure unless rebuilt. Link-cut trees maintain changing forests through auxiliary splay trees and support link, cut, and path operations with amortized logarithmic bounds. Their preferred paths and lazy reversal tags require careful invariants. A cycle-creating link is invalid for a forest representation and must be detected or excluded by the operation contract.','重链剖分默认树结构固定，改变需重建。Link-cut tree用辅助伸展树维护动态森林，link、cut、路径操作均摊对数。首选路径和翻转标记需严谨不变量；形成环的link不符合森林约定。']
], [n('If a path crosses four chains and each range sum is 3,5,2,7, what is its total?','路径四段链区间和为3、5、2、7，总和多少？',17,'The intervals are disjoint.','区间互不交叠。','3+5+2+7=17.','3+5+2+7=17。'),q('Ordinary heavy-light numbering stays valid under arbitrary tree-edge changes.','普通重链编号在任意改树边后仍有效。',false,'Subtrees and heavy choices depend on the original tree.','子树与重儿子依赖原树。','Structural changes can invalidate decomposition and require rebuilding or a dynamic-tree structure.','结构变化可能使剖分失效，需要重建或动态树。')]);
add('S09.04','Persistent and offline data structures','可持久化与离线数据结构',[['Path copying','路径复制'],['Offline ordering','离线排序'],['Rollback','回滚']], [
['Persistence preserves access to earlier versions after updates. A persistent segment tree copies only nodes along an updated root-to-leaf path and shares unchanged subtrees. Each version keeps its own root. Because shared nodes are immutable, changing a new version cannot alter the answers observed through an older root.','可持久化在更新后仍访问旧版本。持久线段树只复制更新的根到叶路径，未变子树共享，每版本保存根。共享节点不可变，因此新版本不会改变旧根查询。'],
['A point update creates O(log n) nodes, so m updates use O(n+m log n) total storage after an initial full tree. Offline algorithms instead exploit knowing all queries in advance. Sorting by an endpoint, value, or time can transform difficult online updates into monotone additions handled by a simpler data structure.','单点更新新建O(log n)节点，m次更新加初始树用O(n+m log n)空间。离线算法利用预先知道全部查询，按端点、值或时间排序，可把复杂在线变化转为简单单调加入。'],
['For prefix versions of a frequency tree, version r minus version l−1 gives value counts in array interval [l,r]. To find its kth smallest value, inspect the left-child count difference; descend left if it is at least k, otherwise subtract it and descend right. Each descent halves the value domain.','频次树前缀版本r减l−1给出数组[l,r]的值频次。查第k小时，看左孩子计数差，若至少k则向左，否则减掉该数后向右；每步把值域减半。'],
['Rollback DSU records changed parents and sizes on a stack, then undoes them when leaving a time-segment recursion. Ordinary path compression makes rollback complicated, so implementations often use union by size without compression. Persistence, rollback, and offline sorting solve related historical-query tasks but provide different access patterns and memory guarantees. Choose from the actual query contract.','回滚并查集把父亲和大小改动压栈，离开时间线段递归时撤销。路径压缩使回滚复杂，常只按大小合并而不用压缩。持久化、回滚、离线排序访问历史的模式和内存保证不同，应按查询约定选择。']
], [n('An interval has two values in its left value-half. For k=5, what rank is sought in the right half?','区间左半值域有2项，查第5小时右半应查第几小？',3,'Skip the two left-half values.','跳过左半两项。','5−2=3.','5−2=3。'),q('Mutating a node shared by old persistent versions preserves those versions.','修改旧版本共享节点能保持旧版本不变。',false,'Every sharing root observes that node.','所有共享根都能看到该节点。','Persistence requires copying changed nodes rather than altering shared historical state.','持久化必须复制变动节点，而非改共享历史。')]);
add('S09.05','Computational geometry and randomized methods','计算几何与随机化方法',[['Orientation','方向判定'],['Geometric degeneracy','几何退化'],['Randomized guarantee','随机保证']], [
['For points A,B,C, the two-dimensional cross product (B−A)×(C−A) determines orientation: positive for a counterclockwise turn, negative for clockwise, zero for collinearity. This predicate supports segment intersection, convex hulls, and polygon area. Coordinates are numbers, but orientation is a discrete decision that can change an algorithm’s entire structure.','三点方向由(B−A)×(C−A)判断，正为逆时针、负为顺时针、零为共线。它支持交段、凸包与面积。坐标虽是数，方向却是影响全算法结构的离散判断。'],
['The monotone-chain convex hull sorts points, then removes the last hull vertex while the newest triple violates the required turn. Each point enters and leaves each chain at most once, giving linear scan work after O(n log n) sorting. Decide whether collinear boundary points should be kept, because strict and nonstrict turn tests differ.','单调链凸包先排序，若新三点不满足转向要求则删除最后顶点。每点各进出一次，排序O(n log n)后扫描线性。必须决定是否保留边界共线点，严格与非严格判定不同。'],
['For A=(0,0), B=(2,0), C=(1,3), the cross product is six, so the turn is counterclockwise and triangle area is three. Integer coordinates allow exact predicates if products fit a sufficiently wide type. Floating coordinates require scale-aware robustness, not a universal epsilon pasted into every comparison.','A=(0,0)、B=(2,0)、C=(1,3)，叉积6，为逆时针，三角形面积3。整数可在足够宽类型下精确判断；浮点需要考虑尺度稳健性，不能每个比较都机械塞同一epsilon。'],
['Randomized algorithms use random choices to obtain a stated probability or expected-time guarantee. A Las Vegas algorithm always returns a correct result but has random running time; a Monte Carlo algorithm can err with bounded probability. Save random seeds for reproduction, and distinguish a distribution-independent guarantee from performance observed on one favorable random input family.','随机算法用随机选择获得概率或期望时间保证。Las Vegas结果总正确但时间随机，Monte Carlo可能有有界错误概率。保存种子便于复现，并区分理论保证与某类有利随机输入上的实测。']
], [n('What is the triangle area for (0,0),(2,0),(1,3)?','三点(0,0)、(2,0)、(1,3)面积是多少？',3,'Area is half the absolute cross product.','面积是叉积绝对值一半。','The cross product is six, so area is three.','叉积6，所以面积3。'),q('A Las Vegas algorithm may return a wrong result with small probability.','Las Vegas算法可能以小概率返回错误结果。',false,'Its randomness affects time, not correctness.','它的随机性影响时间，不影响正确性。','A bounded-error output guarantee describes Monte Carlo algorithms instead.','允许有界输出错误的是Monte Carlo算法。')]);
add('S09.06','Advanced strings, polynomials and synthesis','进阶字符串、多项式与综合',[['Algebraic reduction','代数归约'],['Correlation','相关'],['Proof boundaries','证明边界']], [
['Advanced synthesis begins by translating the requested quantity into a representation with useful operations. A string matching score may become a sum over aligned indicators; a recurrence count may become polynomial coefficients. The reduction must explain why each valid object contributes exactly the intended amount, including duplicate symbols and boundary alignments.','综合题先把所求量翻成有用表示。字符串匹配分数可变为对齐指示量之和，递推计数可变为多项式系数。归约必须解释每个合法对象恰贡献正确数量，包括重复符号和边界对齐。'],
['To count equal-symbol matches at every alignment, build a zero-one indicator array for each alphabet symbol in the text and reversed pattern. Convolving corresponding arrays and summing coefficients produces match counts. Reversal turns alignment correlation into convolution; omitting it computes a different index relation even though the same transform routine still runs.','求每个对齐位置相同字符数，可为每字符建立文本与反转模式的01数组，对应卷积后求和。反转把对齐相关变为卷积；漏反转会计算另一种下标关系，尽管变换程序仍能运行。'],
['For text aba and pattern ab, alignment zero matches both symbols, score two; alignment one compares ba with ab, score zero. Indicator convolution reproduces these scores by selecting the coefficient corresponding to each pattern end. For a small alphabet, this needs one convolution per symbol rather than testing every pattern character at every start.','文本aba、模式ab，起点0两字都同，分数2；起点1比较ba与ab，分数0。指示卷积取模式末端对应系数可复现分数。小字母表下每字符一次卷积，无需逐起点逐字符比较。'],
['Account for transform padding, coefficient bounds, and modular reconstruction before claiming exactness. A faster subroutine does not repair a wrong reduction. Build a tiny direct implementation first and compare every intermediate score on short cases. Report total complexity including alphabet size, transforms, memory, and conversion work; calling something FFT-based alone gives no complete performance bound.','声称精确前检查补零、系数界与模重建。快子程序不能修复错误归约；先做直接小程序，短例逐个比较中间分数。总复杂度应包含字母表大小、变换、内存和转换工作，不能只说“用了FFT”。']
], [n('How many symbols match when ab is aligned with the last two symbols of aba?','ab与aba最后两字对齐时匹配几个字符？',0,'Compare ab with ba.','比较ab与ba。','Both aligned symbols differ.','两个对齐字符均不同。'),q('Reversing the pattern is irrelevant when converting correlation to convolution.','相关转卷积时反转模式无关紧要。',false,'Convolution combines indices by their sum.','卷积按下标和组合。','Reversal changes that sum relation into the required alignment difference.','反转把下标和关系转为所需对齐差关系。')]);

add('S10.01','Reading constraints and designing subtasks','阅读约束与设计子任务',[['Input model','输入模型'],['Complexity budget','复杂度预算'],['Subtask structure','子任务结构']], [
['A problem statement defines valid inputs, required outputs, and resource constraints. Translate every quantifier and boundary before selecting an algorithm. Distinguish the number of vertices, edges, queries, and total input size across test cases. A bound per case is different from a bound on the sum across all cases.','题面定义合法输入、输出与资源约束。选算法前翻译量词和边界，区分点、边、查询数及多组总规模。单组上界与所有组总量上界不同。'],
['Use constraints to reject clearly infeasible approaches, then derive a correctness argument for feasible candidates. If n is twenty, subset enumeration may be appropriate; if n is two hundred thousand, a quadratic scan likely needs replacement. Operation-count estimates guide choices but are not a universal conversion from Big-O to execution seconds.','约束先排除明显不可行方案，再为候选证明正确。n为20可考虑子集枚举，n为二十万时平方扫描通常需替换。操作数估计指导选择，但渐近复杂度不能统一换算成秒。'],
['Suppose a graph problem has subtasks for a tree, unit weights, and general nonnegative weights. A tree offers unique paths; unit weights permit BFS; the general case may require Dijkstra. These are mathematical restrictions supporting different proofs, not arbitrary score labels. A solution can explicitly select a proved method when its input condition holds.','若图题子任务为树、单位权、一般非负权，树有唯一路径，单位权用BFS，一般情况可用Dijkstra。这些是支持不同证明的数学限制，不只是分数标签；可在输入满足条件时选择已证明方法。'],
['Write down maximum possible answer magnitude before choosing integer types. Check whether duplicate edges, disconnected graphs, empty selections, and equal values are permitted. For outputting a witness, specify its validation as well as the objective value. This specification sheet becomes a checklist for adversarial tests and prevents optimizing a subtly different problem.','选类型前计算答案最大量级，检查重边、非连通、空选和相等值。输出方案时同时规定合法性与目标值检验。规范清单可指导对抗测试，避免优化成另一个相似问题。']
], [n('How many states arise in full subset enumeration of 20 items?','20项完全子集枚举有多少状态？',1048576,'Compute 2^20.','计算2^20。','There are 1,048,576 subsets.','共有1,048,576个子集。'),q('A unit-weight graph restriction can justify using BFS for shortest paths.','单位权图条件能支持BFS求最短路。',true,'Path weight equals edge count.','路径权等于边数。','BFS explores increasing edge counts, hence increasing total cost.','BFS按边数分层，也就是按总代价递增。')]);
add('S10.02','Partial scores and time allocation','部分分与时间分配',[['Expected return','期望收益'],['Opportunity cost','机会成本'],['Checkpoint','检查点']], [
['A timed contest is a constrained allocation problem: solving, coding, debugging, and reading all consume limited minutes. A partial solution can be valuable if its valid input region is proved. Preserve a working version before attempting a risky improvement, so a failed optimization does not erase already demonstrated correctness on supported cases.','限时赛把时间分给解题、编码、调试和阅读。若部分算法适用域已证明，就有价值。冒险优化前保存可用版本，避免失败优化抹掉已证实的部分正确性。'],
['Estimate marginal expected score per unit time rather than judging only by the largest possible reward. An uncertain full solution may deserve a fixed exploration window followed by reassessment. Time already spent is sunk cost; future choices should depend on current evidence and remaining opportunities, not a desire to justify earlier effort.','应估计每单位时间边际期望分，而非只看最高奖励。不确定正解可给固定探索窗口再评估。过去时间是沉没成本，下一步取决于当前证据和机会，不应为证明之前投入值得而继续。'],
['If one task offers a reliable twenty-point subtask in ten minutes and another a fifty-percent chance of forty points in thirty minutes, the simple estimates are two points per minute versus two-thirds. These are planning estimates, not measured probabilities. Completing the reliable subtask may free attention and preserve time for the uncertain task afterward.','若一题十分钟可靠拿20分，另一题三十分钟有一半机会拿40分，简单估计分别每分钟2分与2/3分。这些只是计划假设而非测得概率；先完成可靠部分可留时间再攻不确定者。'],
['Reserve time for compilation, input-format checks, sample execution, and boundary tests. Avoid changing several independent components immediately before submission, because attribution of new failures becomes difficult. After the contest, compare predicted effort with actual effort to improve future estimates. Optimization of contest strategy never replaces honest compliance with the event’s specific rules.','预留编译、格式、样例和边界测试时间。提交前不要同时改多个独立部分，否则新故障难定位。赛后比较预计与实际耗时改进估计；策略优化仍应遵守具体赛事规则。']
], [n('Twenty points in ten minutes is how many points per minute?','十分钟20分，每分钟几分？',2,'Divide score by time.','分数除以时间。','20/10=2.','20/10=2。'),q('Time already spent proves a task deserves all remaining contest time.','已经投入时间说明该题值得所有剩余时间。',false,'Past cost cannot be recovered by another poor choice.','过去成本不能靠另一错误选择挽回。','Compare future expected gains and alternatives instead.','应比较未来预期收益与替代选择。')]);
add('S10.03','Adversarial examples and stress testing','对抗样例与压力测试',[['Structural cases','结构用例'],['Oracle','答案程序'],['Reproducibility','可复现性']], [
['Adversarial testing targets the assumptions most likely to fail. Random uniform inputs rarely create a long chain, many equal keys, a nearly overflowing sum, or an exact boundary collision. Deliberately construct these families based on the proof and implementation, rather than treating a large number of random tests as complete coverage.','对抗测试针对最易失败的假设。均匀随机很少生成长链、全等键、近溢出和精确边界，需根据证明与实现主动构造这些家族，不能把大量随机当完整覆盖。'],
['A stress harness generates an input, runs a candidate and independent oracle, validates outputs, and saves the first disagreement. Include timeout and crash outcomes separately from wrong answers. When multiple witnesses are valid, validate the witness and objective rather than comparing raw output strings. Seeds and exact tool versions make a failure reproducible.','对拍框架生成输入，运行候选与独立答案，校验输出并保存首个分歧。超时、崩溃和错误答案分开记录。多解时验证方案与目标而非原始字符串，保存种子和工具版本便于复现。'],
['A shortest-path implementation that wrongly accepts negative edges may pass many nonnegative tests. A graph with edges A→B=2, A→C=5, C→B=−4 challenges the settled-distance assumption. The best A-to-B cost is one through C. A generator must actually include negative edges before it can expose this missing precondition.','错误接受负边的最短路程序可能通过许多非负测试。A→B=2、A→C=5、C→B=−4挑战确定距离假设，A到B最优为经C的1。生成器必须产生负边，才可能暴露遗漏前提。'],
['Keep generated inputs inside the claimed domain; testing forbidden inputs can reveal robustness defects but does not refute correctness under a narrower specification. Minimize failing cases while preserving legality and failure. Save the minimized case as a regression test and separately inspect why the proof or implementation allowed the defect. A patch matching one example is not sufficient repair.','输入应位于声称的合法域；禁用输入可揭示稳健性问题，却不能否定较窄规范内正确性。化简时保留合法与失败，保存回归用例，并检查证明或实现根因；只补一个样例不足。']
], [n('In the worked graph, what is the true A-to-B shortest cost?','例题图中A到B真正最短成本是多少？',1,'Use A→C→B.','走A→C→B。','5+(−4)=1, smaller than the direct cost two.','5−4=1，小于直达2。'),q('Uniform random testing reliably covers every important boundary family.','均匀随机测试可靠覆盖所有重要边界家族。',false,'Some structures have extremely low sampling probability.','一些结构被采到概率极低。','Targeted construction is needed for rare but legal cases.','稀少但合法情况需主动构造。')]);
add('S10.04','Local timed contests','本地限时模拟赛',[['Fixed conditions','固定条件'],['Time log','时间记录'],['Post-contest audit','赛后审计']], [
['A useful local contest has a fixed start, fixed duration, explicit permitted references, and a selected problem set before the clock begins. These controls make performance interpretable. Changing conditions halfway through may be reasonable for learning, but the result should then be described as practice rather than a comparable timed measurement.','有用模拟赛应预定开始、时长、允许参考和题集，使表现可解释。中途改变条件可以用于学习，但结果应称练习，而非可比较的限时测量。'],
['Separate the contest workspace from the learning notebook. Record when each problem was read, when a plausible algorithm was found, and when a tested submission became available. The log distinguishes conceptual difficulty from implementation time and debugging time. A final score alone cannot explain which skill limited performance.','比赛工作区与学习笔记分开，记录读题、找到可行算法、完成测试提交的时间。这样区分概念困难、实现和调试；仅最终分数不能说明瓶颈。'],
['In a ninety-minute session, suppose reading takes ten minutes, problem A takes twenty-five, and problem B takes thirty-five. Twenty minutes remain for testing or another subtask. If A’s code was finished at minute thirty but tested only at minute seventy, the delay reveals a process risk even if the final output happens to be correct.','九十分钟模拟中，阅读10分钟，A用25，B用35，还剩20用于测试或子任务。若A在第30分钟写完却第70才测试，即使最终正确，延迟仍暴露流程风险。'],
['After time expires, freeze the contest version and evaluate it separately from later fixes. Then annotate missed constraints, incorrect proof steps, implementation defects, and time-allocation choices. Comparing a repaired version with the frozen version measures learning without rewriting history. Use repeated sessions with similar difficulty to judge a trend; one unusually favorable set is weak evidence.','时间到先冻结比赛版本，后续修复另行评估。标注漏约束、错证明、实现缺陷和时间分配。修复版与冻结版比较反映学习而不改写历史；趋势需类似难度多次模拟，一次顺利证据弱。']
], [n('After 10+25+35 minutes in a 90-minute contest, how many minutes remain?','90分钟比赛已用10+25+35分钟，还剩多少？',20,'Subtract the total spent.','减去已用总量。','90−70=20.','90−70=20。'),q('Post-contest fixes should be included in the original timed score without a label.','赛后修复可不加说明地计入原限时成绩。',false,'The conditions differ.','条件已经不同。','Keep the frozen score and repaired learning result separate.','冻结成绩与修复后的学习结果应分开。')]);
add('S10.05','Editorial reconstruction and independent re-solving','题解重构与独立重做',[['Reconstruction','重构'],['Retrieval practice','提取练习'],['Transfer','迁移']], [
['Reading an editorial can produce recognition without the ability to generate the method independently. Reconstruction closes that gap: identify the exact obstacle, the key observation that removes it, the state or invariant, and the proof. Restate these in your own notation before looking at implementation details.','看懂题解可能只有熟悉感而不能独立生成方法。重构需指出障碍、解决观察、状态或不变量及证明，在看代码细节前用自己的符号复述。'],
['Close the reference and derive a small example from first principles. Then implement from the reconstructed argument rather than from remembered lines. If you cannot justify a transition, reopen only the relevant explanation and record the missing bridge. Delayed re-solving tests whether the structure survives after short-term memory of the editorial fades.','关闭参考，从第一原理推小例，再根据重构论证编码，而非记忆代码行。若无法解释转移，只重看相关部分并记录缺失桥梁。延迟重做检验结构是否在短期记忆消退后仍保留。'],
['For interval DP, reconstruct why the last split divides the solution into independent shorter intervals, why every valid optimum has such a split, and why all splits are examined. Merely remembering three nested loops omits the central proof. A variation changing the merge cost tests whether the recurrence was understood rather than memorized.','区间DP要重构最后断点为何分成独立短区间、每个最优解为何有该断点、为何枚举覆盖全部。只记三重循环遗漏核心证明；改合并成本的变式检验是否理解递推。'],
['Track assistance honestly: a solved exercise after reading a full solution is supported practice, not an independent discovery. Its educational value is real, but it supplies different evidence. A later independent solve and a nearby unfamiliar variant provide stronger transfer evidence. Keep source attribution for copied ideas or code and avoid presenting reconstructed material as a novel algorithm.','如实记录帮助：看完整解后的完成是有支持练习，不是独立发现，价值真实但证据不同。之后独立重做和邻近陌生变式更能体现迁移。引用借鉴思想或代码，不把重构说成新算法。']
], [n('A recurrence examines split positions 1 through 5 inclusive. How many candidate splits must be considered?','递推枚举断点1到5，含端点，共几种？',5,'Count every legal split.','数全部合法断点。','There are five candidate divisions; skipping one needs a separate proof.','共有五种，跳过任何一种需另证。'),q('Remembering the code’s loop shape is enough to justify its recurrence.','记住循环形状足以证明递推。',false,'The state meaning and exhaustive decomposition supply the proof.','状态含义和穷尽分解才构成证明。','Identical loop shapes can implement unrelated or incorrect recurrences.','同样循环形状可能实现不同甚至错误递推。')]);
add('S10.06','Personal error patterns and targeted sets','个人错误模式与专项训练',[['Error taxonomy','错误分类'],['Targeted practice','针对练习'],['Retention check','保持检验']], [
['An error log is useful when it records causes and corrective actions, not just problem titles. Distinguish misunderstood definitions, missing prerequisites, invalid proof steps, complexity misestimates, implementation defects, and process mistakes. Several wrong answers caused by the same invariant confusion may require one conceptual repair rather than many unrelated additional problems.','错题日志应记录原因和纠正动作，而非只有题号。区分定义误解、前提缺失、证明错误、复杂度误估、实现和流程问题。同一不变量困惑造成多次错误，可能需一次概念修复而非大量无关刷题。'],
['Choose a small practice set that isolates the weakness, then vary one relevant dimension at a time. For off-by-one mistakes, compare empty, singleton, inclusive, and half-open ranges. Predict outputs before execution. Explanation of why a boundary belongs or does not belong is more transferable than memorizing whether one loop happened to use < or <=.','用小题组隔离弱点，每次变化一个相关维度。差一错误可练空、单项、闭区间与半开区间，运行前预测输出。解释边界归属比记住某循环用<还是<=更能迁移。'],
['Suppose six of ten recent defects were overflow errors. A targeted set can ask for maximum sum, maximum product, and intermediate-expression bounds under different constraints. For n=100000 and each value at most 10^9, the sum can reach 10^14. A signed 32-bit accumulator is inadequate even though each individual input fits.','若最近十个缺陷有六个溢出，可专项练不同约束下最大和、最大积、中间式范围。n=100000且每项至多10^9，和可到10^14；每个输入能存不代表32位累计量足够。'],
['Revisit the concept after a delay and include one mixed problem where the relevant technique is not named. Improvement means fewer repeated causes under comparable conditions, not simply more completed items. Record unresolved uncertainty explicitly. Self-selected practice data can be biased toward familiar topics, so occasionally sample a broad diagnostic set to check for neglected foundations.','延后复查，并加一道不点名技巧的混合题。进步是可比条件下同因错误减少，不只是完成更多。明确未解决疑问；自选练习偏熟悉领域，应偶尔抽广泛诊断检查遗漏基础。']
], [n('What is 100000×10^9, the maximum example sum?','例题最大和100000×10^9是多少？',100000000000000,'Add the powers of ten.','幂指数相加。','10^5×10^9=10^14.','10^5×10^9=10^14。'),q('A targeted practice set should vary irrelevant features randomly before isolating the error cause.','专项练习应先随机变化无关特征，再定位错误。',false,'Isolation makes cause and effect visible.','隔离才便于观察因果。','First control unrelated dimensions, then add variation to test transfer.','先控制无关维度，再增加变化检验迁移。')]);

add('S11.01','Boolean logic and combinational circuits','布尔逻辑与组合电路',[['Logic gate','逻辑门'],['Truth table','真值表'],['Binary addition','二进制加法']], [
['A Boolean signal has two abstract values, zero and one. AND outputs one only when both inputs are one; OR when at least one is one; NOT reverses a value. A combinational circuit’s output depends only on present inputs, with physical propagation delay abstracted separately from its logical truth table.','布尔信号有0和1两值。与门要求双1，或门要求至少一1，非门反转。组合电路输出仅依赖当前输入，物理传播延迟与逻辑真值表分开考虑。'],
['A truth table enumerates every input combination and its required output. With k inputs there are 2^k rows. Equivalent Boolean expressions agree on all rows, so algebraic simplification preserves function while potentially reducing gate count or delay. XOR outputs one when its inputs differ, which makes it useful for binary sum bits.','真值表枚举所有输入，k输入有2^k行。等价表达式各行相同，化简保持功能而可能减门数或延迟。异或在输入不同为1，适合二进制和位。'],
['A half adder takes bits a,b and outputs sum a XOR b and carry a AND b. For a=b=1, sum is zero and carry one, representing binary 10. A full adder also accepts an incoming carry; its three input bits have arithmetic total zero through three, encoded by one sum and one carry bit.','半加器和位a异或b，进位a与b。双1时和0进1，表示二进制10。全加器还接收入进位，三输入算术和0到3，用和位与进位表示。'],
['Logical correctness does not prove electrical timing correctness. Different gate paths can change at different times, producing transient glitches. Specify input stability and output sampling assumptions before connecting combinational logic to state elements. Binary encodings also need meaning: the same bits may represent an unsigned integer, signed integer, character, or instruction depending on the surrounding interface.','逻辑正确不证明时序正确，路径延迟不同会产生毛刺。接状态元件前须规定输入稳定与输出采样。编码还需语义，同一位串可代表无符号数、有符号数、字符或指令。']
], [n('How many truth-table rows do three Boolean inputs require?','三个布尔输入需几行真值表？',8,'Each input has two choices.','每输入两种值。','2^3=8.','2^3=8。'),n('What is the sum bit of a half adder with inputs one and one?','半加器输入1、1，和位是多少？',0,'Separate the carry from the low bit.','把进位和低位分开。','Binary 10 has low bit zero and carry one.','二进制10低位0、进位1。')]);
add('S11.02','Sequential logic and state','时序逻辑与状态',[['Register','寄存器'],['Clock edge','时钟边沿'],['Finite-state machine','有限状态机']], [
['Sequential circuits remember information, so their outputs can depend on past inputs. A register stores a fixed number of bits. In a synchronous design, registers sample their next values on designated clock edges, while combinational logic computes those next values between edges. This separation gives a discrete state-transition model.','时序电路记忆信息，输出可依赖历史。寄存器存固定位数；同步设计在指定时钟沿采样下一值，沿间由组合逻辑计算，从而形成离散状态转移模型。'],
['A finite-state machine consists of states, input symbols, transitions, and outputs. Its state must summarize all history relevant to future behavior. A Moore output depends on state alone; a Mealy output can also depend on current input. Both can describe a controller, but their output timing and state counts may differ.','有限状态机含状态、输入、转移和输出，状态应总结未来所需历史。Moore输出只依赖状态，Mealy还依赖当前输入；两者可描述控制器，但输出时机与状态数可能不同。'],
['A two-bit counter stores 00,01,10,11 and increments modulo four on each clock edge. Starting at 00, five increments leave 01. An enable input can hold the old state when false. A reset establishes a known initial state; without a specified initialization, a theoretical trace starting at zero is unjustified.','两位计数器按00、01、10、11循环，00起五次加一到01。enable为假可保持旧值，reset建立已知初态；没规定初始化就不能凭空从零跟踪。'],
['A register needs its input stable for setup and hold intervals around the sampling edge. Violations can cause metastability, which is not a third reliable Boolean value. Signals crossing clock domains require synchronization designs, and multi-bit data needs coherence beyond synchronizing each bit independently. A logical state diagram is one layer of the complete hardware argument.','采样沿前后需满足建立与保持稳定时间，违反可能亚稳，并非可靠第三逻辑值。跨时钟域需同步设计，多位数据还需一致性，不能只逐位同步。状态图只是硬件论证的一层。']
], [n('A two-bit modulo-four counter starts at zero. What value follows five increments?','两位模4计数器从0开始，加五次后是多少？',1,'Reduce five modulo four.','五模四。','5 mod 4=1.','5 mod4=1。'),q('A state variable should preserve every historical input even when irrelevant to future behavior.','状态必须保留所有历史输入，即使对未来无关。',false,'State is a sufficient summary.','状态是充分摘要。','Only history affecting future transitions or outputs needs representation.','只需表示影响未来转移或输出的历史。')]);
add('S11.03','Instruction sets and assembly','指令集与汇编',[['Architectural state','体系结构状态'],['Load-store','加载与存储'],['Control transfer','控制转移']], [
['An instruction-set architecture specifies the programmer-visible machine: registers, instructions, memory addressing, and effects. Assembly gives symbolic names to machine operations. Different processors can implement the same instruction set with different pipelines or caches, so an instruction’s defined effect must be distinguished from one implementation’s execution time.','指令集架构规定程序可见的寄存器、指令、寻址和效果，汇编给机器操作符号名。同一指令集可由不同流水线或缓存实现，应区分定义效果与具体运行时间。'],
['A load copies a memory value into a register; a store copies a register value to memory. Arithmetic instructions transform register values, and branches select the next instruction address. A program counter identifies control position. A calling convention additionally defines how arguments, return values, and preserved registers are shared between separately compiled functions.','加载把内存值放入寄存器，存储反向复制。算术变换寄存器，分支选下一指令地址，程序计数器表示控制位置。调用约定还规定参数、返回值和保留寄存器，支持独立编译函数互调。'],
['To add two stored integers, conceptually load the first into r1, the second into r2, compute r3=r1+r2, then store r3 to the output address. If the values are seven and nine, the output is sixteen. The conceptual sequence exposes data movement that a high-level expression a+b hides from view.','相加两个内存整数，可先载入r1、r2，计算r3=r1+r2，再存出。输入7与9得16。高层a+b隐藏的数据移动在此显露。'],
['Signedness, instruction width, endianness, and alignment affect interpretation. A byte sequence is not self-describing without its architecture and format. Do not assume that one assembly instruction is atomic across all observers or always takes one clock cycle. Examine the relevant architectural contract, while keeping privileged instructions and operating-system interfaces separate from ordinary user-mode arithmetic.','有符号性、位宽、字节序和对齐影响解释；字节序列需架构与格式才能理解。不能假定一条汇编总原子或总一周期。应检查架构约定，区分特权指令、系统接口与普通用户算术。']
], [n('What does a conceptual add of register values 7 and 9 produce?','寄存器7与9相加得到多少？',16,'Add the represented integers.','相加整数。','7+9=16, assuming representable arithmetic.','在可表示范围内7+9=16。'),q('The same instruction set forces every processor to use the same internal pipeline.','同一指令集强制所有处理器使用相同流水线。',false,'The ISA specifies observable effects.','ISA规定可观察效果。','Different microarchitectures can implement those same effects.','不同微架构可实现相同效果。')]);
add('S11.04','CPU datapaths and pipelines','CPU数据通路与流水线',[['Datapath','数据通路'],['Hazard','冒险'],['Throughput','吞吐量']], [
['A datapath carries values through registers, arithmetic units, selectors, and memory interfaces. Control signals determine which values move and which operation occurs. A simple instruction can be divided into fetch, decode, execute, memory access, and writeback stages. This decomposition describes roles rather than requiring every real processor to use exactly five stages.','数据通路连接寄存器、算术单元、选择器和内存接口，控制信号决定数据流与操作。指令可分取指、译码、执行、访存、写回，但真实处理器不必恰好五级。'],
['Pipelining overlaps different instructions in different stages. It improves steady-state throughput but does not necessarily reduce one instruction’s latency. Data hazards occur when an instruction needs an earlier result before it is available; forwarding bypasses some waits. Control hazards arise because a branch changes which instructions should have been fetched.','流水线让不同指令同时处于不同阶段，提高稳定吞吐，却不一定降低单指令延迟。数据冒险是结果尚未可用，转发可减少部分等待；控制冒险来自分支改变应取的指令。'],
['For an ideal five-stage pipeline with one cycle per stage and no stalls, ten instructions finish in five plus nine, or fourteen cycles. Without overlap they take fifty stage cycles. A load-use dependency or mispredicted branch inserts extra work or bubbles, so real completion can exceed the ideal count substantially.','理想五级每级一周期、无停顿，十条指令共5+9=14周期，完全不重叠则50。加载使用依赖或分支预测错会增加气泡和工作，真实用时可大于理想。'],
['A structural hazard means two operations compete for one hardware resource. Scheduling, duplicate resources, and stalls trade cost against throughput. Out-of-order execution can overlap independent work while preserving architectural results through retirement rules. Performance claims must state dependencies, branch behavior, and memory effects; counting instructions alone ignores the mechanisms that determine actual execution cycles.','结构冒险是操作争用同一资源，调度、复制硬件、停顿在成本与吞吐间权衡。乱序可重叠独立工作，并通过退休规则保持架构结果。性能需说明依赖、分支和内存，不能只数指令。']
], [n('How many cycles do ten instructions need in the stated ideal five-stage pipeline?','所述理想五级流水线执行十条指令需几周期？',14,'Fill five stages, then finish one per cycle.','填充五级后每周期完成一条。','5+(10−1)=14.','5+(10−1)=14。'),q('Pipelining always reduces the latency of each individual instruction.','流水线总降低每条指令自身延迟。',false,'Throughput and latency are different quantities.','吞吐与延迟不同。','Overlap may improve completion rate while each instruction still crosses all stages.','重叠提高完成速率，但每条仍需通过全部阶段。')]);
add('S11.05','Memory hierarchy and caches','内存层次与缓存',[['Locality','局部性'],['Cache line','缓存行'],['Miss penalty','缺失代价']], [
['A memory hierarchy combines small fast storage with larger slower storage. Caches retain recently used blocks called lines. Temporal locality means recently used data is likely to be reused; spatial locality means nearby addresses are likely to be accessed. These patterns explain why contiguous array traversal often outperforms pointer chasing despite similar operation counts.','内存层次把小快与大慢存储结合，缓存保留称为行的数据块。时间局部性是近期数据可能重用，空间局部性是邻近地址可能访问；因此连续数组常比同操作量指针追踪快。'],
['A cache hit finds the requested line locally; a miss fetches it from a lower level and may evict another line. Mapping and associativity decide which lines compete for slots. Replacement policies choose a victim, while write-through and write-back policies decide when modified data reaches lower storage levels.','命中在本级找到数据行，缺失从下级取回并可能驱逐。映射与相联度决定竞争位置，替换策略选牺牲者，直写与回写决定修改何时送下级。'],
['In a simplified model with hit time one nanosecond, miss rate five percent, and additional miss penalty forty nanoseconds, average access time is 1+0.05×40=3 nanoseconds. The penalty is additional time, not a replacement for the hit-time term. Multilevel systems and overlapping misses require richer models.','简化模型命中1纳秒，缺失率5%，额外缺失代价40纳秒，平均1+0.05×40=3纳秒。代价是额外时间，不能替代命中项。多级及重叠缺失需要更丰富模型。'],
['Cache-friendly blocking reuses a small working set before moving onward, as in tiled matrix multiplication. Measure with realistic sizes that exceed relevant cache capacities. False sharing occurs when independent threads modify different data on the same coherence line, creating contention despite no logical sharing. A correct algorithm can remain slow because its data layout conflicts with the hierarchy.','分块如矩阵乘法在移动前重用小工作集。测试规模应真实并超过相关容量。不同线程修改同一致性行不同数据会假共享，虽逻辑不共享仍争用。算法正确也可能因布局不适合层次而慢。']
], [n('What is 1+0.05×40 in the average-access example?','平均访问例题1+0.05×40是多少？',3,'Include hit time plus expected penalty.','包含命中与期望惩罚。','One plus two equals three nanoseconds.','1加2等于3纳秒。'),q('Two threads modifying different variables can still cause false sharing.','两线程改不同变量仍可能假共享。',true,'Their variables may occupy the same cache line.','变量可能在同一缓存行。','Coherence operates on line granularity, not individual variable meaning.','一致性以行为单位，不按变量语义。')]);
add('S11.06','Performance measurement and parallel hardware','性能测量与并行硬件',[['Benchmark','基准测试'],['Amdahl law','阿姆达尔定律'],['Bottleneck','瓶颈']], [
['Performance is a measurement of a defined workload under stated conditions. Latency measures time per task; throughput measures tasks per time. Report input sizes, compiler settings, hardware, and whether setup is included. Warmup, caching, background activity, and thermal behavior can change results, so one convenient timing is not a reliable universal property.','性能针对规定工作负载与条件。延迟是每任务时间，吞吐是每时间任务数。需记录规模、编译、硬件与是否含准备；预热、缓存、后台、温度都会影响，单次方便计时不是普遍性质。'],
['Amdahl’s law models a fraction s that remains serial and the rest accelerated by p workers: speedup is 1/(s+(1−s)/p), ignoring overhead. Even infinitely many workers cannot exceed 1/s. This reveals why optimizing a dominant serial stage can matter more than doubling processors for an already parallel stage.','串行比例s、其余用p工作者且忽略开销时，加速比1/(s+(1−s)/p)，无限工作者也不超过1/s。优化主导串行阶段可能比并行阶段加倍处理器更重要。'],
['With twenty percent serial work and four workers, modeled runtime is 0.2+0.8/4=0.4 of the original, giving speedup 2.5. Communication and synchronization reduce that further. GPUs favor many similar operations with enough data parallelism; branch divergence and irregular memory accesses can limit their effective utilization.','串行20%、四工作者，运行比例0.2+0.8/4=0.4，加速2.5；通信同步还会降低。GPU适合大量相似数据并行，分支分歧和不规则访存可限制利用率。'],
['Profile before changing code, and verify that optimized output remains correct. Distinguish strong scaling, fixed total work, from weak scaling, fixed work per processor. Report variability and enough repetitions to reveal noise. A speedup against an unoptimized baseline says little about the best competing implementation unless the baselines and measurement boundaries are made explicit.','改代码前分析瓶颈，并验证结果不变。强扩展固定总工作，弱扩展固定每处理器工作。报告波动与足够重复。相对未优化基线的加速，不能自动说明优于最佳竞争实现，需明确基线与测量边界。']
], [n('For serial fraction 0.2 and four workers, what is ideal speedup?','串行0.2、四工作者的理想加速比是多少？',2.5,'Compute 1/(0.2+0.8/4).','计算1/(0.2+0.8/4)。','The denominator is 0.4, giving 2.5.','分母0.4，结果2.5。'),q('Throughput and latency are the same metric.','吞吐与延迟是同一指标。',false,'They describe rates and durations.','一个描述速率，一个描述时长。','Batching can increase throughput while increasing an individual request’s latency.','批处理可提高吞吐，却增加单请求延迟。')]);

add('S12.01','Processes, threads and system calls','进程、线程与系统调用',[['Process','进程'],['Thread','线程'],['Privilege boundary','权限边界']], [
['A program is stored instructions; a process is an executing instance with an address space and operating-system resources. A thread is an execution stream with its own registers and stack. Threads within one process normally share its address space, so communication is easy but unsynchronized access can corrupt shared state.','程序是存储指令，进程是带地址空间和系统资源的运行实例。线程有自己的寄存器和栈，同进程线程通常共享地址空间，通信方便但无同步访问会破坏共享状态。'],
['The operating system schedules runnable threads onto processors. A context switch saves one execution state and restores another. A system call deliberately crosses from user mode into a controlled kernel interface to request services such as file access or process creation. Ordinary function calls need not cross that privilege boundary.','操作系统把可运行线程调度到处理器，切换时保存与恢复执行状态。系统调用通过受控接口从用户态进入内核，请求文件或创建进程等服务；普通函数调用不一定跨权限边界。'],
['Two processes running the same executable can each store a variable named count at the same virtual address while holding different values. Two threads in one process referring to the same global count access the same object. This difference explains why a thread-based counter requires synchronization while process communication usually needs an explicit shared channel.','同一程序两个进程可在相同虚拟地址存不同count值；同进程两线程访问同全局count则是同对象。因此线程计数器需同步，而进程通信通常需显式共享渠道。'],
['A blocked thread waits for an event and need not consume CPU continuously. Busy waiting is different: it repeatedly executes checks. Handle creation failure, termination, and resource cleanup as part of the process contract. A process boundary supports isolation but is not an automatic guarantee against every vulnerability, especially when shared resources and privileged interfaces are involved.','阻塞线程等待事件，不必持续耗CPU；忙等则反复执行检查。创建失败、终止与清理均属约定。进程边界支持隔离，但共享资源与特权接口仍可能有漏洞，并非万能保证。']
], [n('If two independent processes each initialize a private counter to zero and increment once, what is each counter?','两个独立进程各自私有计数器从0加一次，各是多少？',1,'Private address spaces are distinct.','私有地址空间不同。','Each process modifies its own counter to one.','各自计数器都变为1。'),q('Threads in one process normally have completely separate global-variable storage.','同进程线程通常完全分离全局变量存储。',false,'They share the process address space.','它们共享进程地址空间。','Each thread has its own stack, but shared globals remain shared.','栈各自独立，但全局量仍共享。')]);
add('S12.02','Scheduling and synchronization','调度与同步',[['Scheduling policy','调度策略'],['Critical section','临界区'],['Condition variable','条件变量']], [
['Scheduling chooses which runnable thread receives CPU time. Round-robin rotates through tasks with a time quantum; priority policies favor designated work. Fairness, response time, and throughput can conflict. The mechanism of switching contexts is separate from the policy deciding whose context should run next.','调度选择哪个就绪线程获得CPU。轮转按时间片循环，优先级策略偏向指定工作。公平、响应与吞吐可能冲突；切换机制与选择谁运行的策略不同。'],
['A critical section accesses shared state that must obey an invariant. A mutex admits one owner at a time. A condition variable lets a thread sleep until a shared predicate may have changed; after waking, it rechecks the predicate in a loop while holding the associated lock, because notifications are not the predicate itself.','临界区访问需保持不变量的共享状态，互斥锁一次一个拥有者。条件变量让线程等待共享条件可能改变；醒后持锁循环检查，因为通知本身不等于条件成立。'],
['Two threads both read counter zero, compute one, then both write one. Two increments have produced one: a lost update. Locking the complete read-modify-write sequence serializes the updates and yields two. Protecting only the final assignment is insufficient because the earlier read and computation still race with the other operation.','两线程都读0、算1、写1，两次加一却得1，是丢失更新。锁住完整读改写序列才得到2；只锁最后写入不足，早先读与计算仍竞争。'],
['Deadlock can arise when threads hold resources while waiting in a cycle. A consistent global lock order can prevent circular wait for those locks. Avoid holding locks during slow external operations unless required by a proved design. Race freedom alone does not prove absence of deadlock, starvation, or incorrect higher-level transactions.','持有资源又循环等待可死锁，一致全局加锁顺序可防这些锁的循环等待。无必要不要持锁执行慢外部操作。无数据竞争不等于无死锁、无饥饿或高层事务正确。']
], [n('Two correctly synchronized increments from zero should leave what value?','从0正确同步加两次后是多少？',2,'Each completed increment contributes one.','每次完成加一。','Serializing the full operation gives 0→1→2.','完整串行操作得到0→1→2。'),q('A condition-variable wakeup proves the awaited predicate is true.','条件变量唤醒证明等待条件为真。',false,'The predicate must be checked under its lock.','需要持锁复查条件。','Another thread may consume the condition, and wakeups can be spurious.','其他线程可能消耗条件，也可能伪唤醒。')]);
add('S12.03','Virtual memory','虚拟内存',[['Address translation','地址转换'],['Page table','页表'],['Page fault','缺页异常']], [
['Virtual memory gives each process a logical address space separated from physical memory layout. Addresses are divided into a virtual page number and an offset. A page table maps virtual pages to physical frames and records permissions. Translation changes the page number while preserving the within-page offset.','虚拟内存让进程逻辑地址空间与物理布局分离。地址分虚页号和偏移，页表映射到物理页框并记录权限；转换改变页号，页内偏移不变。'],
['A translation lookaside buffer caches recent page translations. A TLB miss requires finding the translation, not necessarily reading data from disk. A page fault occurs when translation or access conditions need operating-system handling, such as loading a not-present page or rejecting a forbidden write. Not every page fault represents a software bug.','TLB缓存近期页转换。TLB缺失要查转换，不一定读磁盘。缺页异常在页不在场或禁止访问等需要系统处理时发生，并非每次都代表程序错误。'],
['With a 4096-byte page size, virtual address 8197 has page number two and offset five. If virtual page two maps to physical frame nine, the physical address is 9×4096+5=36869. The same virtual page number in another process can map to a different frame or be unmapped.','页大小4096字节，虚地址8197是页号2、偏移5。若映射物理框9，物理地址9×4096+5=36869。另一进程同虚页号可映射别框或无映射。'],
['Demand paging postpones allocating or loading a page until needed. Replacement chooses a resident page to evict when memory is scarce; dirty pages need preservation before reuse. Excessive paging can cause thrashing, where little useful computation occurs. Virtual address capacity, committed memory, and resident physical memory are different quantities and should not be reported interchangeably.','按需分页推迟分配或装入到使用时，内存不足需选页驱逐，脏页复用前需保存。过度换页会抖动，几乎不做有效计算。虚地址容量、已提交内存和驻留物理内存不是同一量。']
], [n('For page size 4096, what is the offset of virtual address 8197?','4096字节页下，地址8197的页内偏移是多少？',5,'Subtract two full pages.','减去两整页。','8197−8192=5.','8197−8192=5。'),q('Every TLB miss means a disk access is necessary.','每次TLB缺失都必须访问磁盘。',false,'The translation may already be in an in-memory page table.','转换可能已在内存页表。','TLB misses concern cached translation, not necessarily nonresident data.','TLB缺失是转换缓存问题，不一定数据不驻留。')]);
add('S12.04','Filesystems and storage','文件系统与存储',[['File namespace','文件命名空间'],['Metadata','元数据'],['Crash consistency','崩溃一致性']], [
['A filesystem maps names and directories to stored objects and maintains metadata such as length, ownership, and permissions. File contents occupy storage blocks that need not be physically contiguous. A file descriptor or handle refers to an opened instance, allowing access without repeatedly resolving the whole pathname for every operation.','文件系统把路径目录映射到存储对象，并维护长度、所有者、权限等元数据。内容块不必物理连续，文件描述符或句柄引用已打开实例，无需每次重新解析完整路径。'],
['Reading and writing can be buffered in memory. A successful write call may report that data reached a kernel buffer rather than durable storage. Durability requires the relevant synchronization contract, including metadata where necessary. Updating a file often changes several structures, so a crash between writes can leave them inconsistent without a recovery mechanism.','读写可能缓存在内存，write成功可能只代表到内核缓冲而非持久存储。持久性需相应同步约定，必要时包含元数据。更新文件常改多结构，中途崩溃若无恢复机制会不一致。'],
['Appending a block may require storing the data, recording its block pointer, and increasing file length. Journaling records intended changes so recovery can finish or discard an incomplete transaction consistently. Copy-on-write instead writes new versions and changes a root reference only when the replacement structure is ready.','追加块可能需写数据、块指针、长度。日志记录预定变化，使恢复能一致完成或丢弃未完整事务；写时复制则写新版本，结构就绪后才换根引用。'],
['Atomic rename can support replacing one file’s visible name, but it does not automatically prove that every byte is durable after power loss. Consult the operating system and filesystem contract. Backups protect against deletion or device loss only if independently stored and tested. A checksum detects some corruption but does not by itself reconstruct lost data.','原子重命名可替换可见文件名，但不自动保证断电后每字节持久，需核对系统与文件系统约定。备份应独立存储并测试；校验和可检错，却不能独自恢复丢失数据。']
], [n('A file has three blocks of 4096 bytes and one final block containing 100 bytes. What is its logical length?','文件三个完整4096字节块，末块实际100字节，逻辑长度是多少？',12388,'Count used bytes, not final-block capacity.','数已用字节，不数末块容量。','3×4096+100=12388.','3×4096+100=12388。'),q('A successful buffered write always guarantees survival after immediate power loss.','缓冲写成功总保证立即断电后仍保存。',false,'Buffered acceptance and durable storage are distinct.','缓冲接收和持久存储不同。','Additional synchronization and storage guarantees are required.','还需同步操作与存储保证。')]);
add('S12.05','Isolation and resource management','隔离与资源管理',[['Least privilege','最小权限'],['Quota','配额'],['Capability','能力授权']], [
['Isolation limits which resources one computation can observe or change. Address-space protection separates memory, while access controls restrict files, devices, and services. Least privilege gives a task only the authority needed for its purpose. The boundary must include every path to the protected resource, not just the most obvious user interface.','隔离限制计算可观察或修改资源。地址保护隔离内存，访问控制限制文件、设备与服务。最小权限只给必要权力，边界须覆盖访问资源所有路径，而非只管明显界面。'],
['Resource management controls CPU time, memory, storage, process count, and other finite capacities. A quota limits consumption; scheduling decides how available capacity is shared. These solve different problems from confidentiality. A task that cannot read another task’s data might still exhaust shared memory or flood a queue unless resource limits are enforced.','资源管理控制CPU、内存、存储、进程数等容量。配额限制消耗，调度决定分配，二者不同于保密。不能读别人的任务仍可能耗尽共享内存或队列，需执行资源限制。'],
['A code-execution service should separately limit executable authority and resources: a time budget stops endless loops, memory limits contain allocation growth, and restricted file access protects unrelated documents. A ten-second limit does not prevent a program from reading a secret during its first millisecond. Permissions and quotas must therefore be designed together.','代码执行服务需同时限制权限与资源：时限停死循环，内存限额限制分配，文件权限保护无关文档。十秒时限不能阻止首毫秒读秘密，因此权限和配额必须共同设计。'],
['A capability is an unforgeable reference granting specific authority to an object or operation. Passing a narrow handle can be safer than granting ambient access to an entire directory tree. Validate inputs at trust boundaries and close resources reliably. Containers, processes, and virtual machines have different isolation mechanisms; their names alone do not establish a complete security argument.','能力是不可伪造、授予特定对象或操作权限的引用。传窄句柄可优于环境中授予整个目录权限。边界验证输入并可靠关闭资源。容器、进程、虚机机制不同，名称本身不能构成完整安全论证。']
], [n('A job has a 64 MB quota and currently uses 50 MB. How many MB remain?','任务限额64MB，已用50MB，还剩多少？',14,'Subtract current use.','减去已用。','64−50=14 MB.','64−50=14MB。'),q('A CPU time limit alone prevents unauthorized file reads.','单独CPU时限就能阻止越权读文件。',false,'Reading can occur before the time limit.','读取可在时限前发生。','Access control must independently restrict which files may be opened.','必须独立限制可打开哪些文件。')]);
add('S12.06','OS design experiments','操作系统设计实验',[['Controlled workload','受控工作负载'],['Observable metric','可观察指标'],['Model validation','模型验证']], [
['An operating-system experiment tests a concrete hypothesis about mechanisms or policies. Define the workload, intervention, and metric before measuring. To study scheduling, record response and completion times; to study memory, record working-set sizes and page behavior. A demonstration that merely runs successfully does not establish an explanation for why it behaves as observed.','系统实验检验机制或策略的具体假设，测前定义负载、干预和指标。调度看响应完成时间，内存看工作集与页行为。仅运行成功不能解释观察机制。'],
['Build a small simulator when directly modifying a kernel would obscure the concept. A scheduling simulator can use known job arrivals and durations, producing an exact timeline for each policy. Its results validate the simulator’s model, not the performance of a production operating system with interrupts, caches, I/O, and competing background work.','直接改内核会掩盖概念时可建小模拟器。调度模拟用已知到达和工期生成精确时间线，但结果只验证模型，不是有中断、缓存、I/O与后台任务的真实系统性能。'],
['Two jobs arrive at time zero with durations eight and two. First-come-first-served with the long job first gives completion times eight and ten, average nine. Shortest-job-first gives two and ten, average six. This explains one policy’s advantage for that workload while leaving fairness and unknown future durations unresolved.','两个任务同时到达，工期8和2。长任务先来的FCFS完成时刻8、10，平均9；短任务优先为2、10，平均6。说明该负载下优势，但公平和未知未来工期仍未解决。'],
['Change one factor at a time and preserve raw measurements. Repeat physical timings, distinguish cold from warm caches, and report variance. Compare predictions with observed results and investigate discrepancies before adjusting the model. Keep experiments inside disposable data and explicitly chosen resources so a lesson about storage or isolation does not alter unrelated user files or machine-wide settings.','每次改一因素并保存原始测量。物理计时需重复，区分冷暖缓存并报告波动；先调查预测与观察差异再改模型。实验限定可丢数据与指定资源，不应改无关文件或全机设置。']
], [n('For jobs of lengths 2 and 8 run shortest first, what is average completion time?','工期2和8，短任务先运行，平均完成时间是多少？',6,'Completion times are two and ten.','完成时刻2和10。','(2+10)/2=6.','(2+10)/2=6。'),q('A simulator’s result automatically measures production-kernel performance.','模拟器结果自动测得生产内核性能。',false,'The simulator omits or simplifies mechanisms.','模拟器省略或简化机制。','Its claims must remain inside the explicit model unless externally validated.','除非外部验证，结论仅适用于明确模型。')]);

add('S13.01','Layers, links and packet switching','分层、链路与分组交换',[['Encapsulation','封装'],['Packet switching','分组交换'],['Link versus path','链路与路径']], [
['A network connects endpoints through links and forwarding devices. Layering separates responsibilities: a link moves frames across one local connection, an internet layer routes packets across networks, transport serves endpoint communication, and applications define meaningful messages. Each layer offers a service while hiding some lower-level details, but failures can still cross those boundaries.','网络通过链路和转发设备连接端点。链路层跨本地连接传帧，网络层跨网络路由分组，传输层服务端点通信，应用层定义消息。分层提供服务并隐藏细节，但故障仍可跨层影响。'],
['Encapsulation places one layer’s data inside another layer’s packet, adding headers needed for its job. Packet switching shares links among independent packets rather than reserving a dedicated circuit for each conversation. Routers buffer packets when arrivals temporarily exceed transmission capacity; sustained overload creates growing delay and eventually loss.','封装把上层数据放入下层分组并加所需首部。分组交换共享链路，不为每次对话独占电路。到达暂超发送能力时路由器排队，持续过载导致延迟增长乃至丢包。'],
['A 1000-byte payload with a 40-byte network-and-transport header occupies 1040 bytes before link overhead. On a one-megabit-per-second link, serialization of those bytes takes 8320 microseconds. This is only the time to put bits onto the link; propagation, queueing, processing, and any retransmission contribute separately.','1000字节负载加40字节网络传输首部是1040字节，未计链路开销。1Mbps链路串行发送这些位需8320微秒，只是把位放上线的时间，传播、排队、处理、重传另计。'],
['An end-to-end path consists of several links with different capacities and delays. The slowest bottleneck can limit sustained throughput, while one-way latency includes delays across the whole path. Do not equate advertised bandwidth with application download speed. Protocol headers, shared traffic, congestion control, and endpoint processing all affect the delivered service.','端到端路径由容量延迟不同的链路组成，瓶颈限制持续吞吐，单向延迟累积全路径。标称带宽不等于应用下载速度，首部、共享流量、拥塞控制和端点处理都影响服务。']
], [n('How many bits are in 1040 bytes?','1040字节有多少位？',8320,'One byte is eight bits.','一字节八位。','1040×8=8320.','1040×8=8320。'),q('Serialization delay and propagation delay are the same phenomenon.','串行发送延迟和传播延迟是同一现象。',false,'One depends on bit count, the other on travel distance and medium.','一个依赖位数，另一个依赖距离与介质。','Even a tiny packet still needs time to propagate after its bits enter the link.','即使小分组，把位放上线后仍需传播时间。')]);
add('S13.02','Addressing and routing','寻址与路由',[['Prefix','前缀'],['Forwarding table','转发表'],['Routing convergence','路由收敛']], [
['An address identifies a network-layer interface within an addressing scheme. A prefix groups addresses sharing initial bits. Routing discovers or configures paths, while forwarding applies the resulting table to an individual packet. These are related tasks at different timescales; forwarding need not recompute a global route for every packet.','网络地址在寻址体系中标识接口，前缀分组初始位相同的地址。路由发现或配置路径，转发对单个包应用表，两者时间尺度不同，逐包不必重算全局路径。'],
['Longest-prefix matching chooses the most specific matching route. A default route matches when no more specific entry applies. Routers decrement a hop-limiting field so persistent forwarding loops eventually discard packets. A next hop is a local forwarding decision; the complete path emerges from decisions at successive routers.','最长前缀匹配选最具体路由，没有更具体项才用默认。路由器递减跳数限制字段，使持续转发环最终丢包。下一跳是本地决策，逐路由器决策组成全路径。'],
['Suppose routes cover 10.0.0.0/8 and 10.2.0.0/16. Destination 10.2.3.4 matches both, so /16 wins. In IPv4, a /24 prefix fixes twenty-four of thirty-two bits, leaving eight bits and 256 numerical addresses. Which addresses are usable as host addresses depends on the applicable network convention.','路由10.0.0.0/8与10.2.0.0/16都匹配10.2.3.4，选/16。IPv4的/24固定32位中24位，剩8位共256个数值地址；哪些能作主机地址取决于网络约定。'],
['Link-state routing distributes topology information and computes routes locally; distance-vector methods exchange estimates with neighbors. Failures take time to propagate, so transient loops or black holes can occur during convergence. Address translation and firewalls further affect reachability. A valid address alone does not prove that a working bidirectional path or permitted application service exists.','链路状态传播拓扑并本地算路，距离向量与邻居交换估计。故障传播需时间，收敛中可能临时环或黑洞。地址转换、防火墙也影响可达；地址有效不证明双向路径或应用获准。']
], [n('How many numerical IPv4 addresses are in a /24 block?','IPv4 /24块有多少数值地址？',256,'There are eight free bits.','有八个自由位。','2^8=256, before any usage conventions.','2^8=256，尚未考虑用途约定。'),q('When /8 and /16 both match, longest-prefix forwarding prefers /8.','/8和/16都匹配时，最长前缀优先/8。',false,'More fixed bits means a more specific route.','固定位越多越具体。','The /16 entry has the longer matching prefix.','/16具有更长匹配前缀。')]);
add('S13.03','Transport and congestion control','传输层与拥塞控制',[['Reliable byte stream','可靠字节流'],['Flow control','流量控制'],['Congestion window','拥塞窗口']], [
['Transport protocols serve communication between application endpoints, usually identified with ports. TCP provides an ordered reliable byte stream while the connection succeeds; UDP sends independent datagrams without built-in retransmission or ordering. TCP does not preserve the boundaries between separate application writes, so the application still needs its own message framing.','传输协议服务通常由端口标识的应用端点。TCP在连接成功期间提供有序可靠字节流，UDP发送独立报文且不内建重传排序。TCP不保留write边界，应用仍需消息分帧。'],
['Sequence numbers identify byte positions, acknowledgments report received progress, and retransmission repairs detected loss. Flow control protects the receiver’s buffer capacity. Congestion control limits how much outstanding data a sender injects into the shared network. A receiver with abundant memory does not imply that intervening links can carry unlimited traffic.','序号标字节位置，确认报告接收进展，重传修复丢失。流量控制保护接收缓冲，拥塞控制限制发往共享网络的在途数据；接收内存充足不代表沿途链路无限。'],
['With a usable window of 100000 bytes and round-trip time 0.1 seconds, a simple window-limited throughput bound is one million bytes per second, ignoring headers and loss. Raising link capacity alone cannot exceed that bound if the window stays unchanged. Conversely, a huge window cannot overcome a slower physical bottleneck.','可用窗口100000字节、往返0.1秒，忽略首部丢包时窗口限制吞吐为每秒一百万字节。窗口不变时仅增链路容量无法突破；大窗口也不能克服更慢物理瓶颈。'],
['Timeout estimates must adapt to variable delay; a delayed acknowledgment is not immediate proof that a peer has failed. Connection establishment and termination manage shared protocol state but do not guarantee that the application committed a requested operation. For retryable requests, define operation identifiers and duplicate handling above transport, especially when a reply may be lost after processing.','超时估计需适应延迟波动，确认迟到不立即证明对端失效。连接建立终止管理协议状态，却不保证应用已提交请求。回复可能在处理后丢失，因此重试请求应在传输之上定义操作标识与去重。']
], [n('A 100000-byte window over 0.1-second RTT gives how many bytes per second?','100000字节窗口、RTT0.1秒，窗口吞吐界是多少字节每秒？',1000000,'Divide window by RTT.','窗口除RTT。','100000/0.1=1000000.','100000/0.1=1000000。'),q('One TCP read must correspond to exactly one earlier TCP write.','一次TCP读取必对应此前恰好一次写入。',false,'TCP exposes a byte stream.','TCP是字节流。','Writes may be split or combined; applications must frame messages.','写入可被拆分合并，应用需分帧。')]);
add('S13.04','Application protocols','应用层协议',[['Message framing','消息分帧'],['Request semantics','请求语义'],['Name resolution','名称解析']], [
['An application protocol defines message syntax, meaning, ordering, and failure behavior. Framing tells a receiver where each message ends, using lengths, delimiters, or a structured stream format. A network connection supplies bytes, but only the protocol explains whether those bytes mean a name query, a document request, or a command.','应用协议定义消息语法、含义、顺序和失败行为。分帧用长度、分隔符或结构流确定消息结束。连接提供字节，协议才说明是名称查询、文档请求还是命令。'],
['DNS maps domain names to typed records such as addresses and uses caching with expiration. HTTP defines requests and responses with methods, status codes, fields, and representations. TLS can authenticate endpoints and protect transport confidentiality and integrity, but it does not decide whether a requested application action is authorized.','DNS把域名映射成地址等类型记录，缓存带过期。HTTP定义方法、状态码、字段和表示的请求响应。TLS可认证端点并保护传输机密完整，但不决定应用动作是否获授权。'],
['If a length-prefixed message says five bytes, receiving only two bytes is incomplete rather than malformed by itself; more bytes may arrive later. Reading seven bytes may contain the complete five-byte message plus the beginning of another. A parser must retain the remainder instead of dropping it or assuming each read is one message.','长度前缀说五字节而只收到两字节，可能只是未完整，后续仍会到。读到七字节可能含五字节消息与下一条开头，解析器应保留余量，不能每次read都视一条消息。'],
['Distinguish successful delivery from successful application processing. A response code and body together describe the result, and retry semantics depend on the operation. Idempotent operations can be repeated without changing the intended final effect beyond one application; this does not mean responses are identical or side effects such as logging never occur. Handle unknown fields and version changes according to the protocol contract.','区分送达与应用处理成功，状态码和正文共同说明结果，重试取决于操作语义。幂等是重复操作最终意图效果与一次相同，不代表响应完全一样或日志无副作用。未知字段和版本变化按协议约定处理。']
], [n('A five-byte framed message has received two bytes. How many payload bytes remain?','五字节消息已收两字节，还差多少？',3,'Subtract received length.','减已收长度。','5−2=3 bytes remain.','5−2=3字节。'),q('TLS alone proves that every application action is authorized.','仅TLS就证明所有应用动作获授权。',false,'Transport security and authorization have distinct roles.','传输安全与授权角色不同。','The server must still check permissions for the requested resource and operation.','服务端仍须检查资源与操作权限。')]);
add('S13.05','Reliability, latency and measurement','可靠性、延迟与测量',[['Round-trip time','往返时间'],['Loss rate','丢包率'],['Tail latency','尾延迟']], [
['Network measurement begins with a precise endpoint and event definition. Round-trip time includes a trip to the peer and a response; one-way delay requires synchronized clocks or another suitable method. Throughput counts delivered useful data per time, while raw link rate counts transmitted bits and can include protocol overhead or retransmissions.','网络测量先定义端点和事件。RTT含去返，单向延迟需同步时钟或合适方法。吞吐算单位时间交付有效数据，原始链路速率可含首部重传。'],
['Packet loss is a fraction over a stated set of attempts, not an intrinsic permanent label for a path. Queues can create highly variable delay even without loss. Report distributions or percentiles when rare slow requests matter; an average can hide a long tail that dominates user experience in a multi-request workflow.','丢包率是规定尝试集合的比例，不是路径永久标签。无丢包时队列也可有大延迟波动。罕见慢请求重要时应报分布分位数，均值可能隐藏影响多请求体验的长尾。'],
['For measured delays [10,10,10,10,110] milliseconds, the mean is thirty while the median is ten. A user waiting for all five requests waits at least until the slowest finishes. These statistics answer different questions. State the percentile convention when samples are small because interpolation rules can produce different numerical percentiles.','延迟[10,10,10,10,110]毫秒，均值30、中位数10。等待五个全部完成者至少等到最慢请求。指标回答不同问题；小样本分位数还需说明插值约定。'],
['A failed probe may reflect filtering or endpoint policy rather than a broken application path. Separate DNS resolution, connection establishment, protocol negotiation, and application response timing to localize failures. Avoid changing several network conditions simultaneously. Preserve raw samples and time windows so later comparisons do not confuse a different workload or route with an actual improvement.','探测失败可能是过滤或端点策略，而非应用路径坏。分开DNS、建连、协议协商、应用响应计时定位故障。避免同时改变多网络条件，保留原始样本和时间窗，防止把负载或路由差异当改进。']
], [n('What is the mean of 10,10,10,10,110 milliseconds?','10、10、10、10、110毫秒均值是多少？',30,'Sum and divide by five.','求和除五。','150/5=30 milliseconds.','150/5=30毫秒。'),q('A low mean latency rules out very slow individual requests.','低平均延迟排除了极慢个别请求。',false,'A small number of large values can hide in an average.','少量极大值可隐藏于均值。','Inspect tail percentiles or the full distribution.','应检查尾分位数或完整分布。')]);
add('S13.06','Network design and failure analysis','网络设计与故障分析',[['Failure domain','故障域'],['Redundancy','冗余'],['End-to-end check','端到端检查']], [
['Network design starts from communication requirements: which endpoints need to exchange what data, with what availability, latency, and trust boundaries. Draw the actual path through naming, routing, transport, authentication, and application processing. A diagram that shows only cables can hide dependencies whose failure makes every physical link irrelevant.','设计先问哪些端点交换何种数据，需要何种可用、延迟和信任边界。画出命名、路由、传输、认证、应用完整路径，仅画电缆会隐藏关键依赖。'],
['A failure domain groups components that can fail together, such as one power source or one upstream route. Redundancy improves resilience only when replicas avoid the relevant shared failure. Two servers in the same power circuit may survive one process crash but not a power outage. Health checks must test the service’s meaningful behavior.','故障域是可能一起失败的组件，如同电源或上游路由。冗余须避开相关共同故障；同电路两服务可抗进程崩溃，却不能抗断电。健康检查应测有意义服务行为。'],
['If two independent links each fail with probability 0.01 during a window, simultaneous failure probability is 0.0001. If both share a failed upstream device, independence is false and that multiplication is unjustified. The calculation’s usefulness depends on the dependency model, not only the arithmetic precision of the percentage.','两独立链路窗口故障概率各0.01，同时故障为0.0001。但若共用故障上游，独立性不成立，不能相乘。计算价值取决于依赖模型，不只是百分比精度。'],
['During diagnosis, verify one layer at a time and retain a known-good comparison path. Distinguish inability to resolve a name, inability to reach an address, rejected credentials, and an application error. Recovery procedures should be reversible and tested. A successful reconnection is evidence of current service, while preventing recurrence requires identifying the underlying mechanism and its trigger.','诊断逐层验证并保留正常对照路径，区分名称解析、地址可达、凭据拒绝和应用错误。恢复步骤应可逆并测试。重连成功仅说明当前服务恢复，防复发还需找机制与触发原因。']
], [n('For independent failure probabilities 0.01 and 0.01, what is their simultaneous failure probability?','独立故障概率各0.01，同时故障概率多少？',0.0001,'Multiply independent probabilities.','独立概率相乘。','0.01×0.01=0.0001.','0.01×0.01=0.0001。'),q('Two redundant endpoints always have independent failure risks.','两个冗余端点总有独立故障风险。',false,'They may share power, routes, or software dependencies.','可能共电源、路由或软件依赖。','Shared failure domains create correlation.','共享故障域造成相关。')]);

add('S14.01','Relational model and SQL','关系模型与SQL',[['Relation','关系'],['Selection and projection','选择与投影'],['Join','连接']], [
['A relation represents records with named attributes drawn from specified domains. In the mathematical model, rows form a set; SQL commonly permits duplicates unless constrained or removed. A schema describes the structure, while a database instance contains current data. Keeping these ideas separate helps distinguish a table definition from its changing contents.','关系用具名属性表示记录，属性来自规定域。数学关系是集合，SQL常允许重复，除非约束或去重。模式描述结构，实例是当前数据，应区分定义与变化内容。'],
['Selection filters rows by a condition; projection chooses columns; a join combines rows satisfying a relationship. SQL SELECT with WHERE expresses filtering and projection, while JOIN combines tables. An aggregate such as COUNT summarizes rows, and GROUP BY forms groups before aggregation. Row order is unspecified unless explicitly requested with ORDER BY.','选择按条件筛行，投影选列，连接组合满足关系的行。SQL的SELECT、WHERE、JOIN表达这些操作，COUNT等聚合汇总，GROUP BY先分组。未写ORDER BY时行序不保证。'],
['Suppose Students contains ids 1,2 and names Lin,Ada, while Scores contains (1,80),(1,90),(2,70). Joining on student id yields three rows because Lin has two scores. Grouping by id and averaging gives Lin 85 and Ada 70. A join does not automatically choose one matching row or remove duplicates.','Students有1 Lin、2 Ada，Scores有(1,80)、(1,90)、(2,70)。按id连接得三行，Lin两次成绩；按id平均得85和70。连接不会自动只选一匹配或去重。'],
['NULL denotes missing or unknown information and introduces three-valued logic in SQL conditions. A comparison with NULL is not ordinary equality; use the intended null test. Validate types and constraints at the database boundary. Construct SQL with parameter binding rather than string-concatenating untrusted values, so data remains separate from executable query syntax.','NULL表示缺失或未知，使条件出现三值逻辑，不能用普通相等比较，应使用相应空值测试。在数据库边界验证类型约束，使用参数绑定而非拼接不可信值，让数据与可执行语法分离。']
], [n('What is the average of Lin’s scores 80 and 90?','Lin的80与90平均是多少？',85,'Add then divide by two.','相加除二。','170/2=85.','170/2=85。'),q('Without ORDER BY, SQL promises rows in insertion order.','没有ORDER BY，SQL保证插入顺序输出。',false,'Relations do not imply an output ordering.','关系不隐含输出顺序。','Plans and storage layout may produce different valid row orders.','计划与布局可能产生不同合法行序。')]);
add('S14.02','Keys, dependencies and normalization','键、依赖与规范化',[['Candidate key','候选键'],['Functional dependency','函数依赖'],['Lossless decomposition','无损分解']], [
['A key identifies a row uniquely. A candidate key is a minimal attribute set with that property; a primary key is one selected candidate. A foreign key requires references to exist in a target key domain. These constraints describe permitted data, not merely convenient indexes or naming conventions in application code.','键唯一识别行，候选键是满足唯一性的最小属性集，主键是选定候选。外键要求引用目标键存在。这些是数据约束，不只是索引或代码命名习惯。'],
['A functional dependency X→Y means equal X values force equal Y values across all permitted records. Repeating a fact in many rows can cause update anomalies. Normalization decomposes schemas to reduce problematic redundancy while preserving intended dependencies where possible and ensuring that joining the pieces does not introduce false combinations.','函数依赖X→Y表示合法记录中X相等必使Y相等。事实多行重复会产生更新异常。规范化分解模式，减少冗余，尽量保依赖，并保证重新连接不产生虚假组合。'],
['In Enrollment(student,course,instructor), suppose each course has one instructor. Then course→instructor. Repeating the instructor for every student risks inconsistent updates. Split into Enrollment(student,course) and Course(course,instructor); joining on course restores the original information when the stated dependency holds. The student-course pair may identify enrollment even though neither field alone does.','Enrollment(student,course,instructor)若每课唯一教师，则course→instructor。每学生重复教师会更新不一致。拆Enrollment(student,course)与Course(course,instructor)，按course连接可恢复；选课键可能需学生与课共同组成。'],
['Normalization rules depend on genuine domain constraints, not accidental uniqueness in a small sample. A decomposition can lose information or generate spurious rows if its join relationship is not justified. Denormalization may improve measured workloads but requires an explicit consistency plan. First establish the correct logical model, then decide whether a physical optimization deserves duplicated data.','规范化依赖真实领域约束，不能看小样本偶然唯一。无依据分解可能丢信息或产生伪行。反规范化可改善测得负载，但需明确一致性方案；先建正确逻辑，再决定是否物理复制数据。']
], [n('A course with one instructor is taken by 100 students. How many instructor facts need storing in the normalized Course table?','一门课唯一教师、100学生选课，规范化Course表需存几条教师事实？',1,'Store the fact at the course level.','在课程层存事实。','One course-instructor row represents that shared fact.','一条课程教师记录表示共享事实。'),q('A dependency seen in a tiny sample is automatically a permanent domain rule.','小样本中的依赖自动成为永久领域规则。',false,'Future legal data may break the coincidence.','未来合法数据可能打破巧合。','Dependencies must come from the domain’s intended constraints.','依赖应来自领域实际约束。')]);
add('S14.03','Indexing and query planning','索引与查询计划',[['Search index','搜索索引'],['Selectivity','选择率'],['Join plan','连接计划']], [
['An index is an auxiliary representation that accelerates selected access patterns. B-tree-family indexes maintain ordered keys in a shallow hierarchy suited to block storage. Hash indexes support equality lookup but do not inherently provide sorted range traversal. Indexes consume storage and must be maintained when indexed data changes.','索引是加速特定访问的辅助表示。B树族以浅层有序结构适合块存储；散列索引适合等值，不天然支持有序范围。索引占空间，数据变化还需维护。'],
['A query planner chooses scans, join order, and physical algorithms using estimated row counts and costs. Selectivity is the fraction of rows satisfying a predicate. A highly selective condition may favor an index, while reading most rows can favor a sequential scan because repeated random lookups and table fetches become expensive.','计划器用估计行数和成本选择扫描、连接顺序及算法。选择率是满足条件比例。少量行可适合索引，读大多数行则顺序扫描可能更好，因为随机查找与回表昂贵。'],
['In a million-row table, a condition matching ten rows is more selective than one matching nine hundred thousand. An index can locate ten keys with far less work than scanning all rows, assuming suitable key order. A composite index on (course,student) naturally groups one course’s students; it does not guarantee equally efficient searches on student alone.','百万行中匹配10行比90万行更具筛选性，合适有序索引能少做很多工作。(course,student)复合索引自然聚合同课学生，却不保证只按student也同样高效。'],
['Statistics can become stale and skewed distributions can defeat average-based estimates. Inspect actual row counts and execution plans before adding indexes indiscriminately. A nested-loop join may be excellent for a tiny outer relation with indexed inner lookups, while a hash or merge join may suit larger sets. Optimization must preserve query semantics, including duplicates and null handling.','统计可过时，偏斜分布会破坏均值估计。加索引前看实际行数和计划。小外表配内表索引时嵌套循环很好，大集合可用散列或归并连接。优化必须保持重复与NULL等语义。']
], [n('Ten matches in a million rows have what selectivity fraction?','百万行匹配10行，选择率分数是多少？',0.00001,'Divide matching rows by total rows.','匹配数除总数。','10/1000000=0.00001.','10/1000000=0.00001。'),q('Adding an index has no cost for writes.','增加索引对写入没有成本。',false,'The auxiliary structure must stay consistent.','辅助结构要同步维护。','Inserts, deletes, and key updates may require extra index work.','插入、删除、改键会增加索引维护。')]);
add('S14.04','Transactions and concurrency','事务与并发',[['Atomicity','原子性'],['Isolation','隔离性'],['Serializable execution','可串行化']], [
['A transaction groups operations into one logical unit. Atomicity means its effects commit together or are rolled back according to the system contract. Isolation controls how concurrent transactions interact. Consistency is preservation of declared application and database rules, while durability concerns surviving failures after a successful commit. These properties address different failure modes.','事务把操作成逻辑单元。原子性按约定一起提交或回滚；隔离性控制并发交互；一致性保持应用数据库规则；持久性关心提交后故障存活，各性质处理不同失败。'],
['Serializable execution behaves like some sequential ordering of whole transactions, even if operations physically overlap. Weaker isolation can permit anomalies such as nonrepeatable reads or write skew. Locks and multiversion concurrency control are mechanisms used to implement isolation, but merely using a database transaction does not imply the strongest isolation level.','可串行化等效于完整事务某串行顺序，即使实际交叠。较弱隔离可有不可重复读或写偏。锁和多版本是实现机制，但用了事务不代表用了最强隔离。'],
['Two transactions each check that at least two doctors are on call, then each removes a different doctor. Under an insufficient isolation policy, both may see the original two and commit, leaving zero. Each individual update looked locally valid, yet the combined result violates the rule requiring at least one doctor on call.','两事务都检查至少两医生值班，再各取消不同医生。隔离不足时都看见原来的两人并提交，最终零人。单次更新看似合法，组合却违反至少一人值班规则。'],
['The remedy must protect the invariant, through an appropriate isolation level, locking strategy, or schema design. Serializable transactions may abort when conflicts occur; the application needs a safe retry policy for the entire logical unit. Keep external effects such as sending messages outside naive retry loops unless they have an idempotency or coordination mechanism.','修复需以隔离级别、锁或模式保护不变量。可串行化冲突可中止，应用需安全重试整个逻辑单元。发送消息等外部副作用不能盲目放重试循环，除非有幂等或协调机制。']
], [n('If two doctors each independently leave from an initial count of two, how many remain?','初始两医生，两人都独立离开，最后几人？',0,'Subtract both departures.','减去两次离开。','2−1−1=0, violating the at-least-one invariant.','2−1−1=0，违反至少一人。'),q('Serializable means transactions must physically run without any overlap.','可串行化要求事务实际完全不能重叠。',false,'It constrains the observable result.','它约束可观察结果。','Concurrent work is allowed if equivalent to some serial order.','只要等效某串行顺序，就允许并行工作。')]);
add('S14.05','Recovery and durability','恢复与持久性',[['Write-ahead log','预写日志'],['Checkpoint','检查点'],['Recovery test','恢复测试']], [
['A database may buffer modified pages in memory before writing them to storage. Crashes can interrupt these writes, so durability needs a recoverable record of committed changes. Write-ahead logging records the necessary change information before the corresponding data page is allowed to reach persistent storage, according to the database’s protocol.','数据库可能先在内存缓冲脏页，崩溃可打断写入。持久性需要可恢复的提交记录；预写日志按协议先持久记录必要变化，再允许对应数据页落盘。'],
['Recovery uses the log to restore a state consistent with committed transactions. Depending on the system, redo reapplies changes and undo removes incomplete effects. A checkpoint records progress and reduces how much history must be examined. It is not automatically a standalone backup because later recovery may still need log segments or additional data files.','恢复用日志得到与已提交事务一致状态。系统可重做变化、撤销未完成效果，检查点记录进展以缩短回放历史；它不自动等于独立备份，因为可能还需日志段或数据文件。'],
['Suppose a transfer subtracts ten from account A and adds ten to B. A crash after only one data page reaches storage must not permanently lose ten units. The transaction log and recovery rules preserve the all-or-nothing logical outcome even if physical pages were written at different moments. Atomicity is therefore supported across time, not just concurrent execution.','转账A减10、B加10，若只一页落盘就崩溃，不能永久丢10。日志与恢复保持全成全不成，即使物理页不同时写入；原子性也跨故障时间，不只是并发执行。'],
['A successful commit’s durability depends on configured flushing and storage guarantees. A backup is useful only if restoration works; test recovery on a separate environment with expected records and integrity checks. Replication can copy accidental deletion or corruption, so it is not automatically an independent backup. Define acceptable data loss and recovery time explicitly before choosing mechanisms.','提交持久性取决于刷新配置与存储保证。备份只有恢复成功才有用，应在独立环境测试记录与完整性。复制可能同步误删腐坏，并非自动独立备份。选机制前明确可接受数据损失与恢复时间。']
], [n('A transfer moves 10 from balances 40 and 20. What should the combined balance remain?','余额40和20间转10，总余额应保持多少？',60,'Transfer changes ownership, not the total.','转账改归属，不改总量。','40+20=60 before and after.','前后均40+20=60。'),q('A replica always protects against accidental deletion on the primary.','副本总能防主库误删。',false,'Replication may faithfully reproduce the deletion.','复制可能忠实重现删除。','Independent historical recovery is needed to restore pre-deletion state.','恢复误删前状态需独立历史恢复机制。')]);
add('S14.06','Data modeling and nonrelational systems','数据建模与非关系系统',[['Access pattern','访问模式'],['Document boundary','文档边界'],['Consistency model','一致性模型']], [
['Data modeling describes entities, relationships, constraints, and the operations the system must support. Relational tables emphasize explicit relationships and declarative queries. Document stores group nested data, key-value stores retrieve by key, and graph stores emphasize relationships. These categories describe useful tendencies, not universal guarantees of speed or scalability.','建模描述实体、关系、约束与操作。关系表强调显式关系和声明查询，文档库存嵌套，键值按键，图存储强调关系；这些是倾向，不是速度扩展的普遍保证。'],
['Choose aggregation boundaries from update and query needs. Embedding order items inside an order can make one-order retrieval simple, while copying a customer address into many orders requires deciding whether it is a historical snapshot or current shared truth. That semantic distinction determines whether later customer updates should change past orders.','聚合边界依更新查询决定。订单嵌入明细便于整单读取；多个订单复制地址时，要判断是历史快照还是当前共享事实，这决定后续地址变化应否改旧订单。'],
['If a customer places three orders, storing a shipping-address snapshot in each preserves what was used at purchase time. Storing only a reference retrieves the customer’s current address instead. Neither is inherently superior: they answer different questions. A sound schema names the distinction so future developers do not accidentally rewrite historical evidence.','客户三订单各存配送地址快照，可保留购买时地址；只存引用则得到当前地址。二者无绝对优劣，回答不同问题，模式应命名区别，防后续误改历史。'],
['Distributed data systems may trade coordination cost against freshness or availability under specified failures. Examine actual transaction scope, conflict behavior, indexing, and durability guarantees rather than assuming all nonrelational systems behave alike. Migration needs validation of counts, keys, relationships, and representative queries. A successful import command does not prove the new model preserves the intended information.','分布式系统在特定故障下权衡协调成本、新鲜度与可用。应查真实事务范围、冲突、索引和持久保证，不能把非关系系统视同。迁移验证数量、键、关系和查询；导入成功不证明语义保留。']
], [n('Three orders each need one historical address snapshot. How many snapshots are stored?','三订单各需一份历史地址快照，共几份？',3,'Each purchase has its own historical record.','每次购买有自己的历史记录。','One per order gives three snapshots.','每单一份，共三份。'),q('A historical address snapshot should always change when the current customer address changes.','历史地址快照总应随当前地址变化。',false,'A snapshot records the past event.','快照记录过去事件。','Changing it would erase the original shipping-address evidence.','改它会抹去原配送地址证据。')]);

add('S15.01','Requirements and decomposition','需求与分解',[['Observable requirement','可观察需求'],['Acceptance criterion','验收条件'],['Decomposition','分解']], [
['A requirement describes an observable need or constraint, not merely a preferred implementation. Distinguish user goals, functional behavior, and qualities such as latency or accessibility. Ambiguous words like fast or intuitive become useful only after identifying the user, task, conditions, and evidence that would demonstrate success.','需求描述可观察需要或约束，不只是偏好实现。区分用户目标、功能及延迟无障碍等质量。“快”“直观”需明确用户、任务、条件和成功证据才有用。'],
['Decompose a large goal into cohesive responsibilities with explicit inputs and outputs. Each component should have a reason to change that is understandable without inspecting the entire program. Requirements traceability links a need to its design and validation, helping detect both missing behavior and unnecessary features that consume effort without serving the user.','大目标分为职责内聚、输入输出清晰的组件，每个变化原因应无需通读全系统也能理解。需求追踪连接需要、设计和验证，帮助发现遗漏或无用户价值的额外功能。'],
['For an offline learning app, “save progress” can become: after completing a practice item, closing the app, and reopening on the same profile, the recorded attempt remains available. This criterion specifies a trigger, interruption, and observable outcome. It does not force a particular database or file format before those implementation choices are justified.','离线学习软件“保存进度”可细化为：完成练习、关闭、同档案重开后仍能看到尝试记录。它指定触发、打断和结果，不预先强制数据库或文件格式。'],
['Record assumptions and exclusions alongside acceptance criteria. A feature that works only while connected does not satisfy an offline requirement, even if its happy path looks polished. Split delivery into independently testable increments, but preserve the end-to-end user journey. Finishing every isolated component does not establish that their integration fulfills the original need.','验收条件同时记录假设与排除项。只联网可用不满足离线，即使顺畅界面漂亮。交付可拆独立验证增量，但须保留端到端旅程；组件各自完成不代表集成满足原需求。']
], [n('A journey has four required steps and only three work. How many required steps remain unresolved?','旅程四个必要步骤只有三个可用，还有几个未解决？',1,'Compare completed with required steps.','必要数减完成数。','4−3=1; the full journey is not yet complete.','4−3=1，完整旅程尚未完成。'),q('“Fast” without a workload or metric is a complete performance requirement.','没有负载指标的“快”是完整性能需求。',false,'A requirement needs observable acceptance conditions.','需求需可观察验收条件。','Define the operation, input scale, and acceptable measured latency.','应定义操作、规模及可接受实测延迟。')]);
add('S15.02','Interfaces, modularity and design','接口、模块化与设计',[['Contract','契约'],['Information hiding','信息隐藏'],['Dependency direction','依赖方向']], [
['An interface states how a component is used: operations, argument meanings, results, errors, and side effects. Its contract separates what callers may rely on from internal representation. Information hiding protects decisions likely to change, so callers need not know whether a collection is stored in an array, tree, or database.','接口说明操作、参数、结果、错误与副作用，契约区分调用者可依赖行为与内部表示。信息隐藏保护易变化决策，使调用者不必知道集合用数组、树或数据库。'],
['High cohesion means a module’s responsibilities belong together; low coupling limits knowledge shared across modules. Pass dependencies explicitly when it makes ownership and testing clearer. An abstraction should simplify a real variation or invariant, not add layers whose only purpose is to rename an existing function without reducing conceptual complexity.','高内聚指职责相关，低耦合限制跨模块知识。显式传依赖有助所有权和测试。抽象应简化真实变化或不变量，而非只给函数换名、增加层次却不减概念复杂度。'],
['A repository interface might provide saveAttempt and loadAttempts. The learning engine depends on those behaviors, while a file-backed implementation handles serialization. Replacing file storage with a database should preserve ordering, error behavior, and durability expectations promised by the interface. Matching method names alone does not establish substitutability.','仓储接口可有saveAttempt和loadAttempts，学习引擎依赖行为，文件实现处理序列化。换数据库应保持承诺的顺序、错误和持久性；方法同名不等于可替换。'],
['Specify who owns returned mutable objects and whether operations can partially succeed. Hidden shared state makes tests order-dependent and introduces surprising coupling. Keep error handling at a layer able to make a meaningful decision, while preserving enough diagnostic context. Good design is evaluated through changes and use cases, not solely through the number of patterns or classes employed.','说明返回可变对象谁拥有、操作能否部分成功。隐藏共享状态造成测试依赖顺序和意外耦合。错误应由能作决策的层处理并保留诊断。设计通过变化和用例评价，不以模式或类数量评分。']
], [n('If an interface promises results sorted by time, how many implementations may ignore that promise: zero or one?','接口承诺按时间排序，允许多少个实现忽略该承诺：0还是1？',0,'All valid implementations satisfy the contract.','所有合法实现都须满足契约。','Zero; callers may rely on the promised ordering.','0，调用者有权依赖承诺顺序。'),q('Two classes with identical method names are automatically interchangeable.','方法名相同的两类自动可互换。',false,'Behavioral contracts also matter.','行为契约也重要。','Errors, side effects, ordering, and preconditions can differ.','错误、副作用、顺序与前提可能不同。')]);
add('S15.03','Version control and collaboration','版本控制与协作',[['Commit','提交'],['Branch','分支'],['Merge conflict','合并冲突']], [
['Version control records changes as a history of meaningful snapshots. A commit identifies a state and its relationship to earlier states. A branch names a line of development, allowing work to diverge temporarily. Clear commit messages explain the problem and resulting behavior, making later review and fault investigation more reliable.','版本控制记录有意义快照历史，提交标识状态及其前驱，分支命名发展路线以暂时分叉。清楚提交说明问题和结果，便于评审与追错。'],
['A merge combines changes from different histories. A textual conflict means the tool cannot choose how overlapping edits should combine; semantic conflicts can remain even when text merges automatically. Review the combined behavior and run relevant validation. A clean merge is a statement about the merge algorithm, not a proof of software correctness.','合并结合不同历史。文本冲突是工具无法决定重叠编辑如何组合；自动文本合并后仍可有语义冲突。应评审合并行为并验证，干净合并不是正确性证明。'],
['Suppose one branch renames a function and updates its callers, while another adds a new caller using the old name. Files may merge without overlapping lines, yet the new caller now fails. Building the integrated result detects this dependency conflict. Reviewing only each isolated branch misses the interaction introduced by their combination.','一分支重命名函数并改旧调用，另一新增旧名调用。虽无重叠行可自动合并，新调用仍失败。构建集成结果可发现，单独评审各分支会漏掉组合互动。'],
['Keep unrelated changes separate enough to review and revert safely. Before public publication, exclude credentials, personal data, generated caches, and files without suitable redistribution rights. This is content review, not merely checking whether a push command succeeds. Coordinate ownership of shared files, and avoid rewriting published history in ways that silently invalidate collaborators’ references.','无关变化适当分开，便于评审回退。公开前排除凭据、个人数据、缓存与无再分发权文件，不能只看push成功。协调共享文件归属，避免改已发布历史而无声破坏协作者引用。']
], [n('Two branches each pass alone but their merged build fails. How many integrated states have been shown broken?','两分支单独通过但合并构建失败，已证实几个集成状态有问题？',1,'The combined state is a distinct artifact.','组合状态是独立产物。','The merged state is broken; isolated success does not cover it.','合并状态坏了，孤立成功不能覆盖它。'),q('An automatic conflict-free merge proves the resulting program is correct.','无冲突自动合并证明结果程序正确。',false,'Semantic dependencies can conflict without overlapping lines.','语义依赖可在无重叠行时冲突。','Integrated review and validation are still necessary.','仍需集成评审与验证。')]);
add('S15.04','Testing and verification strategy','测试与验证策略',[['Test oracle','测试判据'],['Boundary coverage','边界覆盖'],['Proof and testing','证明与测试']], [
['A test compares observed behavior with an expected property. The oracle may be a known value, independent implementation, invariant, or human-reviewed result. Unit tests isolate small behavior; integration tests exercise component interactions; end-to-end tests follow a user journey. Different layers reveal different defects and have different execution and maintenance costs.','测试比较观察行为与期望性质，判据可为已知值、独立实现、不变量或人工审查。单元测小行为，集成测交互，端到端测用户旅程，各自发现不同缺陷且成本不同。'],
['Choose cases that distinguish the specification from plausible wrong implementations. Boundary values, empty collections, repeated inputs, cancellation, and partial failures often expose missing assumptions. Property-based testing generates many inputs and checks general relations, while differential testing compares independent solvers. Neither becomes a mathematical proof merely because the test count is large.','选能区分规范和似是而非实现的用例。边界、空集、重复、取消、部分失败易暴露遗漏。性质测试生成输入查关系，对拍比较独立程序；数量大也不自动成为数学证明。'],
['For a sorting function, check that output is ordered and preserves the input multiset. Checking only ordering lets an implementation returning an empty list pass. For [3,1,3], valid output is [1,3,3], including both copies of three. The pair of properties captures more of the contract than one handpicked output example alone.','排序需检查有序且保留输入多重集，只查有序会让空列表冒充成功。[3,1,3]应得[1,3,3]，两个3都保留。两性质比单个手工答案覆盖更多契约。'],
['Formal verification proves selected properties under explicit assumptions and models. It does not automatically cover deployment configuration, usability, or omitted environmental behavior. Keep deterministic tests reproducible and distinguish flaky infrastructure failures from product defects. After finding a bug, add a regression test that fails for the original reason rather than mirroring the new implementation line by line.','形式验证在明确模型假设下证明所选性质，不自动覆盖部署、可用性或省略环境。确定测试应可复现，区分基础设施抖动与产品缺陷。回归测试要因原错误而失败，而不是逐行照新实现写。']
], [n('How many occurrences of 3 must a sort preserve from [3,1,3]?','排序[3,1,3]后必须保留几个3？',2,'Sorting changes order, not multiplicity.','排序改顺序，不改重数。','Both original copies must remain.','原来的两个都要保留。'),q('An empty result satisfies the complete contract of sorting any list because it is ordered.','空结果有序，因此满足任意列表排序的完整契约。',false,'The input multiset must also be preserved.','还必须保留输入多重集。','Ordering alone is insufficient for correctness.','仅有序不足以正确。')]);
add('S15.05','Reliability, delivery and maintenance','可靠性、交付与维护',[['Release artifact','发布产物'],['Observability','可观察性'],['Rollback','回退']], [
['Delivery turns source code into a versioned artifact that users can run in a specified environment. A successful build proves only that the build completed; installation, launch, data migration, and real workflows need their own checks. Record which artifact was tested so the released files can be linked to the evidence.','交付把源码变为特定环境可运行的版本产物。构建成功只证明构建完成；安装、启动、迁移、真实流程各需检查。记录被测产物，使发布文件可对应证据。'],
['Reliability concerns continued correct service under expected conditions and recoverable failures. Observability uses meaningful logs, metrics, and traces to understand internal behavior from outputs. Collect the minimum information needed for diagnosis, and avoid exposing secrets or unnecessary personal data. A verbose log without actionable context can obscure rather than explain failures.','可靠性关心预期条件和可恢复故障下持续正确服务。可观察性用日志、指标、追踪理解内部行为，收集诊断所需最少信息，不泄露秘密或多余个人数据。冗长无上下文日志反会掩盖故障。'],
['A schema migration adding a required field must handle older saved profiles. A default value, explicit conversion, or a clearly reported incompatibility is needed. Testing only a fresh empty database misses this path. A rollback plan must also consider whether old software can read data already transformed by the new version.','模式迁移新增必填字段必须处理旧档案，可默认、转换或明确不兼容。只测全新空库会漏此路径。回退还须考虑旧软件能否读新版本已转换数据。'],
['Maintain dependency versions, licenses, and reproducible build instructions alongside code. Use staged checks proportional to the change, then stop repeating unchanged tests without new evidence. Incident review should identify contributing mechanisms and corrective actions instead of assigning blame from incomplete logs. Long-term maintenance includes removing obsolete assumptions and updating documentation when behavior changes.','与代码一起维护依赖版本、许可证和可复现构建说明。按变化安排检查，没新证据不反复跑不变测试。故障复盘查机制和纠正，而非凭不完整日志归罪。长期维护要移除过时假设并同步文档。']
], [n('A release supports three existing profile formats but tests only one. How many supported formats remain untested?','发布支持三旧档案格式，仅测一种，还有几种未测？',2,'Compare supported with checked formats.','支持数减已测数。','3−1=2 supported formats lack evidence.','3−1=2种缺验证证据。'),q('A successful compilation proves that installation and migration both work.','编译成功证明安装和迁移都正常。',false,'These are separate behaviors.','它们是独立行为。','Each requires evidence from the appropriate runtime workflow.','各自需要相应运行流程证据。')]);
add('S15.06','Professional responsibility and project review','专业责任与项目评审',[['Evidence boundary','证据边界'],['Data stewardship','数据责任'],['Review rationale','评审理由']], [
['Responsible engineering describes capabilities and limitations accurately. Separate implemented behavior, automated tests, live validation, and future plans. A mockup may explain a design, but it should not be presented as a deployed service. Clear evidence boundaries let users make informed decisions about whether a system meets their needs.','负责任工程准确描述能力限制，区分实现、自动测试、现场验证和计划。原型可说明设计，但不能冒称已部署服务。清楚证据边界让用户判断是否满足需要。'],
['Data stewardship asks what information is necessary, who may access it, how long it is retained, and how it can be corrected or removed. Design defaults around the stated purpose rather than collecting everything because storage is cheap. Permissions are destination-specific: authorization for local work does not imply permission to publish private material.','数据责任问需要什么、谁可访问、留多久、如何修正删除。默认应围绕用途，而非因存储便宜就全收。授权针对目的地，本地工作授权不等于可公开私人材料。'],
['In a project review, explain the triggering problem, the resulting behavior, the meaningful tests, and remaining uncertainty. If a feature was checked only with synthetic data, say so. A reviewer can then decide which additional evidence is needed before relying on it with real users or more demanding workloads.','评审说明触发问题、结果行为、有效测试和不确定性。若只用合成数据验证，应明确说明，使评审者决定真实用户或更大负载前还需哪些证据。'],
['Respect attribution and redistribution conditions for code, text, and media. Accessibility and recoverability are product qualities, not decorative extras. When disagreeing with a proposed change, identify the concrete risk and a testable alternative. Professional judgment means matching claims to evidence and considering affected people, rather than hiding uncertainty behind impressive terminology or a successful demonstration.','尊重代码、文本、媒体署名与再分发条件。无障碍与可恢复是产品质量，不是装饰。反对方案应指出具体风险和可检验替代。专业判断要使声明匹配证据并考虑受影响者，不用术语或演示掩饰不确定。']
], [n('A feature has two verified environments out of five claimed ones. How many claims still lack environment-specific evidence?','声称支持五环境，只验证两种，还有几种缺专门证据？',3,'Subtract verified environments.','减已验证数。','5−2=3 claims remain unverified.','5−2=3项仍未验证。'),q('A polished demonstration removes the need to disclose material limitations.','漂亮演示免除了披露重要限制的需要。',false,'Presentation quality and evidence are separate.','展示质量与证据不同。','Users need limitations to assess whether the demonstrated system fits their use.','用户需限制信息判断系统是否适合用途。')]);

add('S16.01','Formal languages and finite automata','形式语言与有限自动机',[['Alphabet and language','字母表与语言'],['Deterministic transition','确定转移'],['Acceptance','接受']], [
['A formal language is a set of finite strings over an alphabet. A deterministic finite automaton has finitely many states, one start state, a transition for each state-symbol pair, and a set of accepting states. It reads the entire input and accepts exactly when the final state is accepting.','形式语言是字母表上的有限串集合。确定有限自动机有有限状态、初态、每状态字符对的转移及接受态，读完整输入后末态接受才接受。'],
['The current state summarizes the relevant prefix history. For binary strings containing an even number of ones, use states E and O. Reading zero preserves the state; reading one switches it. Start in E and accept E. The machine need not remember the full count because parity suffices for every future continuation.','偶数个1的二进制串只需E、O两态，读0不变，读1切换，初态E且接受E。不用记完整数量，因为奇偶足以决定任意后续。'],
['Reading 1011 follows E→O→O→E→O, so the string is rejected: it contains three ones. The empty string stays at E and is accepted because zero is even. A transition table or diagram must include every input symbol from every state; omitted cases otherwise leave the machine’s behavior undefined.','1011路径E→O→O→E→O，因此拒绝，含三个1。空串留E并接受，因为0为偶数。转移表应覆盖每态每字符，遗漏会使行为未定义。'],
['A nondeterministic automaton can have multiple possible transitions and epsilon moves. It accepts if at least one complete path accepts. Subset construction represents all currently possible states as one deterministic state, proving equivalent recognition power. Nondeterminism can reduce description size, but it does not make finite automata able to recognize every language requiring unbounded memory.','非确定自动机可有多转移和空转移，只要某完整路径接受即接受。子集构造把当前可能态集当确定态，证明识别能力相同。非确定可压缩描述，却不能识别任意需无界记忆的语言。']
], [n('How many parity states suffice to recognize an even number of ones?','识别1的个数为偶数需几个奇偶状态？',2,'Track even or odd.','记录偶或奇。','Two states distinguish the only relevant histories.','两态区分全部相关历史。'),q('An NFA accepts only if every possible run accepts.','NFA只有所有运行都接受才接受。',false,'Acceptance is existential over runs.','接受对运行是存在量词。','One accepting complete run is enough.','一个完整接受运行就够。')]);
add('S16.02','Regular expressions and closure','正则表达式与封闭性',[['Union and concatenation','并与连接'],['Kleene star','克莱尼星'],['Product construction','积构造']], [
['Formal regular expressions build languages from basic symbols using union, concatenation, and Kleene star. Union chooses either language, concatenation joins one string from each, and star allows any finite number of repetitions including zero. These formal expressions are equivalent in expressive power to finite automata. Some practical regex extensions exceed this formal model.','形式正则用基本符号、并、连接和星构造语言。并二选一，连接拼两串，星重复有限次包括零，表达能力与有限自动机相同；实际正则某些扩展超出此模型。'],
['Regular languages are closed under union, intersection, complement, concatenation, and star. Intersection can run two deterministic automata in parallel, storing a pair of states and accepting only when both accept. Complement swaps accepting and rejecting states of a complete deterministic automaton; doing this directly on an arbitrary NFA is not valid.','正则语言对并、交、补、连接、星封闭。交可并行跑两DFA，状态为状态对，双接受才接受。补可对完整DFA交换接受与拒绝，不能直接对任意NFA这样做。'],
['The expression 0*10* describes binary strings with exactly one one. It accepts 1,00100, and 0001, but rejects the empty string and 101. Intersecting it with the language of even-length strings adds a second constraint; a product automaton remembers both whether one has appeared and the current length parity.','0*10*表示恰一个1，接受1、00100、0001，拒绝空串和101。再与偶长度语言取交，积自动机同时记1是否出现及长度奇偶。'],
['Closure proofs are constructions, not just memorized lists. State what the new machine stores and why its acceptance corresponds exactly to the set operation. A language of equally many consecutive a symbols followed by b symbols is not regular; a finite number of states cannot retain an arbitrary unmatched count. This marks a memory boundary, not a failure of clever expression syntax.','封闭性证明需构造，说明新状态存什么及接受为何等价。先连续a后同数b的语言非正则，有限状态不能记任意未匹配数量，这是记忆边界，不是表达式写得不够巧。']
], [n('How many ones occur in every string described by 0*10*?','0*10*描述的串恰有几个1？',1,'Only the middle symbol is one.','只有中间符号为1。','The stars repeat zero symbols, not the one.','星重复的是0而非1。'),q('Complementing a language can always be done by flipping accepting states of an arbitrary NFA.','任意NFA直接反转接受态总能求补。',false,'NFA acceptance is existential, so rejection is universal.','NFA接受是存在，拒绝是全称。','Determinize and complete before applying the simple accepting-state flip.','应先确定化并补全，再简单反转。')]);
add('S16.03','Context-free grammars and pushdown automata','上下文无关文法与下推自动机',[['Grammar production','文法产生式'],['Parse tree','语法树'],['Stack memory','栈记忆']], [
['A context-free grammar has terminal symbols, nonterminal symbols, a start symbol, and productions replacing one nonterminal by a sequence. Repeated replacement derives terminal strings. A parse tree records how a string was generated and exposes its hierarchical structure, such as nested expressions or balanced parentheses.','上下文无关文法含终结符、非终结符、初始符和单非终结符替换产生式。反复替换导出终结串，语法树记录生成层级，如嵌套表达式和平衡括号。'],
['A pushdown automaton adds an unbounded stack to finite control. The stack can remember unmatched opening parentheses, popping when a matching close appears. Context-free languages are exactly those recognizable by nondeterministic pushdown automata. The stack’s last-in-first-out restriction is important: it is stronger than finite memory but weaker than unrestricted general computation.','下推自动机给有限控制加无界栈，可记未匹配左括号并遇右括号弹出。上下文无关语言恰由非确定下推识别。后进先出限制使其强于有限记忆，却弱于通用计算。'],
['Grammar S→aSb or ε generates equal numbers of a followed by b: ε,ab,aabb,aaabbb. Each use of aSb adds one symbol at each end; finally ε terminates. By contrast, a grammar that permits two distinct parse trees for the same terminal string is ambiguous, even if both trees print identical characters.','S→aSb或ε生成ε、ab、aabb、aaabbb；每次两端各加一，最后ε终止。同一终结串若有两棵不同语法树，则文法歧义，即使输出字符相同。'],
['Expression precedence can be encoded with separate nonterminals for sums, products, and atoms. A parser chooses or constructs a derivation, while semantic analysis later assigns meaning and checks conditions such as variable declaration. Do not confuse syntax acceptance with program correctness. A syntactically valid expression can divide by zero or refer to an undefined name.','表达式优先级可用和、积、原子不同非终结符编码。解析构造推导，语义分析再赋意义并检查声明。语法接受不等于程序正确，合法表达式仍可除零或用未定义名字。']
], [n('How many b symbols occur after applying S→aSb four times and then S→ε?','应用S→aSb四次再S→ε后有几个b？',4,'Each recursive production adds one b.','每次递归产生式加一个b。','Four applications add four b symbols.','四次增加四个b。'),q('A grammar is ambiguous if one string has two different parse trees.','一个串有两棵不同语法树就说明文法歧义。',true,'Ambiguity concerns structure, not printed equality.','歧义关心结构而非字符是否相同。','Distinct derivation structures can assign different interpretations to the same string.','不同推导结构可使同串有不同解释。')]);
add('S16.04','Turing machines and computability','图灵机与可计算性',[['Machine configuration','机器配置'],['Decider','判定器'],['Recognizer','识别器']], [
['A Turing machine has finite control and an unbounded tape divided into cells. Each step reads a symbol, writes a symbol, changes state, and moves the head according to a rule. A configuration includes tape contents, head position, and control state. This abstract model studies what can be computed, independently of a particular physical processor.','图灵机有有限控制和无界格带，每步读写符号、改态并移动头。配置包含带、头位置、状态。模型研究可计算什么，不依赖具体处理器。'],
['A decider halts on every input and answers yes or no correctly for a language. A recognizer must eventually accept members but may loop forever on nonmembers. The distinction is termination, not merely output format. Every decidable language is recognizable, while some recognizable languages have no decider.','判定器对每输入都停并正确回答是非；识别器对成员最终接受，对非成员可永远循环。区别是终止，不只是输出格式。可判定必可识别，反向不总成立。'],
['To decide whether a finite binary string contains a one, scan right until either a one appears or the input ends. Both outcomes halt, so this is a decider. A search that enumerates candidate mathematical proofs and accepts upon finding one is only a recognizer unless a separate argument guarantees a stopping rule when no proof exists.','判断有限二进制串是否含1，可向右扫到1或末尾，两种情况都停，因此是判定器。枚举数学证明、找到即接受的搜索，若无证明时没有保证终止，只是识别器。'],
['The Church–Turing thesis relates effective mechanical procedures to Turing-computable functions; it is a modeling thesis, not a theorem derived solely from the machine definition. Alternative standard models, such as sufficiently general register machines or lambda calculus, have equivalent computability power. Faster hardware changes resource limits, but cannot by itself turn an undecidable problem into a universally decidable one.','丘奇—图灵论题把有效机械过程对应图灵可计算，是建模论题，不只是定义推出的定理。足够一般寄存器机、λ演算等标准模型能力等价。更快硬件改变资源，却不能使不可判定问题普遍可判定。']
], [n('A recognizer accepts a member after 12 steps. How many more steps are required by the definition before that acceptance counts?','识别器12步接受成员，按定义还需多少步才算接受？',0,'Acceptance already satisfies the requirement.','接受已满足要求。','No additional waiting is needed once an accepting state is reached.','到达接受态后无需再等。'),q('A recognizer must halt on every nonmember.','识别器对每个非成员必须停机。',false,'Only member acceptance is guaranteed.','只保证成员最终接受。','It may reject or loop on nonmembers.','非成员可拒绝或循环。')]);
add('S16.05','Reductions and undecidability','归约与不可判定性',[['Reduction direction','归约方向'],['Contradiction','反证'],['Halting problem','停机问题']], [
['A reduction transforms instances of problem A into instances of problem B while preserving the answer. If B had an algorithm, the transformation plus that algorithm would solve A. Therefore, to show B undecidable using a known undecidable A, reduce A to B, not the other way around. Direction carries the logical force.','归约把A实例转为B并保持答案。若B有算法，则转换加算法可解A。用已知不可判定A证明B不可判定，必须A归约到B，方向决定逻辑。'],
['The halting problem asks whether an arbitrary program eventually stops on a given input. Assume a universal decider H exists. Construct a program D that, on program description x, loops when H says x halts on itself and halts when H says it does not. This construction makes opposite behavior explicit.','停机问题问任意程序给定输入是否终停。假设通用判定H存在，构造D：输入程序描述x，若H说x在自身输入停则D循环，否则D停，刻意取反。'],
['Run D on its own description. If H predicts halting, D loops; if H predicts looping, D halts. Either prediction contradicts H’s assumed correctness, so no such universal decider exists. The argument does not claim that no individual program’s termination can be proved; many particular loops and algorithms have straightforward termination proofs.','让D以自身描述运行，H预测停则D循环，预测循环则D停，两者都矛盾，所以无通用判定器。这不代表不能证明具体程序终止，许多循环算法有简单终止证明。'],
['A valid reduction must be computable and preserve both yes and no cases. Merely saying that two problems look difficult is insufficient. Undecidability concerns a family of unbounded inputs; bounded instances can be exhaustively analyzed in principle. Practical static analyzers remain useful by restricting the language, accepting incomplete answers, or proving selected properties under conservative assumptions.','归约需可计算并保持是与否两类，不能只说都难。不可判定针对无界输入族，有限界实例原则上可穷举。静态分析仍可限制语言、允许未知或保守证明所选性质而有用。']
], [n('To prove B undecidable from undecidable A, does the reduction go A→B? Enter 1 for yes, 0 for no.','由不可判定A证明B不可判定，应A→B吗？是填1否填0。',1,'A hypothetical B solver must solve A.','假设B可解要能推出A可解。','Transform A instances into B instances, then invoke the hypothetical B solver.','将A转B，再调用假设B求解器。'),q('Undecidability means no particular instance can ever be solved.','不可判定意味着任何具体实例都无法解决。',false,'It denies one total algorithm for all instances.','它否定覆盖所有实例的总算法。','Many individual instances can still be proved or computed.','许多具体实例仍可证明或计算。')]);
add('S16.06','Complexity classes and NP-completeness','复杂度类与NP完全性',[['P and NP','P与NP'],['Polynomial reduction','多项式归约'],['Completeness','完全性']], [
['P contains decision problems solvable in polynomial time by a deterministic algorithm. NP contains decision problems whose yes instances have polynomial-size certificates verifiable in polynomial time. Verification is different from discovering the certificate. The input length is measured in its encoding size, so a runtime polynomial in a numeric value may not qualify.','P含确定算法多项式时间可解判定问题，NP含是实例有多项式长证书且可多项式验证者。验证不同于寻找，输入规模按编码长度，数值多项式不一定合格。'],
['A problem is NP-hard if every NP problem reduces to it in polynomial time. It is NP-complete if it is both NP-hard and in NP. To prove a new B NP-hard, reduce a known NP-hard A to B. Showing B reduces to an easy problem would instead provide an algorithmic upper bound for B.','NP难指每个NP问题多项式归约到它，NP完全还需属于NP。证B难应把已知难A归约到B；若B归约到容易问题，反而给B算法上界。'],
['For a graph Hamiltonian-cycle certificate, list the vertices in cyclic order. A verifier checks that each vertex appears once and that every consecutive pair, including the last-to-first pair, is an edge. This takes polynomial time even though finding such an order is not known to have a general polynomial-time algorithm.','哈密顿环证书可列顶点循环次序。验证每点恰一次，所有相邻对含末到首均有边，耗多项式时间；但一般寻找次序尚无已知多项式算法。'],
['NP does not mean non-polynomial, and NP-completeness is not a proof that polynomial algorithms are impossible: P versus NP remains unresolved. Practical approaches include exact exponential algorithms, parameterized methods, approximation, and special-case structure. An optimization problem should be related carefully to its decision version before assigning a complexity-class label or invoking a reduction theorem.','NP不意为非多项式，NP完全也未证明不可能多项式，因为P与NP未决。实践可用指数精确、参数化、近似或特例结构。优化题应先正确关联判定版再贴复杂度类标签。']
], [n('A Hamiltonian-cycle certificate on seven vertices should list how many distinct vertices?','七顶点哈密顿环证书应列几个不同顶点？',7,'Every vertex appears exactly once.','每顶点恰一次。','All seven must occur, with the closing edge checked separately.','七个都要出现，闭环边另行检查。'),q('NP-complete currently proves that no polynomial-time algorithm can exist.','NP完全已证明不可能存在多项式算法。',false,'P versus NP is unresolved.','P与NP仍未解决。','Such an algorithm would imply P=NP, which is not known to be impossible.','该算法会推出P=NP，但尚未证明不可能。')]);

add('S17.01','Syntax and parsing','语法与解析',[['Token','词法单元'],['Precedence','优先级'],['Abstract syntax tree','抽象语法树']], [
['A language frontend first turns source characters into tokens such as identifiers, numbers, and operators. Lexing recognizes token boundaries; parsing organizes tokens according to a grammar. Whitespace may separate tokens without appearing in the final tree. Source positions should be retained so later errors can point to the actual problematic text.','前端先把字符变为标识符、数、运算符等词法单元。词法分析识别边界，语法分析按文法组织。空白可分隔却不进入最终树，应保留源位置以准确报错。'],
['An abstract syntax tree records the essential program structure while omitting punctuation that only guides parsing. Precedence decides which operator binds more tightly; associativity resolves equal-precedence sequences. Recursive-descent parsing often assigns separate functions to precedence levels, while table-driven methods use explicit parsing states and grammar-derived decisions.','抽象语法树保留本质结构，省略仅辅助解析的标点。优先级决定紧密程度，结合性处理同级序列。递归下降常按优先级分函数，表驱动则用状态与文法决策。'],
['The expression 2+3*4 parses as addition with right child multiplication, yielding fourteen. Parentheses in (2+3)*4 change the tree so multiplication becomes the root, yielding twenty. A parser that simply processes operators left to right would compute the second structure for the first expression and violate the language’s precedence rules.','2+3*4解析为加法根、右子乘法，值14；(2+3)*4使乘法为根，值20。若一律从左到右处理，会对第一式算出第二结构，违反优先级。'],
['Syntax recovery should avoid turning one missing delimiter into dozens of misleading errors. A parser must still reject invalid inputs rather than silently inventing arbitrary semantics. Distinguish lexical errors, such as an invalid number token, from grammatical errors, such as a missing operand. Successful parsing proves grammatical structure, not correct names, types, termination, or runtime behavior.','错误恢复应避免一个缺分隔符引出几十条误导报错，但仍须拒绝非法输入而非随意补意义。区分非法数字等词法错与缺操作数等语法错。解析成功不证明名字、类型、终止或运行正确。']
], [n('Under ordinary arithmetic precedence, what is 3+2*5?','通常优先级下3+2*5是多少？',13,'Multiply before adding.','先乘后加。','2×5=10, then 3+10=13.','2×5=10，再3+10=13。'),q('A successfully parsed program is necessarily free of type errors.','语法解析成功必无类型错误。',false,'Type checking is a later semantic task.','类型检查是后续语义任务。','A grammatically valid expression can combine incompatible types.','语法合法表达式仍可组合不兼容类型。')]);
add('S17.02','Semantics and type systems','语义与类型系统',[['Evaluation rule','求值规则'],['Typing judgment','类型判断'],['Soundness','可靠性']], [
['Syntax says how a program is formed; semantics says what it means. Operational semantics describes execution as state transitions or evaluation rules. A type system assigns categories to expressions and restricts combinations before or during execution. A type judgment is a claim under an environment of assumptions, not a guess based only on the expression’s spelling.','语法规定形成方式，语义规定意义。操作语义用状态转移或求值规则描述执行。类型系统给表达式分类并限制组合，类型判断基于环境假设，不仅看字面。'],
['For integer addition, both operands must have integer type and the result is integer. A conditional expression may require a Boolean condition and compatible branch types. Static checking rejects some invalid programs before running them, while dynamic checks inspect runtime values. Neither style automatically prevents every logical error or proves that a loop terminates.','整数加法要求双整数并产整数，条件式可能要求布尔条件与兼容分支类型。静态检查运行前拒绝部分非法程序，动态检查查看运行值，二者都不自动防全部逻辑错或证明循环终止。'],
['In an environment where x:int and flag:bool, x+1 has type int and flag&&true has type bool. The expression x&&flag is rejected in a language that forbids integer-to-Boolean conversion. Another language may define a conversion, changing which programs are legal without changing the underlying mathematical meaning of integer addition.','环境x:int、flag:bool下，x+1为int，flag&&true为bool。禁止整数转布尔的语言会拒绝x&&flag；另一语言可定义转换，合法程序集合因而不同。'],
['Type soundness is commonly expressed through preservation, evaluation maintains the assigned type, and progress, a well-typed nonvalue can take a permitted step. These theorems depend on the exact language and runtime model. Unsafe features, foreign interfaces, or unspecified arithmetic can sit outside a theorem’s assumptions, so state the scope of any safety claim explicitly.','类型可靠性常由保持性和进展性表达：求值保持类型，良类型非值可继续合法一步。定理依精确语言模型；不安全功能、外部接口或未规定算术可能不在假设内，应明确安全声明范围。']
], [n('If x:int equals 6, what is the integer value of x+1?','x:int且x=6时，x+1整数值多少？',7,'Apply integer addition.','用整数加法。','6+1=7 with result type int.','6+1=7，类型为int。'),q('Static typing alone proves that every accepted program terminates.','静态类型本身证明所有接受程序终止。',false,'Many typed languages permit infinite loops.','许多有类型语言允许无限循环。','Termination requires stronger restrictions or a separate proof.','终止需更强限制或另证。')]);
add('S17.03','Scope, binding and evaluation','作用域、绑定与求值',[['Lexical scope','词法作用域'],['Closure','闭包'],['Evaluation strategy','求值策略']], [
['A binding associates a name with a value, location, or declaration. Scope defines where that association can be used. Lexical scope follows the program’s written nesting structure, while dynamic scope follows active calls. Shadowing introduces a nearer binding with the same name; it does not necessarily modify the outer binding.','绑定把名字关联值、位置或声明，作用域规定哪里可用。词法作用域跟随代码嵌套，动态作用域跟随活动调用。遮蔽引入同名更近绑定，不一定修改外层。'],
['A closure pairs function code with the environment needed for its free variables. Capturing by value stores a value, while capturing by reference observes a location whose lifetime must remain valid. Evaluation strategy determines when arguments are computed: eager evaluation computes before the call, while lazy evaluation defers work until its result is needed.','闭包把函数代码与自由变量所需环境配对。值捕获存值，引用捕获观察位置且需生存期有效。急切求值先算参数，惰性等结果被需要才算。'],
['Let outer x=4 and create a function that returns x+1 under lexical scope. If an unrelated caller has its own x=100, that caller’s variable does not replace the captured binding. A value capture of four returns five. A reference capture can observe later changes to the original x, provided that original object is still alive.','外层x=4，词法函数返回x+1。无关调用者自己的x=100不会替换捕获绑定。值捕获4返回5；引用捕获可看原x后续变化，但原对象须仍存活。'],
['Argument evaluation order can matter when expressions have side effects. Do not assume a particular order unless the language specifies it. Lazy evaluation also changes which effects or errors occur when an argument is unused. Rename bound variables carefully during substitution to avoid capturing a formerly free name; correct substitution preserves binding relationships, not just character strings.','参数有副作用时求值顺序重要，语言未规定就不能假定。惰性还改变未用参数的效果或错误是否发生。代换中重命名需避免捕获原自由名，正确代换保绑定关系而非仅替字符。']
], [n('A value closure captures x=4 and returns x+1. What does it return after another variable named x becomes 100?','值闭包捕获x=4并返回x+1，另一个同名变量变100后返回多少？',5,'Its captured binding remains four.','捕获绑定仍为4。','4+1=5; unrelated shadowing does not change the capture.','4+1=5，无关遮蔽不改变捕获。'),q('A reference closure remains safe even after its captured local object is destroyed.','引用闭包在捕获局部对象销毁后仍安全。',false,'The reference’s target must remain alive.','引用目标必须存活。','Otherwise accessing the dangling captured reference is invalid.','否则访问悬空捕获引用无效。')]);
add('S17.04','Intermediate representations','中间表示',[['Three-address code','三地址码'],['Control-flow graph','控制流图'],['SSA','静态单赋值']], [
['A compiler uses intermediate representations to separate source-language details from target-machine details. A useful representation makes selected program properties explicit, such as control flow, data dependencies, or types. No single representation is best for every transformation, so compilers often move through several levels while preserving program meaning.','编译器用中间表示分离源语言与目标机器细节，显式表达控制流、数据依赖或类型等性质。没有一种表示适合全部变换，常逐级转换并保持意义。'],
['Three-address code breaks complex expressions into simple operations with named temporary results. Basic blocks contain straight-line instructions with one entry and a terminating control transfer. A control-flow graph connects possible successor blocks. Analyses compute facts over this graph, such as which definitions can reach a use or which values remain live.','三地址码把复杂表达式拆为带临时结果的简单操作。基本块顺序执行，单入口并以控制转移结束；控制流图连接后继。可分析定义到达使用或值是否活跃。'],
['The expression a+b*c becomes t1=b*c and t2=a+t1. Static single assignment gives each variable version exactly one defining assignment. When branches assign different versions and later merge, a phi function selects the incoming version associated with the predecessor edge taken. It is a representation of control-dependent choice, not an ordinary eager arithmetic operation.','a+b*c拆t1=b*c、t2=a+t1。SSA每变量版本恰一定义；分支赋不同版本后汇合，用phi按实际前驱边选输入版本，它表示依控制的选择，不是普通急切算术。'],
['IR invariants must be checked after transformations: uses need valid definitions, control-flow edges need valid destinations, and type relationships must remain coherent. Debug locations connect transformed operations to source positions. An optimization that works on one representation may be invalid after lowering changes memory or exception behavior, so preserve and document the assumptions required by each compiler pass.','变换后需检查IR不变量：使用有定义、边有目标、类型一致。调试位置关联源码。某表示上合法优化在降低后可能因内存或异常行为失效，应记录每遍所需假设。']
], [n('How many simple operations represent a+b*c in the shown three-address expansion?','所示三地址展开a+b*c有几次简单操作？',2,'One multiplication and one addition.','一次乘一次加。','The two temporaries separate the two operations.','两个临时结果分离两次操作。'),q('An SSA phi selects its input based on the incoming control-flow edge.','SSA的phi根据进入控制流边选择输入。',true,'Different predecessors define different versions.','不同前驱定义不同版本。','The selected value corresponds to the predecessor actually taken.','所选值对应实际进入的前驱。')]);
add('S17.05','Optimization and code generation','优化与代码生成',[['Semantic preservation','语义保持'],['Liveness','活跃性'],['Register allocation','寄存器分配']], [
['Compiler optimization changes representation to improve a cost while preserving the language’s observable behavior. Constant folding evaluates known expressions early; dead-code elimination removes results with no observable use. The definition of observable behavior can include I/O, exceptions, volatile accesses, and specified floating-point effects, so unused-looking code is not automatically removable.','优化改善代价同时保持语言可观察行为。常量折叠提前算已知式，死代码删无可观察用途结果。观察可能含I/O、异常、volatile和指定浮点效果，因此看似未用不一定可删。'],
['Code generation maps IR operations to machine instructions and obeys calling conventions. Register allocation assigns frequently used values to a limited set of registers. Two values whose live ranges overlap cannot share the same physical register unless one is spilled or recomputed. Liveness means a value may be used along a future path before being redefined.','生成代码把IR映射指令并遵守调用约定。寄存器分配把值放有限寄存器，活跃区间重叠不能共用，除非溢出到内存或重算。活跃表示未来路径在重定义前可能使用。'],
['If t1 is needed after t2 is computed, their live ranges overlap and they need distinct storage. If t1’s last use occurs before t2 is defined, the same register can hold both at different times. Spilling stores a value to memory and reloads later, trading extra instructions and memory traffic for feasibility.','若t2算出后仍要用t1，两者活跃重叠需独立存储；若t1最后使用先于t2定义，则可不同时共享寄存器。溢出保存到内存再重载，用额外指令与访存换可行。'],
['Algebraic rewrites need domain checks. Replacing x/x by one fails at zero and may differ for special floating-point values. Reordering floating-point additions can change rounding. Benchmark the final generated program rather than assuming fewer source expressions means faster execution. Correctness, compile time, code size, energy, and runtime are separate optimization objectives.','代数改写需条件，x/x改1在零和特殊浮点可能失败，重排浮点加法可改舍入。应测最终程序，不能以源码表达式更少推断更快。正确、编译时间、大小、能耗、运行是不同目标。']
], [n('Two simultaneously live values with no spilling require at least how many distinct registers?','两个同时活跃值且不溢出，至少需几个不同寄存器？',2,'Both must be retained at once.','二者须同时保留。','Two distinct storage locations are required.','需要两个不同存储位置。'),q('Replacing x/x by 1 is valid for every integer x.','对所有整数x，把x/x改1都合法。',false,'Check x=0.','检查x=0。','Division by zero is not the value one and may be invalid or signal an error.','除零不是1，可能无效或报错。')]);
add('S17.06','Building a small compiler or interpreter','构建小型编译器或解释器',[['Language specification','语言规范'],['Interpreter pipeline','解释流程'],['Conformance tests','符合性测试']], [
['Begin with a deliberately small language and write its semantics before implementing it. A useful first language contains numeric literals, variables, arithmetic, and explicit output. Define precedence, numeric range, division behavior, undefined names, and error messages. A small precise language teaches more than a large collection of features with inconsistent rules.','先选小语言并写语义，再实现。可从数值、变量、算术、输出开始，定义优先级、范围、除法、未定义名与错误。精确小语言优于规则矛盾的大功能集合。'],
['Build separate lexer, parser, semantic checker, and evaluator stages with explicit inputs and outputs. The evaluator traverses an AST using an environment that maps names to values. A compiler backend instead emits another representation or machine code. Both approaches should preserve the same defined source semantics for supported programs.','分开词法、解析、语义检查、求值阶段。求值器遍历AST，环境映射名字到值；编译后端则输出另一表示或机器码。二者应保持支持语言的相同语义。'],
['For let x=3; print x*4+1;, lex names and punctuation, parse multiplication below addition in the tree, bind x to three, then evaluate the print expression to thirteen. A test of print y should report an undefined name, not silently supply zero, unless default-zero behavior was explicitly part of the language specification.','let x=3; print x*4+1;先分词，树中乘法紧于加法，绑定x=3后输出13。print y应报未定义，而不是默默给0，除非默认零是明确规范。'],
['Test malformed tokens, missing delimiters, nested expressions, shadowed names, and arithmetic boundaries as well as successful examples. Give each error a source location. If adding loops, include an execution budget for the teaching environment without claiming that the budget proves termination. The finished interpreter is complete only for its stated language subset, not automatically compatible with C++ or another full language.','测试非法词、缺分隔、嵌套、遮蔽、算术边界，也测成功例，错误带源位置。加入循环可设教学执行预算，但预算不证明终止。解释器只对规定子集完整，不自动兼容C++等完整语言。']
], [n('What should let x=3; print x*4+1 output?','let x=3; print x*4+1应输出多少？',13,'Evaluate multiplication before addition.','先乘后加。','3×4+1=13.','3×4+1=13。'),q('Silently inventing a zero value for every unknown name preserves a language that specifies undefined-name errors.','为未知名默默补0保持了规定未定义错误的语言语义。',false,'The specified observable behavior is an error.','规定的可观察行为是错误。','Returning a value changes the language rather than implementing its contract.','返回值改变了语言，而非实现契约。')]);

add('S18.01','Search and symbolic reasoning','搜索与符号推理',[['State-space model','状态空间模型'],['Heuristic','启发函数'],['Logical entailment','逻辑蕴含']], [
['Symbolic AI represents states, actions, goals, and rules explicitly. Search explores possible action sequences, while logical inference derives statements from a knowledge base. A model’s conclusions are only as sound as its assumptions and representation: a missing obstacle or incorrect rule can produce a perfectly executed but practically invalid plan.','符号AI显式表示状态、动作、目标和规则。搜索探索动作序列，逻辑推理由知识库导出命题。模型结论依赖假设与表示，漏障碍或错规则会让执行完美的计划实际无效。'],
['A* prioritizes states by f=g+h, where g is cost already incurred and h estimates remaining cost. An admissible heuristic never overestimates the true remaining cost. With suitable graph-search handling, consistency supports safe closed-state behavior. Heuristics change exploration order; they must not silently change the definition of a legal action or goal.','A*按f=g+h排序，g已付成本，h估剩余。可采纳h不高估真实剩余，一致性配适当图搜索支持安全关闭状态。启发改变探索顺序，不能悄改合法动作或目标。'],
['On a four-neighbor grid with unit movement costs and no teleportation, Manhattan distance |x−xg|+|y−yg| is a lower bound because each move changes that distance by at most one. From (1,2) to (4,6), it is seven. Obstacles can lengthen the actual route but cannot make this lower bound too large.','四邻接单位代价格无瞬移时，曼哈顿距离是下界，因为每步至多缩短一。从(1,2)到(4,6)为7。障碍可增长真实路径，但不使此下界过大。'],
['Logical entailment means every model satisfying the premises also satisfies the conclusion. It differs from a statistical prediction that is often right. Rule systems need explicit treatment of unknown facts: failure to prove a statement is not generally proof of its negation. Compare predicted plans with environment feedback, especially when actions can fail or observations are incomplete.','逻辑蕴含指每个满足前提的模型都满足结论，不同于通常准确的统计预测。规则系统须处理未知：证不出不通常等于证伪。动作可失败、观察不全时，要把计划与环境反馈比较。']
], [n('What is Manhattan distance from (2,1) to (5,5)?','(2,1)到(5,5)曼哈顿距离多少？',7,'Add absolute coordinate differences.','相加坐标绝对差。','|5−2|+|5−1|=3+4=7.','3+4=7。'),q('Failure to prove a proposition always proves its negation.','无法证明命题总能证明其否定。',false,'The available information may be incomplete.','现有信息可能不完整。','Both the statement and its negation may remain unknown.','命题与否定都可能仍未知。')]);
add('S18.02','Supervised learning and evaluation','监督学习与评估',[['Training example','训练样本'],['Generalization','泛化'],['Data leakage','数据泄漏']], [
['Supervised learning fits a mapping from features to labeled targets using examples. Regression predicts numerical values; classification predicts categories or their probabilities. The goal is performance on new relevant data, not merely memorizing training examples. Define the deployment population before selecting samples, features, and evaluation metrics.','监督学习由特征标签样本拟合映射，回归预测数值，分类预测类别或概率。目标是在相关新数据表现好，而非记住训练样本；采样特征指标前先定义部署总体。'],
['Split data into training, validation, and test roles. Training fits parameters, validation selects modeling choices, and the held-out test estimates performance after choices are settled. Repeatedly choosing based on test scores leaks information into selection. Related observations, such as records from the same person or future timestamps, may require grouped or chronological splitting.','训练拟参数，验证选模型，最终测试在选择结束后估性能。反复按测试分选型会泄漏。相同人多记录或未来时间数据可能需分组或时间顺序划分。'],
['In a dataset with ninety negative and ten positive cases, always predicting negative achieves ninety-percent accuracy but finds none of the positive cases. Recall is true positives divided by actual positives; precision is true positives divided by predicted positives when that denominator is nonzero. The useful metric depends on the task’s error costs.','90负10正时全猜负准确率90%却找不到任何正例。召回为真正/实际正，精确率为真正/预测正且分母非零。合适指标取决于误差代价。'],
['Preprocessing parameters, including scaling and imputation, must be fitted using training information only before applying them elsewhere. Report sample counts, uncertainty, and subgroup behavior when meaningful. A high benchmark score does not prove causality or robustness to a changed environment. Keep a simple baseline so added complexity must demonstrate an actual improvement under the same evaluation conditions.','缩放、填补等预处理参数只用训练信息拟合，再应用他处。报告样本数、不确定性和相关分组表现。高分不证明因果或环境变化稳健；保留简单基线，使复杂度需在同条件证实收益。']
], [n('A model finds 6 of 10 actual positive cases. What is recall?','10个实际正例找出6个，召回率多少？',0.6,'Divide found positives by actual positives.','找到数除实际数。','6/10=0.6.','6/10=0.6。'),q('Fitting preprocessing on the test set can leak evaluation information.','用测试集拟合预处理可泄漏评估信息。',true,'Even unlabeled distribution information can influence modeling.','即使无标签分布也可影响建模。','Keep fitted preprocessing inside the training pipeline.','拟合预处理应留在训练流程内。')]);
add('S18.03','Linear models and optimization','线性模型与优化',[['Prediction function','预测函数'],['Loss function','损失函数'],['Gradient descent','梯度下降']], [
['A linear predictor has the form yhat=w·x+b, combining features through weights and an intercept. Linear refers to parameters in this representation; engineered nonlinear features can still produce a linear-in-parameters model. A loss function measures disagreement with targets, and training searches for parameters that reduce aggregate loss.','线性预测yhat=w·x+b由权和截距组合特征。线性指该表示的参数，非线性特征仍可产生参数线性模型。损失衡量目标偏差，训练寻找降低总损失的参数。'],
['For squared error, large residuals receive quadratically increasing penalties. Gradient descent updates parameters opposite the loss gradient: w_new=w−η∇L. The learning rate η controls step size. Excessive steps can overshoot or diverge, while tiny steps progress slowly. Feature scaling affects the geometry and conditioning of the optimization problem.','平方误差对大残差二次惩罚。梯度下降w_new=w−η∇L沿负梯度，η控步长，过大可越过或发散，过小慢。特征尺度影响几何与条件数。'],
['For L(w)=(w−3)², the derivative is 2(w−3). Starting at w=0 with η=0.1 gives w_new=0−0.1×(−6)=0.6, moving toward three. This one-dimensional example exposes the same update principle used with many parameters; vector gradients simply collect all partial derivatives.','L(w)=(w−3)²导数2(w−3)。w=0、η=0.1时新值0.6，向3靠近。多维用收集各偏导的梯度，更新原理相同。'],
['Regularization penalizes selected parameter complexity, such as squared weight magnitude, to control variance or impose prior preferences. It changes the objective rather than proving better performance universally. Logistic regression uses a sigmoid to model binary probabilities and commonly minimizes cross-entropy. Numerical stability, convergence checks, and held-out evaluation remain necessary even when the model formula is simple.','正则惩罚如权平方大小以控方差或加入偏好，它改变目标，不普遍证明更好。逻辑回归用sigmoid建二类概率，常最小化交叉熵。即使公式简单，也需稳定数值、收敛检查和留出评估。']
], [n('For L(w)=(w−3)² at w=0, what is the derivative?','L(w)=(w−3)²在w=0导数多少？',-6,'Use 2(w−3).','用2(w−3)。','2(0−3)=−6.','2(0−3)=−6。'),q('A larger learning rate always reaches a minimum faster.','学习率越大总越快到最小值。',false,'A step can overshoot the stable region.','步长可能越过稳定范围。','Large updates can oscillate or diverge instead of converging.','大更新可振荡或发散。')]);
add('S18.04','Trees, kernels and ensembles','决策树、核与集成',[['Decision split','决策划分'],['Kernel similarity','核相似性'],['Ensemble','集成']], [
['A decision tree recursively partitions feature space using tests such as x1≤c. Leaves store predictions. Splits are chosen to improve an impurity or loss measure on training data. Deep unrestricted trees can fit noise, so stopping rules, pruning, or validation-based complexity control are needed to support generalization.','决策树用x1≤c等测试递归分特征空间，叶存预测，训练按纯度或损失改善选划分。无限深可拟合噪声，需停止、剪枝或验证控制复杂度。'],
['Kernel methods express similarity through a function corresponding to an inner product in a possibly implicit feature space. This can represent nonlinear decision boundaries without explicitly listing all transformed features. A valid kernel must satisfy the relevant positive-semidefinite conditions; an arbitrary convenient similarity formula is not automatically a valid kernel.','核方法用函数表示可能隐式特征空间内积，无需列全部变换特征就能表达非线性边界。有效核需相应半正定条件，任意方便相似度不自动是核。'],
['An ensemble combines multiple predictors. Bagging trains on resampled datasets to reduce instability, while boosting builds predictors sequentially to address remaining errors under a chosen loss. If three binary classifiers predict yes,yes,no, a majority vote returns yes. Their benefit depends on useful accuracy and diversity, not simply counting how many models are included.','集成组合多个预测器。装袋用重采样减不稳定，提升按损失逐步补错误。三个预测yes、yes、no多数为yes；收益依赖准确与差异，不只是模型数量。'],
['Correlated errors limit ensemble gains: ten copies of the same mistaken model do not provide ten independent pieces of evidence. Tune depth, regularization, and ensemble size using validation data. Explain feature importance cautiously because correlated predictors and model-specific attribution can distort interpretation. Predictive usefulness of a split does not establish that intervening on that feature causes the target to change.','相关错误限制收益，十份同错模型不是十份独立证据。深度正则规模用验证选。特征重要性受相关特征和归因方法影响，划分有预测力不证明干预该特征会造成目标变化。']
], [n('Five classifiers vote yes,yes,no,yes,no. How many vote yes?','五分类器yes、yes、no、yes、no，有几个yes？',3,'Count the affirmative votes.','数肯定票。','Three of five vote yes, giving the majority.','五中三票yes，占多数。'),q('Copying one model many times creates independent prediction evidence.','把一个模型复制多次会产生独立预测证据。',false,'Copies share the same errors.','复制品有相同错误。','Diversity of useful information, not duplicate count, enables ensemble gains.','有效信息差异而非副本数量带来集成收益。')]);
add('S18.05','Neural networks and representation','神经网络与表示',[['Layer','层'],['Nonlinearity','非线性'],['Backpropagation','反向传播']], [
['A neural network composes parameterized transformations. A dense layer computes an affine map followed by an activation function. Without nonlinear activations, any stack of affine layers collapses into one affine map, so depth alone would not create the intended expressive power. Hidden representations are learned intermediate features, not automatically human-interpretable concepts.','神经网络复合参数变换。全连接层先仿射再激活；无非线性时多层仍可合成一个仿射，深度本身不增所需表达能力。隐藏表示是学习特征，不自动对应可解释人类概念。'],
['Backpropagation applies the chain rule efficiently through the computation graph to obtain loss gradients for every parameter. An optimizer uses those gradients to update parameters. The backward pass computes sensitivity; it does not itself decide which loss, data, architecture, or evaluation protocol is appropriate for the task.','反向传播沿计算图高效用链式法则求各参数损失梯度，优化器据此更新。反传计算敏感度，不负责决定任务该用何损失、数据、架构或评估。'],
['For z=wx+b and ReLU output max(0,z), take x=2,w=3,b=−1. Then z=5 and output five. At a positive z, the derivative of output with respect to w is x=2. For negative z, the ReLU output is zero and its local derivative is zero; at zero a convention is needed.','z=wx+b，ReLU=max(0,z)。x=2,w=3,b=−1得z=5、输出5；z正时对w导数为x=2。z负时输出与局部导数为0，零点需约定。'],
['Training may be limited by overfitting, vanishing or exploding gradients, data quality, and distribution shift. Report architecture and training conditions, and separate a teaching visualization from a measured model. More parameters do not automatically imply better calibration or reasoning. Reproducible evaluation and uncertainty checks are necessary before using predictions in consequential decisions.','训练受过拟合、梯度消失爆炸、数据质量与分布变动限制。报告架构条件，区分教学图示与实测模型。更多参数不自动保证校准或推理更好，重要用途前需可复现评估与不确定检查。']
], [n('For x=3,w=2,b=−1, what is ReLU(wx+b)?','x=3,w=2,b=−1时ReLU(wx+b)是多少？',5,'Compute the affine value before clipping at zero.','先仿射再与0取大。','2×3−1=5, which remains five.','2×3−1=5，保留5。'),q('Stacking affine layers without nonlinearities always creates a nonlinear function.','叠加无非线性激活的仿射层总产生非线性函数。',false,'Affine maps compose to an affine map.','仿射复合仍仿射。','Nonlinearity must enter through an operation that is not affine.','非线性必须来自非仿射操作。')]);
add('S18.06','Uncertainty, bias and responsible evaluation','不确定性、偏差与负责评估',[['Calibration','校准'],['Distribution shift','分布变化'],['Error analysis','误差分析']], [
['A prediction can be uncertain because observations are noisy, the model lacks knowledge, or the input differs from training conditions. A probability score is meaningful only relative to an event and population. Calibration asks whether events assigned probability p occur about a fraction p of the time in comparable cases.','预测不确定可因噪声、模型知识缺失或输入异于训练。概率分数须对应事件总体；校准问在可比情况中预测p的事件是否约p比例发生。'],
['Bias can arise in sampling, measurement, labeling, feature selection, objectives, or deployment. Overall accuracy can conceal very different subgroup errors. Select subgroup analyses from the task and affected populations, while considering sample size and uncertainty. Statistical disparity requires investigation, and a single summary metric cannot by itself settle every fairness or suitability question.','偏差可来自采样、测量、标签、特征、目标或部署。总体准确掩盖群体误差差异，分析应依据任务与人群且考虑样本不确定。差异需调查，单指标不能解决所有公平适用问题。'],
['If one hundred predictions each claim probability 0.8 and only fifty corresponding events occur, the group is overconfident relative to the observed frequency. This small calibration check is not a full assessment: selection, dependence, and sampling variability matter. Reliability diagrams compare predicted probabilities with outcome frequencies across bins containing enough observations.','一百次都报0.8却只发生五十次，观察上该组过度自信。但选择、相关、抽样波动仍重要；可靠性图在足够样本分箱比较预测概率与实际频率。'],
['Keep test data representative of the intended use and monitor changes in data collection or behavior. Abstention can be appropriate when uncertainty is high, but its coverage and error trade-off must be measured. Document failure modes and human review paths. A benchmark number supports only the tested distribution and protocol, not an unrestricted claim of intelligence or safety.','测试应代表用途，并监测收集或行为变化。高不确定可拒答，但需测覆盖与误差权衡。记录失败模式与人工复核路径，基准数值仅支持该分布协议，不支持无限智能或安全声明。']
], [n('Fifty observed events out of one hundred predictions give what empirical frequency?','一百次预测观察五十次事件，经验频率是多少？',0.5,'Observed events divided by trials.','发生数除试验数。','50/100=0.5.','50/100=0.5。'),q('A model with excellent overall accuracy must have equally good accuracy for every subgroup.','总体准确极好必意味着所有子群同样好。',false,'Averages can hide uneven errors.','平均会隐藏不均误差。','Small or difficult subgroups may perform poorly despite a strong aggregate score.','小或难群体可表现差而总体仍高。')]);

add('S19.01','Threat models and trust boundaries','威胁模型与信任边界',[['Asset','资产'],['Adversary capability','对手能力'],['Trust boundary','信任边界']], [
['A threat model identifies what must be protected, from whom, under which assumptions. Assets include data, availability, integrity, and authority to perform actions. An adversary’s capabilities might include supplying malformed input, observing network traffic, or controlling a client. Explicit capabilities make a security claim testable instead of relying on the vague statement that a system is secure.','威胁模型说明保护什么、面对谁、假设什么。资产含数据、可用、完整及操作权限。对手可能输入畸形数据、看流量或控制客户端，明确能力使安全声明可检验。'],
['A trust boundary is where data or control crosses between differently trusted components. Treat input crossing that boundary as untrusted until validated for its intended use. Validation at one layer does not automatically authorize every later operation. A well-formed filename can still name a resource that the caller must not access.','信任边界是不同信任组件间的数据控制跨越处。跨界输入需按用途验证。一层验证不自动授权后续所有操作，格式合法文件名仍可能指向无权资源。'],
['For an offline lesson importer, assets include existing progress and local files. A imported JSON object may be syntactically valid but contain unknown fields, oversized strings, or unsupported version numbers. A narrow schema, size limits, and a preview before replacement address those capabilities without giving the importer permission to execute code or choose arbitrary filesystem paths.','离线课程导入要保护旧进度与本地文件。JSON语法合法也可能含未知字段、巨长字符串或不支持版本。窄模式、大小限制、替换前预览可处理，而无需允许执行代码或任意路径。'],
['Separate prevention, detection, containment, and recovery. A threat model should include accidental failures as well as intentional misuse when both affect the same assets. Revisit it when adding features such as code execution, networking, or plugins, because those introduce new authority. Security review is strongest when each claimed control is tied to a concrete boundary and failure scenario.','分开预防、检测、限制影响和恢复，相关时也包括意外故障。加入执行代码、联网、插件会引入新权限，需重审模型。每个控制应关联具体边界和失败场景。']
], [n('An importer allows at most 1000 characters but receives 1200. How many exceed the limit?','导入限1000字符，收到1200，超出多少？',200,'Subtract the allowed size.','收到量减限额。','1200−1000=200 excess characters.','1200−1000=200。'),q('Syntactically valid input is automatically authorized input.','语法合法输入自动拥有授权。',false,'Format and permission are different checks.','格式与权限是不同检查。','A valid request can still target an unauthorized resource.','合法请求仍可能针对无权资源。')]);
add('S19.02','Cryptographic primitives and protocols','密码原语与协议',[['Encryption','加密'],['Authentication tag','认证标签'],['Digital signature','数字签名']], [
['Encryption aims to protect message confidentiality using a key. A cryptographic hash maps data to a fixed-size digest with specified resistance goals, such as collision resistance. A message authentication code uses a shared secret to authenticate data; a digital signature uses a private signing key and a public verification key. These primitives provide different guarantees.','加密用密钥保护机密，密码哈希输出固定摘要并要求抗碰撞等性质。MAC用共享秘密认证，数字签名用私钥签、公钥验，原语保证不同。'],
['A protocol combines primitives with identities, nonces, ordering, and state. Authenticated encryption protects confidentiality and integrity together under its assumptions. Many schemes require nonce uniqueness for a given key; reusing a nonce can destroy security even when the algorithm itself is reputable. Key generation and storage are part of the system, not optional finishing touches.','协议组合原语与身份、随机数、顺序和状态。认证加密在假设下兼顾机密完整，许多方案要求同密钥nonce唯一；重用可破坏安全，即使算法可靠。密钥生成保存也属于系统。'],
['If a receiver verifies a MAC on message bytes but does not include a transaction identifier or freshness rule, an attacker may replay an old valid message unchanged. The tag still verifies because the bytes are authentic. Preventing replay therefore requires protocol context, not merely a stronger hash or a longer encryption key.','若MAC验证消息却无事务标识或新鲜性规则，攻击者可重放旧合法消息，标签仍正确，因为字节确实真实。防重放需要协议上下文，不是换更强哈希或更长密钥。'],
['Use reviewed libraries and standardized constructions rather than inventing a cipher from reversible arithmetic. Passwords need dedicated slow password-hashing schemes with salts; a fast general-purpose hash is not an equivalent substitute. Never treat encoding, compression, or obscured variable names as encryption. State which adversary and failure assumptions a cryptographic claim actually covers.','使用审查过库与标准构造，不用自创可逆运算当密码。密码存储需带盐专门慢哈希，快速普通哈希不等价。编码、压缩、混淆变量名不是加密；声明应说明覆盖何对手和假设。']
], [n('A protocol accepts each unique transaction identifier once. A valid message with an already used identifier arrives again. How many new transactions should occur?','协议每唯一事务号只接受一次，已用号消息再次到达，应产生几个新事务？',0,'Freshness is checked separately from authenticity.','新鲜性独立于真实性检查。','Zero; the duplicate must not repeat the effect.','0，重复不能再产生效果。'),q('Encryption alone always detects message tampering.','单独加密总能检测篡改。',false,'Confidentiality and integrity are distinct properties.','机密与完整是不同性质。','Use an authenticated construction when integrity is required.','需要完整性时应使用认证构造。')]);
add('S19.03','Authentication and authorization','身份认证与授权',[['Identity proof','身份认证'],['Permission decision','权限决策'],['Session','会话']], [
['Authentication establishes evidence about who or what is requesting access. Authorization decides whether that identity may perform a particular operation on a particular resource. A valid login does not imply unlimited authority. Keep these decisions distinct in the design so every sensitive operation checks the permission relevant to its actual target.','认证建立请求者是谁的证据，授权决定该身份能否对特定资源做特定操作。登录有效不代表无限权，设计应分开，使每敏感操作检查真实目标权限。'],
['A session associates later requests with an authenticated interaction, often through a secret token. Tokens require protection, expiration, and invalidation rules. Multi-factor authentication combines distinct factor categories, such as something known and something possessed; two passwords remain one category. Recovery procedures must not become an easier bypass of the primary authentication design.','会话常用秘密令牌关联后续请求，需保护、过期和撤销。多因素组合知识与持有等不同类别，两密码仍是一类。恢复流程不能成为比主认证更易绕过的入口。'],
['A student may read their own progress but not modify another student’s record. Changing a record identifier in a request must trigger a new ownership or permission check on the server. Hiding another student’s button in the interface is helpful presentation, but a crafted request can bypass that interface and still reach the operation.','学生可读自己进度，不能改别人记录。请求改记录号后服务端须重新查所有权权限。界面隐藏别人按钮只是展示，构造请求可绕过界面直达操作。'],
['Prefer explicit allow rules and deny access when required identity or permission information is missing. Minimize privilege granted to service accounts and separate administrative functions from ordinary activity. Audit meaningful decisions without logging passwords or session secrets. Authorization must be enforced at the resource boundary, including background jobs and internal APIs that bypass the main user interface.','优先明确允许规则，缺必要身份权限时拒绝。服务账号最小权限，管理与普通操作分离。审计有意义决策但不记密码会话秘密。授权须在资源边界执行，也涵盖后台任务和内部API。']
], [n('A user owns one of five records. Under an owner-only policy, how many may they modify?','用户拥有五记录中的一条，仅所有者可改时能改几条？',1,'Apply permission per resource.','逐资源检查权限。','Only the one owned record is authorized.','只有自己那一条获授权。'),q('Hiding a forbidden action’s button is sufficient authorization enforcement.','隐藏禁止动作按钮就足以执行授权。',false,'Requests can be made without that interface.','可不经过界面发请求。','The receiving service must verify permission independently.','接收服务必须独立验证权限。')]);
add('S19.04','Memory and application security','内存与应用安全',[['Bounds','边界'],['Injection','注入'],['Lifetime','生存期']], [
['Memory safety requires accesses to refer to live objects and remain within permitted bounds. Out-of-bounds writes, use-after-free, and invalid pointer arithmetic can corrupt state or violate isolation. Safe containers and ownership disciplines reduce risk, but their contracts still matter: unchecked indexing or retaining invalidated references can defeat otherwise good abstractions.','内存安全要求访问活对象且不越界。越界写、释放后用、非法指针算术可破坏状态隔离。安全容器和所有权降风险，但未检查下标或失效引用仍可破坏抽象。'],
['Injection occurs when untrusted data is interpreted as instructions in another language, such as SQL, HTML, or a shell. Separate data from code using parameter binding or context-appropriate encoding. Escaping for one context is not automatically correct for another; a string safe as HTML text may be unsafe inside a script or command argument.','注入是把不可信数据当SQL、HTML或shell指令。应参数绑定或按上下文编码。一个上下文转义不自动适用于另一处，HTML文本安全不代表脚本或命令参数安全。'],
['For an array of length four, valid zero-based indices are zero through three. Accepting index four is one element past the end. At an SQL boundary, a name containing quote characters should remain a data value in a bound parameter, rather than being concatenated into the query grammar. These examples share the principle of enforcing the correct interpretation boundary.','长四数组零基合法0到3，4越过末端。SQL中含引号名字应作为绑定数据，不拼进语法。两例共同要求在正确解释边界执行约束。'],
['Validate lengths before allocation and conversion, check arithmetic used to compute buffer sizes, and fail coherently on invalid input. Fuzzing explores many malformed cases; sanitizers expose some memory errors on executed paths. They complement, rather than replace, secure design and code review. Test only controlled applications and data for which the testing scope is explicitly authorized.','分配转换前查长度，查缓冲大小计算算术，非法输入一致失败。模糊测试探索畸形，检测器发现执行路径部分内存错，补充而非代替安全设计评审。只测明确授权的受控应用数据。']
], [n('What is the largest valid zero-based index of a length-six array?','长度六数组最大合法零基下标是多少？',5,'Indices start at zero.','下标从零开始。','The range is 0 through 5.','范围0到5。'),q('Escaping a string for HTML text automatically makes it safe as a shell command.','HTML文本转义自动使字符串可安全当shell命令。',false,'The parsers and special characters differ.','解析器与特殊字符不同。','Use the target context’s data interface rather than reusing unrelated escaping.','应使用目标上下文数据接口，而非复用无关转义。')]);
add('S19.05','Network and systems defense','网络与系统防护',[['Attack surface','攻击面'],['Defense in depth','纵深防御'],['Recovery readiness','恢复准备']], [
['An attack surface is the set of exposed interfaces through which a system can be influenced. Reduce unnecessary services, privileges, and dependencies before adding complex monitoring. Defense in depth uses controls with different failure modes, so one mistake does not immediately expose every protected resource. More controls are useful only when their interactions remain understandable.','攻击面是可影响系统的暴露接口集。先减少不必要服务权限依赖，再加复杂监控。纵深防御用失败方式不同的控制，避免一个错误全盘暴露，但控制交互仍须可理解。'],
['Network filtering limits permitted communication paths; host hardening constrains local capabilities; updates repair known defects; backups support recovery. None substitutes for all the others. Segmentation can restrict lateral movement after one component fails, but a permitted channel still needs authentication, authorization, and robust input handling.','网络过滤限路径，主机加固限本地能力，更新修已知缺陷，备份支持恢复，不能互相完全替代。分段可限制失陷后横移，但允许通道仍需认证授权与稳健输入。'],
['A database intended only for the local app should not need an externally reachable listener. Removing that listener eliminates one class of remote access path. If remote access is required later, introduce it deliberately with a narrow interface and tested identity controls, rather than treating network exposure as a harmless configuration convenience.','仅供本地应用的库不必有外网监听，移除可消掉一类远程路径。以后需远程时，应有意加入窄接口和已测身份控制，不能当无害配置便利。'],
['Monitor meaningful events, define alert thresholds, and rehearse response with controlled scenarios. Protect logs from unauthorized alteration while minimizing sensitive content. Recovery includes restoring data, revoking compromised credentials, and confirming that the entry mechanism is addressed. A service returning online is not proof that the same failure cannot recur or that data integrity has been preserved.','监控有意义事件、设阈值并受控演练响应。保护日志不被篡改且少敏感内容。恢复含数据、撤销失陷凭据与处理入口；服务上线不证明不复发或数据完整。']
], [n('A host needs two services but exposes five. How many unnecessary services should be reviewed for removal?','主机需两服务却暴露五，几项不必要服务应审查移除？',3,'Compare required with exposed services.','暴露数减所需。','5−2=3 unnecessary interfaces increase surface.','5−2=3项扩大攻击面。'),q('A firewall removes the need to validate input on allowed connections.','防火墙免除了允许连接上的输入验证。',false,'Allowed traffic can still contain malformed data.','允许流量仍可含畸形数据。','The application boundary must remain robust.','应用边界仍须稳健。')]);
add('S19.06','Controlled security analysis','受控安全分析',[['Scope','范围'],['Reproduction','复现'],['Remediation verification','修复验证']], [
['A controlled security analysis begins with explicit authorization, defined targets, permitted techniques, and stopping conditions. Use a local training application or disposable test environment when learning. The objective is to understand a failure mechanism and verify a repair, not to explore unrelated accounts, production resources, or third-party systems outside that scope.','受控分析先明确授权、目标、方法和停止条件。学习可用本地训练或可丢环境，目标理解机制并验修复，不探索范围外账号、生产或第三方系统。'],
['Document expected behavior, observed behavior, minimal triggering input, affected boundary, and plausible impact. Separate confirmed effects from hypothetical consequences. A proof of a malformed-input crash is not automatically proof of arbitrary code execution. Preserve enough evidence to reproduce the issue without collecting unnecessary secrets or personal information.','记录预期、观察、最小触发、边界和合理影响，区分确认与假想。畸形输入崩溃不自动证明任意代码执行。保留可复现证据但不收多余秘密个人信息。'],
['For a toy parser accepting a declared length followed by bytes, test zero length, exact length, truncated data, and a size exceeding the documented limit. A correct repair checks the limit before allocation and checks remaining bytes before reading. A regression test should demonstrate that the formerly failing case now returns a controlled error.','玩具解析器读声明长度再读字节，可测零、恰好、截断、超上限。修复应分配前查上限、读取前查剩余。回归应证明旧失败现返回受控错误。'],
['Retest normal behavior and neighboring boundary cases after the fix, because rejecting every input would prevent the crash while destroying the feature. Review root cause rather than adding a special case for one literal payload. Finish by cleaning the disposable test state and recording remaining uncertainty. Communicate findings through the project’s authorized review process with concrete evidence and a reproducible repair description.','修后还测正常与邻边界，全拒绝虽不崩却毁功能。查根因，不只为某字面输入加特例。结束清理可丢测试状态并记不确定，通过授权评审渠道给证据和修复说明。']
], [n('A parser declares 8 bytes but only 5 remain. How many bytes are missing?','解析器声明8字节但剩5，缺多少？',3,'Compare declared and available lengths.','声明减可用。','8−5=3; it must not read past the available buffer.','8−5=3，不能越过可用缓冲读取。'),q('Rejecting every input is a complete repair for a parser that must accept valid messages.','拒绝所有输入是必须接受合法消息解析器的完整修复。',false,'The functional contract still matters.','功能契约仍重要。','A repair must reject invalid cases while preserving valid behavior.','修复须拒非法且保合法行为。')]);

add('S20.01','Geometric transformations','几何变换',[['Coordinates','坐标'],['Affine transform','仿射变换'],['Composition order','复合顺序']], [
['A geometric object can be represented by points and vectors in a coordinate system. Translation changes position, rotation changes orientation, and scaling changes size along selected axes. Distinguish points from displacement vectors: translating a point changes its location, while the same translation does not change a displacement between two points.','几何对象用坐标中的点和向量表示。平移改位置，旋转改朝向，缩放改各轴尺度。点与位移向量不同，平移点改位置，同平移不改变两点间位移。'],
['Homogeneous coordinates append an extra coordinate so affine transformations fit matrix multiplication. In three dimensions, points use a final coordinate one and direction vectors zero. Multiplying matrices composes transformations, but order matters. Conventions for row versus column vectors determine written multiplication order and must remain consistent throughout a graphics pipeline.','齐次坐标加一维使仿射变换可用矩阵乘。三维点末坐标1，方向0。矩阵复合通常不交换，行或列向量约定决定书写顺序，管线须一致。'],
['In two dimensions, start at (1,0). Rotate ninety degrees counterclockwise to (0,1), then translate by (2,0), reaching (2,1). Reversing the operations first gives (3,0), then (0,3). The different results show why a model rotating around its own center differs from orbiting a world-space origin.','二维(1,0)先逆时针九十度到(0,1)，再平移(2,0)得(2,1)。反过来先到(3,0)再旋到(0,3)。这说明自转与绕世界原点公转不同。'],
['Normals require special handling under nonuniform scaling: transform them with the inverse transpose of the linear transform, then normalize when appropriate. Applying the point transform directly can destroy perpendicularity. Singular transformations, such as scaling an axis to zero, lack an inverse and need explicit treatment. Keep units and coordinate-frame names visible when connecting graphics to physical simulation.','非均匀缩放下法向用线性变换逆转置，再适当归一；直接按点变换会失垂直。某轴缩到零等奇异变换无逆，应明确处理。连接物理模拟时应标单位与坐标系。']
], [n('After translating point (3,2) by vector (−1,4), what is its y coordinate?','点(3,2)平移(−1,4)后y坐标多少？',6,'Add the y components.','相加y分量。','2+4=6.','2+4=6。'),q('Rotation and translation always commute.','旋转和平移总可交换。',false,'Their order changes which origin is used.','顺序改变所绕原点关系。','The worked points reach different final positions.','例题得到不同最终位置。')]);
add('S20.02','Cameras and projection','相机与投影',[['View transform','观察变换'],['Perspective divide','透视除法'],['Clipping','裁剪']], [
['A virtual camera defines a coordinate frame for viewing the scene. The view transform expresses world points relative to that camera. Projection then maps three-dimensional positions toward a two-dimensional image. Orthographic projection keeps apparent size independent of depth, while perspective projection makes farther objects appear smaller under a pinhole model.','虚拟相机定义观察坐标系，视变换把世界点转到相机坐标。投影映射三维到图像，正交不随深度缩尺寸，针孔透视使远物更小。'],
['In a simple camera convention with positive depth z, image coordinates are x′=f x/z and y′=f y/z. Focal length f controls the scale relative to the image plane. Objects at zero depth make division undefined, and points behind the camera need clipping or separate handling before rasterization.','简化正深度约定下x′=fx/z、y′=fy/z，焦距控制图像平面尺度。z=0除法无定义，镜后点需裁剪或另处理再光栅化。'],
['With f=2, point (3,1,6) projects to (1,1/3). Doubling every coordinate to (6,2,12) gives the same image location because the point lies on the same viewing ray. This ambiguity explains why a single image does not directly reveal an object’s absolute distance without additional scale or scene information.','f=2时(3,1,6)投到(1,1/3)。坐标全倍增(6,2,12)仍同位置，因为同视线。这解释单图无额外尺度场景信息不能直接给绝对距离。'],
['A viewing frustum limits visible space between near and far planes and image boundaries. Depth-buffer precision is not uniform under common perspective mappings, so an unnecessarily tiny near distance can reduce usable precision. Clearly distinguish mathematical camera coordinates, normalized device coordinates, and screen pixels. Mixing conventions often produces mirrored images, inverted depth, or objects disappearing unexpectedly.','视锥限制近平面、远平面和图像边界。常见透视深度映射精度非均匀，过小近距可损精度。区分相机、规范设备、屏幕像素坐标，混约定易镜像、反深度或物体消失。']
], [n('With f=2, x=4, z=8, what is projected x′?','f=2、x=4、z=8，投影x′多少？',1,'Use fx/z.','使用fx/z。','2×4/8=1.','2×4/8=1。'),q('Perspective projection uniquely determines absolute depth from one image point alone.','单个透视图像点唯一确定绝对深度。',false,'All positive points on one viewing ray project together.','同一正向视线点投到同处。','Additional scale or scene constraints are required.','需要额外尺度或场景约束。')]);
add('S20.03','Rasterization and shading','光栅化与着色',[['Coverage','覆盖'],['Barycentric coordinates','重心坐标'],['Depth test','深度测试']], [
['Rasterization determines which image samples are covered by projected primitives such as triangles. Shading computes their appearance from material, lighting, and geometric information. These are different stages: a covered sample still needs a color, and a shaded surface hidden behind another surface should not overwrite the visible front one.','光栅化确定投影三角形覆盖哪些采样，着色按材质光照几何算外观。二者不同：覆盖样本仍需颜色，后面被挡表面不应覆盖前面可见者。'],
['Barycentric coordinates express a point inside a triangle as weighted vertex positions with weights summing to one. They interpolate attributes such as color or texture coordinates. Under perspective, screen-space interpolation needs perspective correction for many attributes. A depth buffer stores the nearest accepted depth per sample under the pipeline’s chosen depth convention.','重心坐标用和为1的顶点权表示三角形内点，并插值颜色纹理。透视下许多属性需透视校正，不能直接屏幕线性插。深度缓冲按约定保存每样本最近已接受深度。'],
['If vertex colors are scalar intensities 0,0.5,1 and barycentric weights are 0.2,0.3,0.5, linear interpolation gives 0.65. For a simple diffuse model, brightness is proportional to max(0,n·l) with normalized normal and light direction. A negative dot product contributes zero direct front-facing diffuse light in this model.','顶点强度0、0.5、1，重心权0.2、0.3、0.5，线性插值0.65。简单漫反射与max(0,n·l)成正比，法向光向需归一；负点积在该模型正面直射贡献为零。'],
['A shading model is an approximation with stated assumptions, not a universal law of every material. Sampling too sparsely causes aliasing; antialiasing estimates pixel-area coverage or filtered radiance rather than merely blurring arbitrary edges. Perform lighting computations in an appropriate linear color space, then apply display encoding. Treating encoded display values as linear light produces incorrect blends.','着色模型有假设，非所有材质普遍定律。稀疏采样混叠，抗锯齿估像素面积覆盖或过滤光，而非随意模糊。光计算应在线性色彩空间，再显示编码；把编码值当线性光会错混合。']
], [n('What is 0×0.2+0.5×0.3+1×0.5?','重心插值0×0.2+0.5×0.3+1×0.5是多少？',0.65,'Sum weighted vertex intensities.','相加权强度。','0+0.15+0.5=0.65.','0+0.15+0.5=0.65。'),q('Rasterization alone specifies a physically correct material response.','仅光栅化就规定物理正确材质响应。',false,'It determines coverage, not the whole light model.','它决定覆盖，不决定完整光模型。','Shading requires additional material and illumination assumptions.','着色另需材质光照假设。')]);
add('S20.04','Curves, surfaces and animation','曲线、曲面与动画',[['Interpolation','插值'],['Bézier curve','贝塞尔曲线'],['Continuity','连续性']], [
['A parametric curve maps a parameter t to a point in space. Interpolation passes through specified values, while approximation may be controlled by points it does not visit. Animation maps time to changing position or other properties. Choosing this mapping determines not only the path but also velocity and acceleration along it.','参数曲线把t映到空间点。插值经过给定值，逼近可由不经过的控制点操控。动画把时间映到位置等属性，映射不仅决定路径，也决定速度加速度。'],
['A quadratic Bézier curve uses B(t)=(1−t)²P0+2(1−t)tP1+t²P2 for t in [0,1]. The weights sum to one and are nonnegative, placing the curve within the control points’ convex hull. De Casteljau construction obtains the same point through repeated linear interpolation and gives a stable geometric interpretation.','二次贝塞尔B(t)=(1−t)²P0+2(1−t)tP1+t²P2，t在[0,1]，权非负且和1，所以曲线在控制凸包内。de Casteljau反复线性插值得同点并有稳定几何解释。'],
['For scalar control points 0,2,4 at t=0.5, weights are 0.25,0.5,0.25 and the value is two. Equal increments of t do not generally yield equal traveled distances on a spatial curve. Constant-speed motion may require arc-length parameterization or an approximation table mapping distance to parameter.','标量控制点0、2、4，t=0.5权为0.25、0.5、0.25，值2。空间曲线上t等增量不一般对应等路程，匀速可能需弧长参数或距离到参数近似表。'],
['Joining segments with equal endpoints gives positional continuity; matching derivatives gives stronger smoothness. Easing changes time progression and can make interfaces feel responsive, but should respect reduced-motion preferences. Numerical animation should use elapsed time rather than assuming every frame has equal duration. Otherwise a dropped frame changes apparent speed or destabilizes a simulation tied to the display loop.','端点相同给位置连续，导数匹配更光滑。缓动改时间进程，可改善界面但需尊重减少动效。数值动画应按实际时间，不假定每帧等长，否则掉帧改变速度或使绑定显示循环模拟失稳。']
], [n('For scalar Bézier controls 0,2,4 at t=0.5, what is B(t)?','控制值0、2、4的二次贝塞尔在t=0.5是多少？',2,'Use weights 1/4,1/2,1/4.','使用权1/4、1/2、1/4。','0+1+1=2.','0+1+1=2。'),q('Equal parameter steps always imply equal arc-length steps.','参数等步长总对应弧长等步长。',false,'Curve speed can vary with the parameter.','曲线参数速度可变。','Constant-distance motion needs an arc-length relationship.','匀距离运动需要弧长关系。')]);
add('S20.05','Ray tracing and numerical issues','光线追踪与数值问题',[['Ray equation','射线方程'],['Intersection','求交'],['Visibility','可见性']], [
['A ray is r(t)=o+td with origin o, direction d, and a permitted parameter range. Ray tracing finds intersections with scene geometry and uses them to evaluate visibility and light transport. The closest valid positive intersection generally determines the first visible surface, not whichever object happens to be tested first.','射线r(t)=o+td含原点、方向和参数范围。追踪求与场景交点以算可见和光传输。最近合法正交点决定首可见面，不是先测到的物体。'],
['For a plane with normal n through point p, solve n·(o+td−p)=0, giving t=n·(p−o)/(n·d) when the denominator is nonzero. Parallel rays require separate handling. Acceleration structures such as bounding-volume hierarchies reject whole groups whose bounds are missed, reducing the number of expensive primitive tests.','平面法向n过p，解n·(o+td−p)=0得t=n·(p−o)/(n·d)，分母非零；平行另处理。包围体层次可拒绝整组不相交边界，减少昂贵图元测试。'],
['From origin (0,0,0) along direction (0,0,1), the plane z=5 is hit at t=5. If direction is instead (0,0,2), the same point has t=2.5. Thus t equals physical distance only when direction length is one. Keep this distinction explicit when applying distance-dependent lighting or clipping.','原点(0,0,0)沿(0,0,1)与z=5交于t=5；方向改(0,0,2)同点t=2.5。所以只有单位方向时t等于物理距离，距离光照与裁剪需区分。'],
['Floating-point error can make a newly spawned ray hit its own surface again or miss a nearly tangent intersection. Robust methods use error bounds, careful origin offsets, and stable root calculations. A universal arbitrary epsilon is not scale-independent. Monte Carlo path tracing estimates integrals of light transport and produces sampling noise; more samples reduce variance but do not fix a biased model.','浮点误差可让新射线再撞自身或漏近切交点。稳健方法用误差界、原点偏移与稳定根计算，固定任意epsilon不适应尺度。路径追踪蒙特卡洛估光积分有噪声，多样本减方差但不修模型偏差。']
], [n('A ray from z=0 has direction z component 2. At what t does it reach z=6?','射线从z=0出发，方向z分量2，何t到z=6？',3,'Solve 2t=6.','解2t=6。','t=3, while traveled distance is six for this direction.','t=3，沿该方向实际距离6。'),q('Ray parameter t always equals physical distance.','射线参数t总等于物理距离。',false,'Direction magnitude affects the parameter scale.','方向长度影响参数尺度。','Distance equals t times direction length for positive t.','正t时距离等于t乘方向长度。')]);
add('S20.06','Scientific visualization and perception','科学可视化与感知',[['Visual encoding','视觉编码'],['Scale','尺度'],['Uncertainty display','不确定性显示']], [
['Scientific visualization maps data to visual attributes such as position, length, color, and shape. The encoding should preserve relationships relevant to the question. Position on a shared axis often supports more precise comparison than area or color intensity. A beautiful image can still mislead if its scale or encoding changes the apparent evidence.','科学可视化把数据映到位置、长度、色与形，应保问题相关关系。共同轴位置常比面积或色强更精确。再美图像也可能因尺度编码而误导证据。'],
['Linear axes preserve additive differences; logarithmic axes emphasize multiplicative ratios and require positive values unless a different transformation is specified. Color maps should fit ordered or categorical data and remain distinguishable under common color-vision differences. Use labels, shape, or patterns alongside color when color alone would exclude readers.','线性轴保加法差，对数轴强调倍数且通常要求正值。色图应匹配有序或类别数据，并考虑色觉差异，必要时加标签、形或纹理，不能只靠颜色。'],
['Values ten and twenty differ by a factor of two. If shown as circle radii ten and twenty, their areas differ by four, exaggerating the ratio. Encoding area proportional to value instead requires radius proportional to the square root of value. This calculation connects geometry directly to honest graphical comparison.','10与20为两倍，若圆半径取10与20，面积四倍而夸大。要面积正比数值，半径应正比平方根；几何计算直接决定诚实图形比较。'],
['Show units, sample size, provenance, and uncertainty where they affect interpretation. Missing observations should not silently become zero. Interactive filtering needs visible active conditions so a subset is not mistaken for the whole population. Distinguish measured data, simulated output, and explanatory illustrations, especially when the same polished visual style could make all three appear equally authoritative.','影响解释时标单位、样本、来源和不确定。缺失不应默默变零；交互过滤显示当前条件，防子集误认为总体。区分测量、模拟与解释图示，漂亮风格不能使证据层级混同。']
], [n('Doubling a circle’s radius multiplies its area by what factor?','圆半径翻倍，面积乘几倍？',4,'Area is proportional to radius squared.','面积正比半径平方。','2²=4.','2²=4。'),q('Missing measurements can always be plotted as zero without changing meaning.','缺失测量总可画成零而不改意义。',false,'Missing and measured zero are distinct states.','缺失与测得零不同。','Replacing one with the other invents data and can distort patterns.','替换会捏造数据并扭曲规律。')]);

add('S21.01','Human perception and interaction models','人类感知与交互模型',[['Attention','注意'],['Recognition','识别'],['Feedback','反馈']], [
['Interfaces compete for limited attention and working memory. Grouping, alignment, contrast, and consistent location help users find relevant information without repeatedly interpreting the whole screen. Recognition, choosing among visible meaningful options, usually demands less recall than remembering an invisible command or an unexplained symbol from a previous page.','界面竞争有限注意与工作记忆。分组、对齐、对比、一致位置帮助找到信息。识别可见有意义选项通常比回忆隐藏命令或之前未解释符号负担小。'],
['An interaction loop includes a user goal, an action, system response, and interpretation of that response. Clear feedback makes state changes visible. Affordances suggest possible actions, while labels explain their purpose. A visual object that looks clickable but does nothing creates a mismatch between the interface’s signifiers and its actual behavior.','交互循环含目标、动作、响应和解释。反馈使状态变化可见，操作暗示可能动作，标签解释用途。看似可点击却无反应会使视觉提示与真实行为不符。'],
['A learning map showing hundreds of equal-weight nodes forces users to search without a hierarchy. Starting with subject areas, then a chosen course route, then one concept’s immediate prerequisites reduces simultaneous demands. A persistent location label explains where the user is, while a visible back action makes exploration recoverable. This is progressive disclosure with preserved context.','学习地图数百等权节点使搜索无层次。先领域，再选课路线，再概念直接前提，可减少同时负担。持续位置标签说明所在，返回动作使探索可恢复，这就是保上下文的渐进展示。'],
['Models such as target-acquisition time and choice complexity describe tendencies under particular experimental conditions, not universal laws predicting every person’s behavior. Validate designs with representative tasks. Animation should explain continuity or state changes and remain interruptible; motion that competes with reading can harm comprehension even when it appears visually impressive.','目标获取时间和选择复杂度模型描述特定条件趋势，不是预言每人的普遍定律。需代表任务验证。动画应解释连续或状态且可打断；与阅读争注意的运动再漂亮也可损理解。']
], [n('A view exposes 120 nodes, then filters to 12 relevant nodes. How many nodes were removed from immediate attention?','视图120节点过滤成12相关节点，减少几项即时注意对象？',108,'Subtract the focused count.','总数减聚焦数。','120−12=108, while navigation must preserve access to the rest.','120−12=108，同时导航仍应能访问其余。'),q('Animation always improves comprehension regardless of reading context.','无论阅读情境，动画总改善理解。',false,'Motion can compete for attention.','运动会竞争注意。','Use it to explain transitions and respect reduced-motion preferences.','应解释转场并尊重减少动效设置。')]);
add('S21.02','User research and task analysis','用户研究与任务分析',[['Task goal','任务目标'],['Observation','观察'],['Evidence synthesis','证据综合']], [
['User research investigates what people are trying to accomplish, the conditions they face, and where current tools fail. A task describes a meaningful goal, such as locating the prerequisite for a physics lesson, rather than a prescribed click sequence. Distinguishing goals from current interface steps leaves room for a better design.','用户研究看人想完成什么、处于何条件、现工具哪里失败。任务描述找物理课前提等目标，不是固定点击序列；目标与现步骤分离才能改设计。'],
['Interviews reveal reported experiences and motivations; observation reveals actual behavior and workarounds. Each has limitations: memory can be inaccurate, and an observed setting may influence behavior. Ask neutral questions and avoid teaching participants the intended answer. Record specific evidence separately from interpretations so later design decisions can be traced back to what was actually seen.','访谈反映陈述经历动机，观察反映行为和绕法；回忆会错，观察环境也会影响。提问中性，不教预期答案。将证据与解释分开，便于追踪设计依据。'],
['A learner says a map is confusing. Observing them may show that they cannot distinguish prerequisites from optional related topics. The design problem is then edge semantics and hierarchy, not simply insufficient color. A revised task asks them to identify what must be learned before derivatives and explain why each visible connection is present.','学习者说地图混乱，观察发现无法区分必要前提和可选相关主题，问题就是边语义层次，不只是颜色不足。改任务让其找导数前必须学什么，并解释各连接为何出现。'],
['Recruit participants relevant to the product’s intended range, including beginners and people using assistive technology when applicable. A few vivid comments do not establish population percentages. Synthesize repeated obstacles, contradictory needs, and unresolved questions, then prioritize changes by impact and evidence. Keep research records limited to necessary information and obtain appropriate consent before recording or sharing personal observations.','参与者应覆盖目标范围，适当包括初学和辅助技术使用者。几条生动评论不能代表总体比例。综合反复障碍、冲突需要与未知，按影响证据排序；记录最少必要信息，录制分享须合适同意。']
], [n('Eight participants attempt a task and six complete it under the same conditions. What is the observed completion fraction?','八人同条件尝试六人完成，观察完成比例是多少？',0.75,'Divide completions by attempts.','完成数除尝试数。','6/8=0.75, with uncertainty from the small sample.','6/8=0.75，小样本仍有不确定。'),q('A task should always dictate the exact buttons the participant must press.','任务总应指定参与者必须按哪些按钮。',false,'That can conceal navigation difficulty.','这样可能隐藏导航困难。','Specify the goal and observe whether the interface makes the path discoverable.','应给目标，观察路径能否被发现。')]);
add('S21.03','Information architecture and prototyping','信息架构与原型',[['Hierarchy','层次'],['Navigation model','导航模型'],['Prototype fidelity','原型精度']], [
['Information architecture organizes content so users can locate, understand, and move between it. Categories should reflect meaningful distinctions in the user’s task. A hierarchy provides broad-to-specific navigation, while cross-links represent relationships that do not fit a single parent. The design must explain which structure is primary rather than presenting every possible connection at equal visual weight.','信息架构帮助定位理解移动内容，分类应符合任务。层次提供由广到细导航，交叉链接表达非单父关系；设计须说明主结构，不能所有连接同权展示。'],
['A prototype tests an interaction hypothesis before all production behavior exists. Low-fidelity sketches reveal layout and terminology problems cheaply; higher-fidelity prototypes test motion, density, and interaction details. Label simulated data and inactive controls clearly. Fidelity in appearance does not imply fidelity in persistence, accessibility, performance, or real backend behavior.','原型在完整实现前检验交互假设。低精度草图廉价查布局术语，高精度测动效密度细节。标明模拟数据和无效控件，外观高精不代表存储、无障碍、性能或后端真实。'],
['For a curriculum, use subject→course→module as the browsing spine. At a module, show immediate prerequisites and a recommended next lesson. Offer a separate route view for longer dependencies instead of overlaying all edges on the course list. A text outline gives another way to inspect the same structure without spatial navigation.','课程可用学科→课程→模块为主导航。模块显示直接前提与推荐下一课，长依赖另开路线视图，不把所有边叠课程列表。文本大纲让无需空间导航也可检查同结构。'],
['Test whether users can predict where an item belongs and return from a detour without losing their place. Search complements navigation but should not compensate for unexplained categories. Preserve selected filters and scroll positions when they support continuity. When a prototype is approved, translate its behavior into explicit implementation and acceptance criteria rather than assuming screenshots specify every interaction.','测试能否预测条目归属、绕路后不迷失返回。搜索补充导航，不应掩盖不明分类。按需要保留筛选和位置。原型批准后仍需明确实现验收，截图不能规定所有交互。']
], [n('A route has three levels: subject, course, module. How many transitions connect the first level to the third?','学科、课程、模块三层，从首到末需几次层间转移？',2,'Move subject→course, then course→module.','学科到课程再到模块。','Two transitions establish the hierarchy path.','两次转移。'),q('A visually polished prototype proves data persistence works.','外观精美原型证明数据持久保存正常。',false,'Appearance and storage behavior are separate.','外观与存储行为独立。','Persistence needs a real save-and-reopen verification.','持久性需真实保存重开验证。')]);
add('S21.04','Accessibility and inclusive design','无障碍与包容设计',[['Keyboard access','键盘访问'],['Semantic structure','语义结构'],['Equivalent alternatives','等效替代']], [
['Accessibility enables people with varied abilities, devices, and contexts to use a product. It includes perceiving information, operating controls, understanding behavior, and compatibility with assistive technologies. A design that works for a mouse user at one screen size may fail for keyboard navigation, magnification, a screen reader, or reduced-motion settings.','无障碍支持不同能力设备情境，涵盖感知、操作、理解和辅助技术兼容。单屏鼠标可用不代表键盘、放大、读屏或减少动效可用。'],
['Use semantic controls, programmatic labels, logical focus order, and visible focus indicators. Every essential action should be reachable without pointer precision. Do not convey correctness or status by color alone; pair color with text or shape. Dynamic updates need appropriate announcements without repeatedly interrupting the user’s reading or typing.','使用语义控件、程序标签、逻辑焦点序与可见焦点，关键操作不依赖精确指针。正确状态不能只靠颜色，要配文字形状。动态更新适当通知，不反复打断阅读输入。'],
['A draggable prerequisite graph needs a keyboard and text alternative. A list can state “fractions is required before ratios” and provide ordinary links to both lessons. The same learning relationship is then available without interpreting line position or performing a drag. A slider should expose its value and support arrow-key changes as well as pointer movement.','可拖前提图需要键盘文本替代，列表可写“比例前需要分数”并链接两课，无需看线位置或拖动也能得关系。滑杆应暴露值并支持方向键。'],
['Test at increased text sizes, narrow layouts, high contrast, and reduced motion, and include actual assistive-technology checks where possible. Automated audits find only some barriers. Avoid claiming full compliance from a clean scanner report. Accessible design preserves equivalent information and control, even when the interaction format differs from the default visual presentation.','测试大字、窄布局、高对比、减动效，并尽可能真实辅助技术验证。自动审计只能找部分障碍，不能凭零告警声称完全合规。等效信息控制可用不同交互格式提供。']
], [n('A critical action supports mouse and keyboard. How many of those two input methods can operate it?','关键动作支持鼠标键盘，两方式中几种能操作？',2,'Both are supported independently.','两者独立支持。','Two methods preserve access across input preferences.','两种方式支持不同输入偏好。'),q('Passing an automated accessibility scan proves every user can complete every task.','通过自动无障碍扫描证明所有用户可完成所有任务。',false,'Many barriers require contextual and human testing.','许多障碍需情境和人工测试。','Use automated checks as one evidence layer, not a universal guarantee.','自动检查只是证据一层，不是普遍保证。')]);
add('S21.05','Usability evaluation','可用性评估',[['Task success','任务成功'],['Error observation','错误观察'],['Study validity','研究有效性']], [
['Usability evaluation asks whether intended users can accomplish representative tasks effectively, efficiently, and with acceptable experience. Define success criteria before observing the session. Completion time matters only alongside success and context: finishing quickly by misunderstanding the task is not equivalent to performing it correctly with minimal effort.','可用性看目标用户能否有效高效且体验可接受地完成代表任务，观察前定义成功。时间需结合成功与情境，误解任务后快速结束不等于正确省力。'],
['Observe where participants hesitate, backtrack, make errors, or request help. Think-aloud comments can reveal reasoning but may change timing, so choose methods consistent with the study question. Distinguish moderator assistance from independent completion. A test should not quietly teach the interface and then count the resulting success as effortless discoverability.','观察犹豫、回退、错误和求助。出声思考可揭推理却影响时间，方法应符合问题。区分协助与独立完成，不能先悄教界面再把成功记为自然发现。'],
['If ten users attempt to find a lesson prerequisite, seven succeed independently, two succeed after a hint, and one fails, independent completion is seventy percent. Reporting ninety percent without noting assistance hides a discoverability problem. The two assisted paths still provide useful evidence about which clue or label might make the next design clearer.','十人找前提，七独立成功、两提示后成功、一失败，独立完成70%。不说明帮助而报90%隐藏可发现问题；受助过程仍能提示哪些线索标签可改善。'],
['Small formative studies identify concrete obstacles; they do not justify precise population estimates without an appropriate sampling design. Compare revisions using equivalent tasks and account for learning effects if the same people repeat them. Prioritize issues by severity and impact on core goals, then retest the changed interaction. A preference vote alone is not evidence that one design supports better task performance.','小形成性研究可找障碍，但无适当抽样不能精确估总体。修订对比用等价任务，同人重复要考虑学习效应。按核心目标严重度排序并重测，偏好投票不独自证明任务表现更好。']
], [n('Seven independent completions among ten attempts give what fraction?','十次尝试七次独立完成，比例多少？',0.7,'Exclude assisted completions from this metric.','此指标不计受助完成。','7/10=0.7.','7/10=0.7。'),q('A hint-assisted completion should be labeled identically to an independent completion.','受提示完成应与独立完成完全同标。',false,'Assistance changes the evidence.','帮助改变证据。','Report both categories so discoverability remains visible.','应分别报告，使可发现性问题可见。')]);
add('S21.06','Iterative design with evidence','以证据迭代设计',[['Hypothesis','假设'],['Controlled revision','受控修订'],['Decision record','决策记录']], [
['Iteration is a cycle of identifying a problem, proposing a change, observing its effect, and revising the explanation. A useful design hypothesis names a user obstacle and a mechanism by which the change should reduce it. “Make the screen prettier” is less testable than “group prerequisite cards so users can distinguish required and optional links.”','迭代循环为发现问题、提出变化、观察效果、修正解释。假设应命名障碍及变化如何减障。“更漂亮”不如“分组前提卡帮助区分必需与可选”可检验。'],
['Change enough to address the mechanism while preserving a comparison. If typography, navigation, labels, and content all change together, improvement may be real but its cause is harder to identify. Combine quantitative outcomes with qualitative observations: a completion rate indicates what happened, while observed confusion can explain why it happened.','改到足以影响机制但保留对照。字体导航标签内容全改，可能改善却难辨原因。定量说明发生什么，定性困惑可解释为何，两者结合。'],
['Suppose the original route view shows thirty nodes and users miss the next action. A revision shows six immediate prerequisites, one current lesson, and one next step, with expansion available. Test whether learners can identify their next useful lesson and still inspect distant dependencies when needed. Reducing visible count alone is not success if essential information becomes unreachable.','原路线30节点，用户漏下一动作；改为六直接前提、一当前、一下一步，并可展开。测试能否找下一课且仍能查远依赖。只减少可见数不算成功，若信息不可达仍失败。'],
['Keep a decision record describing the evidence, chosen trade-off, and unresolved questions. Retest regressions such as keyboard focus, language switching, and saved state after visual changes. Stop polishing details that do not improve the core task while major obstacles remain. A design is supported by accumulated evidence under stated conditions, not by an irreversible declaration that iteration is finished forever.','记录证据、权衡与未知。视觉改后重测键盘、语言切换、保存状态等回归。重大障碍仍在时，不应只打磨无助核心的细节。设计由条件下累积证据支持，不是永远终结迭代的声明。']
], [n('A focused view shows six prerequisites, one current lesson, and one next step. How many cards are visible?','聚焦视图六前提、一当前、一下一步，共几卡？',8,'Add the three groups.','相加三组。','6+1+1=8.','6+1+1=8。'),q('Fewer visible items is always better even when required information becomes inaccessible.','即使必要信息无法访问，可见项越少也总越好。',false,'Progressive disclosure must preserve access and context.','渐进披露须保访问与上下文。','A simpler surface that blocks the task is not a successful revision.','阻碍任务的简化表面不是成功修订。')]);

add('S22.01','Parallel models and decomposition','并行模型与任务分解',[['Work and span','工作量与跨度'],['Data parallelism','数据并行'],['Task parallelism','任务并行']], [
['Parallel computing performs independent work concurrently. Data parallelism applies similar operations to different data pieces; task parallelism runs different operations that can overlap. Decomposition must identify dependencies explicitly, because two operations that update the same state may not be independent even if they appear in different functions.','并行同时执行独立工作。数据并行对不同数据作类似操作，任务并行重叠不同操作。分解需明确依赖，改同一状态的操作即使在不同函数也未必独立。'],
['Work is the total number of operations; span is the longest dependency-chain length. With p ideal processors, running time is at least max(work/p,span). This lower bound distinguishes insufficient hardware from inherent sequential dependence. Scheduling and communication add overhead, so actual time may be larger even when enough independent tasks exist.','工作量是总操作数，跨度是最长依赖链。p理想处理器时间至少max(work/p,span)，区分硬件不足与固有顺序；调度通信还添开销，真实可更大。'],
['Summing eight values sequentially takes seven additions along one chain. A balanced reduction tree still performs seven additions but has three addition levels: four pair sums, two sums of pairs, and one final sum. Parallelism reduces span without reducing total arithmetic work, illustrating why these two measures should not be confused.','八值求和顺序七次加法同一链，平衡归约仍七次，但三层为4、2、1。并行减跨度不减总算术，说明两指标不能混同。'],
['Choose chunks large enough to amortize scheduling costs but small enough to balance load. Irregular tasks may need work stealing or dynamic scheduling. Shared data movement can dominate arithmetic, especially across machines. Verify that parallel regrouping preserves intended numerical semantics: floating-point addition is not exactly associative, so a parallel reduction may differ slightly from a sequential one.','块要足够大分摊调度，又足够小平衡负载；不规则任务可偷取或动态调度。跨机时数据移动可主导算术。浮点加法不精确结合，重组归约可能与顺序略异，需验证语义。']
], [n('How many levels does a balanced pairwise sum of 16 values require?','16值平衡两两求和需几层？',4,'Halve the number of active values each level.','每层活动值减半。','16→8→4→2→1 gives four levels.','16→8→4→2→1，共四层。'),q('Parallelization always reduces the total number of arithmetic operations.','并行化总减少算术总次数。',false,'It can reduce span while preserving or increasing work.','可减跨度却保持或增加工作。','The sum tree uses the same additions as the sequential sum.','求和树与顺序求和加法数相同。')]);
add('S22.02','Synchronization and memory models','同步与内存模型',[['Happens-before','先行发生'],['Atomic operation','原子操作'],['Memory ordering','内存序']], [
['A memory model specifies which observations are permitted when threads access shared memory. Source-code order in one thread is not automatically a global observation order across all threads. Compilers and processors may reorder operations within the rules of the language and hardware, making explicit synchronization essential for communication.','内存模型规定并发共享访问允许哪些观察。线程源码顺序不自动成为全局观察序，编译器处理器可在规则内重排，因此通信需显式同步。'],
['An atomic operation avoids indivisible-access races on its own object, while memory-order rules control relationships to other operations. A release operation paired with an appropriate acquire observation can establish a happens-before relation. A mutex also provides ordering guarantees around protected operations. Ordinary volatile access is not a general replacement for thread synchronization in C++.','原子操作保证自身对象不可分访问，内存序控制其他操作关系。适当释放与获取观察可建立先行发生；互斥锁也提供保护区顺序。C++普通volatile不是通用线程同步替代。'],
['One thread writes a data object and then publishes a ready flag. Another sees ready and reads data. Correct publication requires synchronization that orders the data write before the read, not merely a flag variable that often appears to work on one processor. Otherwise the language may permit a race or stale observation despite favorable test results.','一线程写数据再发布ready，另一见ready后读数据。正确发布需同步排序写在读前，不是某处理器常看似可用的标志。否则即使测试顺利，语言仍可能允许竞争或旧观察。'],
['Locks protect invariants spanning several values; independent atomic fields do not automatically make a compound operation atomic. Review lock ordering and avoid waiting while holding resources needed by the producer. Concurrency tests can expose failures but cannot enumerate every interleaving. Reason using the stated memory model and then stress-test the implementation under diverse scheduling conditions.','锁保护跨多值不变量，各字段独立原子不使复合操作原子。检查锁序，避免等待时持有生产者需资源。测试无法穷尽交错，应先按内存模型推理，再多调度压力测。']
], [n('A compound update changes two fields that must be consistent together. How many fields belong to that invariant?','复合更新两个必须一起一致的字段，不变量涉及几字段？',2,'The consistency rule spans both values.','规则跨两值。','Both fields must be coordinated as one logical state.','两字段需作为同一逻辑状态协调。'),q('Making every field atomic automatically makes any multi-field transaction atomic.','各字段原子自动使任意多字段事务原子。',false,'Observers can still see intermediate combinations.','观察者仍可看见中间组合。','A broader synchronization protocol is needed for the compound invariant.','复合不变量需要更广同步协议。')]);
add('S22.03','Distributed communication and failure','分布式通信与故障',[['Partial failure','部分故障'],['Timeout','超时'],['Idempotent retry','幂等重试']], [
['A distributed system contains components communicating across boundaries where messages may be delayed, lost, duplicated, or reordered according to the model. Components can fail independently, leaving part of the system running. This partial-failure behavior differs from a single sequential program where one local call usually returns within the same execution context.','分布式组件跨边界通信，模型可允许消息延迟、丢失、重复、乱序，组件独立失败，系统部分仍活。此部分故障不同于同执行上下文普通本地调用。'],
['A timeout means a response was not observed before a deadline; it does not distinguish a crashed peer from a slow peer or delayed network. Retries can improve availability but may duplicate effects. Give operations stable identifiers and define how receivers recognize repeated requests, especially when processing completed but the acknowledgment was lost.','超时只代表截止前未见响应，不能区分崩溃、缓慢或网络延迟。重试提升可用却可能重复效果；应给稳定操作号并定义重复识别，尤其处理已完成但确认丢失。'],
['A client requests increment once. The server increments from ten to eleven, but the reply disappears. A blind retry increments again to twelve. With a durable request identifier and recorded result, the retry can return the original result eleven without repeating the effect. Deduplication state needs its own retention and failure rules.','客户端请求加一，服务端10变11但回复丢。盲重试变12；若有持久请求号与结果，重试返回原11而不重复。去重状态也需保留与故障规则。'],
['Define crash-stop, crash-recovery, or Byzantine assumptions explicitly; algorithms valid for one are not automatically valid for another. End-to-end exactly-once effects require coordination with the actual side effect, not merely a reliable message queue label. Observe and report uncertain outcomes honestly when the available evidence cannot determine whether an operation committed.','明确停止崩溃、恢复崩溃或拜占庭假设，算法不自动跨模型适用。端到端恰一次效果需协调真实副作用，不只是队列标称可靠。证据无法确定是否提交时应诚实报告不确定。']
], [n('A counter starts at 10 and an unprotected retried increment executes twice. What is its value?','计数10，无去重重试使加一执行两次，值多少？',12,'Both executions change the state.','两次都改变状态。','10+1+1=12.','10+1+1=12。'),q('A timeout proves the remote process has crashed.','超时证明远程进程崩溃。',false,'Slow execution or communication can look the same.','缓慢执行通信可表现相同。','A deadline detects missing timely response, not the unique cause.','期限只能发现未及时响应，不能唯一确定原因。')]);
add('S22.04','Replication and consistency','复制与一致性',[['Replica','副本'],['Linearizability','线性一致性'],['Eventual convergence','最终收敛']], [
['Replication keeps copies of data on multiple nodes for availability, locality, or durability goals. A consistency model specifies which histories clients may observe. Linearizability makes each operation appear to take effect at one instant between invocation and response, preserving real-time ordering. Weaker models may permit stale reads or differently ordered observations.','复制为可用、本地性或持久保多份数据。一致性模型规定可观察历史。线性一致使操作看似在调用返回之间某瞬时生效，并保实时顺序；弱模型可旧读或不同序观察。'],
['A leader-based design sends writes through one coordinator and replicates them to followers. Synchronous acknowledgment waits for a stated replication condition; asynchronous replication can acknowledge earlier but risks followers lagging. Eventual consistency promises convergence under its conditions when updates stop and communication succeeds, not that every read always returns the newest value.','主节点设计经协调者写并复制从节点。同步确认等规定复制条件，异步可早确认但从节点滞后。最终一致是在停止更新且通信成功等条件下收敛，不是每次都最新。'],
['If a client writes score 12 to the leader and immediately reads a lagging follower still storing 10, it sees an older value. Read-your-writes consistency specifically protects that client’s subsequent observations. Different guarantees solve different user expectations; calling a database consistent without naming the model leaves essential behavior ambiguous.','客户端主节点写12后立刻读仍存10的滞后从节点，会见旧值。读己之写专门保护该客户端后续观察。不同保证解决不同期待，不说模型只称一致会模糊关键行为。'],
['Quorum reads and writes rely on overlap plus version and conflict rules. The arithmetic R+W>N alone is not a complete proof of linearizability for every failure and concurrency model. Concurrent writes may need ordering or merge semantics. Replicas sharing a software bug or deletion stream are not independent historical backups, so replication and recovery must be designed together.','读写法定数依靠重叠及版本冲突规则，单R+W>N不证明任意故障并发下线性一致。并发写需排序或合并语义。同软件错或删除流副本不是独立历史备份，应联合设计恢复。']
], [n('For N=5, R=3 and W=3, what is R+W−N, the minimum overlap count?','N=5、R=3、W=3时，最少重叠R+W−N是多少？',1,'Use inclusion-exclusion for two subsets.','用两个集合容斥。','3+3−5=1 shared node at minimum.','3+3−5=1，至少共一节点。'),q('Eventual consistency guarantees every immediate read sees the newest write.','最终一致保证每个立即读取都见最新写。',false,'Convergence is a different guarantee.','收敛是不同保证。','A replica may temporarily lag before convergence conditions are met.','收敛条件满足前副本可暂滞后。')]);
add('S22.05','Consensus and coordination','共识与协调',[['Agreement','一致决定'],['Majority quorum','多数法定数'],['Safety and liveness','安全性与活性']], [
['Consensus requires participating nodes to agree on a value under a stated failure model. Safety prevents conflicting decisions; liveness requires eventual progress under specified timing and availability conditions. These properties must be stated separately because a system that never decides anything can avoid disagreement while being practically useless.','共识让节点在故障模型下决定同值。安全性防冲突决定，活性在时序可用条件下最终进展。永不决定可无冲突却无用，因此两性质要分开。'],
['Majority-based crash-fault protocols use intersecting quorums so decisions cannot be made independently by disjoint majorities. Terms or ballot numbers distinguish leadership attempts and prevent stale leaders from overwriting accepted history. A replicated log additionally orders commands so state machines applying the same sequence can remain in the same state.','多数崩溃容错协议用交叠法定数，避免互不相交多数独立决定。任期或提案号区分领导尝试、防旧领导覆盖已接受历史。复制日志排序命令，使同序状态机保持同态。'],
['With five nodes, a majority requires three. Losing two nodes can still leave a majority, but a partition into groups of two and three allows only the three-node side to make majority-backed progress. Permitting both sides to independently commit conflicting commands would sacrifice the agreement guarantee rather than merely improve availability.','五节点多数需三，失两仍可多数；分成二和三时仅三节点侧能以多数进展。若双方可独立提交冲突命令，就是牺牲一致，不是无代价提升可用。'],
['In a fully asynchronous model with possible crashes, deterministic consensus faces an impossibility result for guaranteed termination under all schedules. Practical protocols add assumptions such as eventual synchrony and use timeouts for progress while preserving safety. Consensus does not automatically make external side effects deterministic or idempotent; those operations need coordination with the committed log and application state.','完全异步且可能崩溃时，确定共识无法保证所有调度下终止。实践增加最终同步等假设，用超时求进展并保安全。共识不自动使外部副作用确定或幂等，还需与提交日志应用状态协调。']
], [n('How many nodes form a majority of seven?','七节点多数至少几节点？',4,'More than half must participate.','要超过一半。','Four is the smallest integer greater than 3.5.','4是最小大于3.5的整数。'),q('Safety and liveness mean exactly the same property.','安全性与活性完全同义。',false,'One forbids bad outcomes; the other requires progress.','一个禁止坏结果，一个要求进展。','A halted system may preserve agreement while failing liveness.','停滞系统可保持一致却不满足活性。')]);
add('S22.06','Performance, reliability and trade-offs','性能、可靠性与权衡',[['Coordination cost','协调成本'],['Tail amplification','尾延迟放大'],['Failure budget','故障预算']], [
['Distributed performance includes computation, communication, serialization, queueing, and coordination. Adding nodes can increase capacity while also increasing communication and failure opportunities. Evaluate a specified workload and consistency requirement; comparing a weakly coordinated system with a strongly coordinated one without acknowledging semantics can make a misleading speed comparison.','分布式性能含计算、通信、序列化、排队、协调。加节点可增容量也增通信故障机会。比较需规定负载一致性，弱协调与强协调不说明语义就比速度会误导。'],
['A request that waits for many parallel subrequests is sensitive to the slowest required response. Tail latency can therefore worsen as fan-out grows. Redundant requests may reduce latency but add load, potentially worsening congestion. Backpressure limits incoming work to sustainable capacity rather than allowing queues to grow without bound.','等待多并行子请求的任务受最慢必需响应影响，分发越多尾延迟可越差。冗余请求或降延迟却加负载拥塞。背压把进入工作限于可持续容量，防队列无界增长。'],
['If a service handles 100 requests per second but receives 120 continuously, an unconstrained queue grows by about twenty requests per second in a simplified steady model. After thirty seconds, roughly six hundred extra requests wait. Faster retries can amplify this overload; bounded retries with delays and admission control address the feedback loop.','简化稳态每秒处理100、持续到120，队列每秒增20，三十秒多600等待。更快重试可放大过载，有限延迟重试和准入控制处理反馈环。'],
['Reliability targets need explicit time windows, success definitions, and dependencies. A service-level objective is a design and measurement target, not a proof that no failure will occur. Test recovery, degraded modes, and partition behavior as well as the normal fast path. Choose trade-offs from user needs and documented failure assumptions rather than treating maximum throughput as the only engineering objective.','可靠目标需时间窗、成功定义和依赖。服务目标是设计测量目标，不证明无故障。既测正常快路径，也测恢复、降级、分区。权衡应依据用户需要与故障假设，不能只最大吞吐。']
], [n('Arrival rate 120 and service rate 100 per second add how many queued requests in 15 seconds?','每秒到120处理100，15秒增加多少排队请求？',300,'Multiply excess arrival rate by time.','超额到达率乘时间。','(120−100)×15=300.','20×15=300。'),q('Immediate unlimited retries always improve an overloaded service.','立即无限重试总能改善过载服务。',false,'Retries create more work on the same bottleneck.','重试在同瓶颈加工作。','They can form a positive feedback loop that worsens overload.','可能形成加剧过载的正反馈。')]);

add('X01.01','Reproducible computational notebooks','可复现计算笔记',[['Executable narrative','可执行叙述'],['Environment','运行环境'],['Deterministic input','确定输入']], [
['A computational notebook combines explanation, code, parameters, and outputs into an inspectable account of an analysis. Reproducibility requires that another clean run can regenerate the reported result from the stated inputs and environment. A screenshot of a plot preserves appearance but does not record enough information to recover the calculation that produced it.','计算笔记结合解释、代码、参数和输出。可复现要求用规定输入环境干净重跑能重建结果。图截图保外观，却不记录足够计算信息。'],
['Separate raw data from derived data and keep units in variable names or metadata. Record software versions, random seeds, and preprocessing choices. Cells should execute in a documented order without hidden state left from earlier experiments. A result depending on a manually changed variable outside the saved workflow cannot be reproduced reliably.','分原始与派生数据，在变量或元数据记单位；记录版本、种子、预处理。单元按已知顺序执行，不依赖旧实验残状态。流程外手改变量导致结果不可可靠复现。'],
['To estimate mean speed from distances [10,20,30] meters and equal durations [2,2,2] seconds, calculate each speed and state whether the target is mean trial speed or total distance divided by total time. Here both give ten meters per second, but unequal durations would generally make them different summaries. The notebook must define the quantity before computing it.','距离[10,20,30]米、各2秒，需说明求各次平均速度还是总距离除总时间。此例均10米每秒，时长不等通常不同。笔记必须先定义量再计算。'],
['Restart the environment and run from beginning before sharing. Validate intermediate dimensions, units, missing values, and expected invariants. Keep generated outputs traceable to a parameter set and input identifier. A notebook is an argument with executable evidence, so explain assumptions and interpret the numerical result instead of presenting many cells whose scientific purpose is unclear.','分享前重启并从头跑，查维度单位缺失与不变量。输出应可追到参数和输入标识。笔记是带可执行证据的论证，需解释假设与结果，不能只堆不明用途单元。']
], [n('Total distance is 45 m and total time 9 s. What is average speed in m/s?','总45米、9秒，平均速率多少米每秒？',5,'Divide total distance by total time.','总路程除总时间。','45/9=5 m/s.','45/9=5米每秒。'),q('Saved outputs alone guarantee a notebook can regenerate them from a clean start.','只保存输出就保证笔记能干净重跑得到它们。',false,'Hidden state or missing inputs may be required.','可能依赖隐藏状态或缺失输入。','A clean full execution tests the reproducible workflow.','干净完整执行才能检验流程复现。')],['physics.units']);
add('X01.02','Numerical-model validation','数值模型验证',[['Model error','模型误差'],['Discretization error','离散误差'],['Convergence study','收敛研究']], [
['A numerical result can differ from reality because the mathematical model is imperfect, parameters are uncertain, discretization approximates continuous equations, or finite arithmetic rounds values. These are distinct error sources. Increasing computational precision addresses only some of them; an exact solution of the wrong model can remain physically misleading.','数值与现实差异可来自模型、参数不确定、离散近似与有限算术舍入，来源不同。增加精度只处理部分，错误模型的精确解仍可误导物理。'],
['Verification asks whether the equations were solved correctly; validation asks whether the model adequately represents the target phenomenon for its intended use. Compare with analytic solutions, conserved quantities, limiting cases, or independent implementations. Agreement between two programs sharing the same mistaken formula is weaker evidence than an independent physical or mathematical check.','验证计算问方程是否算对，模型有效性问是否适合目标现象。可比解析解、守恒、极限、独立实现。两个共用错公式程序一致，弱于独立物理数学检查。'],
['Approximate the derivative of f(x)=x² at x=2 using a forward difference with step h. The result is ((2+h)²−4)/h=4+h, so h=0.1 gives 4.1 and h=0.01 gives 4.01. The exact derivative is four, revealing first-order truncation error and a predictable improvement as h decreases in exact arithmetic.','f(x)=x²在2处前向差分=((2+h)²−4)/h=4+h。h=0.1得4.1，0.01得4.01，精确导数4，显示一阶截断误差及精确算术下缩步改善。'],
['Extremely small h can magnify floating-point cancellation, so smaller steps are not always better indefinitely. Plot error against step size and estimate the convergence order over a regime where one error source dominates. Report the tested regime, tolerances, and independent reference. A smooth-looking curve is not a numerical accuracy certificate.','极小h会放大浮点相消，所以并非越小永远越好。画误差对步长，在单一误差主导区估阶。报告区间、容差、独立参考，平滑曲线不是精度证书。']
], [n('For the stated forward difference with h=0.2, what derivative estimate is obtained?','所述前向差分h=0.2时估计导数多少？',4.2,'Use 4+h.','用4+h。','4+0.2=4.2.','4+0.2=4.2。'),q('A numerically exact solution automatically validates the physical model.','数值精确解自动证明物理模型有效。',false,'The equations may omit relevant phenomena.','方程可能省略相关现象。','Solving the model and validating its applicability are distinct tasks.','解模型与验证适用性是不同任务。')]);
add('X01.03','ODE and physical simulation','常微分方程与物理模拟',[['Initial-value problem','初值问题'],['Time step','时间步'],['Stability','稳定性']], [
['An ordinary differential equation describes how a state changes with one independent variable, often time. An initial-value problem gives y′=f(t,y) and an initial state y(t0). Numerical integration advances approximate states at discrete times. The equation, initial conditions, parameter units, and force assumptions together define the model being simulated.','常微分方程描述状态对一个自变量常为时间的变化。初值问题给y′=f(t,y)和初态，数值积分逐离散时刻推进。方程、初态、参数单位与力假设共同定义模型。'],
['Forward Euler uses y_next=y+h f(t,y), following the present tangent for one time step. For motion, position and velocity are separate state variables, with x′=v and v′=a(t,x,v). Higher-order methods sample slopes more carefully, while adaptive methods adjust h using local error estimates. A local tolerance is not automatically a bound on every global physical error.','前向Euler用y_next=y+h f(t,y)沿当前切线一步。运动含x′=v、v′=a。高阶法更精细采样斜率，自适应按局部误差调h，但局部容差不自动界全部全局物理误差。'],
['For y′=−2y, y(0)=1 and h=0.1, Euler gives y1=0.8 and y2=0.64. Each step multiplies by 1−2h. Numerical decay requires |1−2h|<1, or 0<h<1. At h=1.5, the multiplier is −2, producing growing oscillation although the true exponential solution decays.','y′=−2y、初值1、h=0.1时Euler得0.8、0.64。每步乘1−2h，衰减需绝对值小于1，即0<h<1。h=1.5乘−2会振荡增长，但真解指数衰减。'],
['Check step-size convergence and physically relevant invariants, such as energy behavior in a conservative system. A visually plausible animation can conceal drift. Stiff systems may force explicit methods to use tiny stable steps even when the solution changes slowly. Choose a solver from the equation’s structure and error requirements rather than from display frame rate alone.','查步长收敛与能量等物理性质，像真动画可能藏漂移。刚性系统即使解变化慢，也可迫显式法极小步长。选求解器依方程结构误差要求，不只依显示帧率。']
], [n('For y′=−2y with y=1 and Euler step h=0.2, what is the next value?','y′=−2y、y=1、Euler步h=0.2，下一值多少？',0.6,'Compute 1+h(−2).','计算1+h(−2)。','1−0.4=0.6.','1−0.4=0.6。'),q('A continuous system that decays is guaranteed to decay under any Euler step size.','连续衰减系统在任意Euler步长都保证衰减。',false,'The discrete amplification factor can exceed one in magnitude.','离散放大因子绝对值可超1。','Stability places a separate constraint on the step size.','稳定性另限制步长。')],['physics.motion','math.derivatives']);
add('X01.04','Monte Carlo and uncertainty bridges','蒙特卡洛与不确定性桥梁',[['Random sampling','随机采样'],['Estimator','估计量'],['Sampling error','抽样误差']], [
['Monte Carlo methods estimate quantities through random samples from a specified distribution. An estimator is a function of those samples, such as their mean. Randomness can approximate integrals, probabilities, or uncertainty propagation when exact enumeration is difficult. The sampling distribution must correspond to the target quantity rather than merely be easy to generate.','蒙特卡洛从规定分布抽样估量，估计量是样本函数如均值。可估积分、概率或传播不确定；采样分布须对应目标，不能只图方便生成。'],
['For independent identically distributed samples with finite variance, the sample mean’s standard error decreases proportionally to 1/√N. Reducing this error by a factor of two therefore requires about four times as many samples. Correlation reduces effective information, and biased sampling can converge precisely to the wrong answer even with an enormous sample count.','独立同分布且有限方差时，均值标准误按1/√N下降，减半约需四倍样本。相关减少有效信息，有偏采样即使海量也可精确收敛到错答案。'],
['Estimate the area under f(x)=x² on [0,1] by sampling uniform x and averaging x², since the interval length is one. The exact integral is one-third, providing a reference. The average of squared samples differs from the square of their average; applying the nonlinear function after averaging estimates a different quantity.','均匀采x于[0,1]，平均x²估曲下面积，区间长1，精确积分1/3可作参考。平方的平均不等于平均的平方，先平均再非线性会估另一量。'],
['Save seeds for reproducibility but use independent repetitions to assess variability. A fixed seed reproduces one realization; it does not remove uncertainty. Separate uncertainty in parameters from numerical sampling error. Report the estimator, distribution, sample count, and interval assumptions, and investigate rare events because naive sampling may observe none even when their contribution matters.','保存种子复现，用独立重复评波动。固定种子只重现一次，不消不确定。分开参数与采样误差，报告估计量分布数量区间假设，注意稀有事件，未见不代表贡献无关。']
], [n('To halve Monte Carlo standard error from 1000 independent samples, approximately how many samples are needed?','1000独立样本的标准误要减半，约需多少样本？',4000,'Error scales with inverse square root.','误差按根号倒数缩放。','Four times as many samples gives half the standard error.','四倍样本使标准误减半。'),q('A fixed random seed makes sampling uncertainty disappear.','固定随机种子使抽样不确定消失。',false,'It fixes one realization, not the unknown target.','它固定一次实现，不固定未知目标。','Repeatability and uncertainty are distinct properties.','可重复与不确定性是不同性质。')],['math.integrals']);
add('X01.05','Data-driven biological or chemical models','数据驱动生物与化学模型',[['Mechanistic parameter','机制参数'],['Mass balance','质量平衡'],['Identifiability','可辨识性']], [
['A mechanistic model encodes a proposed process, such as chemical conversion or population growth, while data estimate parameters and test predictions. A fitted curve alone does not establish the mechanism. Different models may describe the same observed range but make different predictions outside it, so interpretation requires both domain knowledge and statistical evidence.','机制模型编码化学转化或种群增长过程，数据估参数测预测。拟合曲线本身不证明机制，不同模型可同样描述观察范围却外推不同，因此需领域与统计证据。'],
['For a closed first-order reaction A→B, d[A]/dt=−k[A] and d[B]/dt=k[A], so [A]+[B] remains constant. The rate constant has units inverse time. Measuring both species checks conservation as well as curve shape. An open system with inflow, outflow, or another reaction needs additional terms rather than forcing the closed model onto it.','封闭一级A→B满足A′=−kA、B′=kA，所以A+B不变，k单位为时间倒数。同时测两者可查守恒。开放流入流出或其他反应需添项，不能硬套封闭模型。'],
['If initial concentrations are A=4 and B=1 millimoles per liter, their total is five. A later measured A=2 implies B=3 under the closed one-to-one model. If B instead measures one, the discrepancy could indicate measurement error, an unmodeled pathway, or violated closure; fitting k cannot repair the missing mass balance.','初A=4、B=1毫摩尔每升，总5。后A=2则封闭一比一模型下B=3。若B测1，可能测误、漏反应或非封闭，调k不能修缺失质量平衡。'],
['Identifiability asks whether distinct parameter values can produce distinguishable observations. Sparse sampling can make parameters poorly determined even when the fitted line looks excellent. Use units, nonnegativity, conservation, residuals, and held-out conditions together. Keep simulated biological or chemical results labeled as model predictions, and do not treat this teaching exercise as experimental confirmation or medical guidance.','可辨识性问不同参数能否产生可区分观察。稀疏样本可使参数不确定，哪怕曲线漂亮。联合用单位、非负、守恒、残差、留出条件。模拟应标模型预测，不作实验证实或医疗指导。']
], [n('A closed A→B system has total concentration 8 and current A=3. What is B?','封闭A→B总浓度8，当前A=3，B多少？',5,'Use conservation of A+B.','使用A+B守恒。','8−3=5 in the same concentration units.','8−3=5，浓度单位相同。'),q('A visually excellent fitted curve uniquely proves its mechanism.','漂亮拟合曲线唯一证明其机制。',false,'Different mechanisms can fit the same observed data.','不同机制可拟合同数据。','Independent predictions and domain constraints are needed to distinguish them.','需独立预测与领域约束区分。')],['chemistry.concentration','biology.energy']);
add('X01.06','Reproducible simulation project','可复现模拟项目',[['Specification','规范'],['Verification suite','验证集'],['Reproduction package','复现包']], [
['A simulation project should begin with a scientific question and a defined output quantity. For a falling object, the question might concern the time to reach a specified height under constant gravity with no drag. State the coordinate direction, initial conditions, units, and approximation domain before choosing a numerical solver or drawing an animation.','模拟项目先有科学问题与输出量。例如无阻力常重力落体到指定高度时间，需先说方向、初态、单位和适用域，再选求解器画动画。'],
['Separate model equations, numerical method, data storage, and visualization. This makes it possible to compare solvers without changing the physical assumptions, or compare models without changing the reporting code. Use deterministic configuration files and save the exact parameter set with each output. Explanatory labels must distinguish idealized assumptions from measured environmental conditions.','分开模型方程、数值方法、存储、可视化，可换求解器不改物理或换模型不改报告。配置确定并每输出保存参数，标签区分理想假设与实测环境。'],
['For a drop from rest under g=10 m/s², height traveled is 5t². Reaching twenty meters takes two seconds in the ideal model. Compare the numerical event time against this analytic result while shrinking the time step. Detect crossing of the height threshold; stopping only at the next coarse time step creates an additional timing error.','静止落体g=10时路程5t²，到20米需2秒。缩步比较数值事件时间与解析值。应检测高度阈值穿越，仅到下一粗步才停会增加时间误差。'],
['The final package should contain the question, equations, assumptions, source, parameters, validation results, and instructions for reproducing outputs offline. Include at least one failing or limiting case to expose the method’s boundary. Report what was verified mathematically, tested numerically, and compared with actual observations separately. A functioning visual demo is a component of the project, not its complete scientific justification.','成包应含问题、方程、假设、源码、参数、验证及离线复现说明，至少一失败或极限例显示边界。分开数学证明、数值测试、实际观察比较。能动演示只是组件，不是完整科学论证。']
], [n('From rest with g=10 m/s², how many meters are traveled in 3 seconds?','静止g=10米每二次方秒，3秒走多少米？',45,'Use gt²/2.','用gt²/2。','10×9/2=45 meters.','10×9/2=45米。'),q('A simulated animation alone confirms that the chosen physical assumptions match reality.','模拟动画本身确认物理假设符合现实。',false,'It displays consequences of the assumptions.','它显示假设的后果。','Validation against appropriate observations is a separate requirement.','还需与适当观察独立验证。')],['physics.motion']);

add('X02.01','Data provenance and cleaning','数据来源与清理',[['Provenance','来源记录'],['Missingness','缺失'],['Validation rule','验证规则']], [
['Data provenance records where data came from, how it was collected, and which transformations produced the current version. A dataset is evidence about a population through a measurement process, not an unexplained table of facts. Preserve raw input and document corrections so the analysis can be inspected or repeated without guessing what changed.','来源记录数据从哪来、如何收集、如何变换。数据是经测量过程得到的总体证据，不是无解释事实表。保留原始并记录修正，使分析可审查重跑。'],
['Cleaning checks types, units, allowed ranges, duplicates, missing values, and relationships between fields. Missing is different from zero, and a duplicate row may be an error or a genuine repeated event. Decide using collection semantics. Automated rules should flag ambiguous cases rather than silently invent values that make the table easier to process.','清理查类型单位范围重复缺失及字段关系。缺失非零，重复可为错误或真实重事件，要按收集语义判断。自动规则应标模糊项，不默默编值方便处理。'],
['Suppose temperatures include 20,21,293.15 with no unit field. The third value may be kelvin corresponding to twenty Celsius, or a genuine high Celsius reading. Dividing or subtracting based only on appearance risks corrupting evidence. Recover the source unit or mark the value unresolved before computing a summary or fitting a model.','温度20、21、293.15却无单位，第三项可能开尔文即20摄氏，也可能真高摄氏。只看外观换算会破坏证据，需查源单位或标未决，再汇总拟合。'],
['Separate deterministic normalization from judgment-based exclusions. Report how many records each rule changes or removes and test whether conclusions depend on plausible alternative handling. Missingness can correlate with the outcome, so deleting all incomplete rows may bias the sample. Cleaning improves usability only when it preserves the intended meaning and transparently records the evidence lost or altered.','分确定规范化与判断排除，报告每规则改删数量，查结论是否依赖合理替代处理。缺失可与结果相关，全删缺行可偏样本。清理需保意义并透明记录损失或变化。']
], [n('A dataset has 120 rows and a documented duplicate rule removes 15. How many remain?','120行按已记录重复规则删除15，剩多少？',105,'Subtract removed records.','总数减删除。','120−15=105 rows remain.','120−15=105行。'),q('A missing measurement can always be replaced by zero without further assumptions.','缺失测量总可无条件替换0。',false,'Zero is an observed numerical value, not absence.','0是数值，缺失是无观察。','Imputation requires a justified model and sensitivity checks.','填补需合理模型与敏感性检查。')]);
add('X02.02','Exploratory visualization','探索性可视化',[['Distribution','分布'],['Relationship','关系'],['Exploration versus confirmation','探索与确认']], [
['Exploratory analysis looks for structure, anomalies, and questions before committing to a final explanatory model. Histograms summarize distributions, scatterplots show paired relationships, and grouped plots compare categories. Choose encodings from the variable types and scientific question, and retain units so apparent patterns can be interpreted in their measurement context.','探索在定最终模型前找结构异常问题。直方看分布，散点看配对关系，分组图比较类别。编码应依变量类型问题，并留单位便解释测量情境。'],
['A histogram depends on bin boundaries and width; a pattern visible under one arbitrary binning may disappear under another. Scatterplots can hide overlapping points, so transparency or counts may be needed. Faceting by relevant groups can reveal patterns that an aggregate view conceals, while too many categories can overwhelm comparison.','直方依分箱边界宽度，一种分箱的规律可能另一种消失。散点重叠可需透明度或计数，按相关组分面可揭总体隐藏模式，但类别过多也妨碍比较。'],
['For values [1,1,2,2,100], the mean is 21.2 while the median is two. A dot plot reveals the extreme value responsible for their difference. Removing it merely to make the average look typical would change the dataset; first investigate whether it is a valid observation, measurement error, or a different population.','[1,1,2,2,100]均值21.2、中位2，点图显示极值造成差异。为平均好看就删会改变数据，先查是真观察、测误还是不同总体。'],
['Exploratory findings are hypotheses, not automatically confirmed discoveries. Trying many plots and highlighting only the striking one can overstate evidence. Keep an exploration log and test important claims with fresh data or an appropriate analysis accounting for selection. Show missingness, sample size, and uncertainty when they materially affect the reader’s interpretation of the visible pattern.','探索发现是假设，不自动确证。试很多图只挑醒目者可夸证据，应记探索并以新数据或考虑选择的分析检验重要说法。影响解释时标缺失、样本量、不确定性。']
], [n('What is the median of [1,2,3,4,50]?','[1,2,3,4,50]中位数多少？',3,'Take the middle ordered value.','取有序中间项。','The third of five values is three.','五项第三为3。'),q('A visually striking pattern found after many exploratory plots is automatically a confirmed causal discovery.','许多探索图后找到醒目规律自动是确证因果发现。',false,'Selection and confounding still matter.','选择与混杂仍重要。','It motivates a hypothesis requiring separate evidence.','它启发需另证的假设。')]);
add('X02.03','Statistical models and diagnostics','统计模型与诊断',[['Residual','残差'],['Assumption','假设'],['Predictive check','预测检查']], [
['A statistical model describes how observed outcomes relate to variables and random variation. It provides a structured approximation rather than a guarantee that the world follows a chosen equation exactly. Parameters summarize features of that model, while diagnostics examine where the model’s assumptions or predictions conflict with the data.','统计模型描述结果如何关联变量和随机变化，是结构近似，不保证世界精确遵方程。参数概括模型特征，诊断检查假设预测与数据冲突。'],
['A residual is observed value minus predicted value. Plot residuals against fitted values, time, and important predictors. Curvature suggests a missing nonlinear relationship; changing spread suggests nonconstant variance; temporal patterns suggest dependence. These clues guide revisions, but each revised model needs renewed evaluation rather than assuming that adding parameters always fixes the underlying issue.','残差为观察减预测，可对拟合值、时间和重要特征画图。弯曲暗示漏非线性，散布变化暗示非恒方差，时间规律暗示依赖。修模型后要重评，不是加参数就总修根因。'],
['If predictions are [2,4,6] and observations [3,4,5], residuals are [1,0,−1]. Their sum is zero, yet errors remain. Mean squared error is (1²+0²+(−1)²)/3=2/3. A zero mean residual does not establish accurate prediction, because positive and negative errors can cancel.','预测[2,4,6]、观察[3,4,5]残差[1,0,−1]，和0但仍有误差。均方误差为(1+0+1)/3=2/3。正负可抵消，因此平均残差0不证明准。'],
['Check influential observations, extrapolation, sample selection, and uncertainty in estimated parameters. Training residuals alone can look excellent under overfitting; held-out predictive checks assess new-data behavior. A confidence interval for a mean and a prediction interval for one new observation answer different questions. State the target of inference and the assumptions needed for its uncertainty calculation.','查影响点、外推、选择、参数不确定。过拟合时训练残差可漂亮，留出预测检验新数据。均值置信区间与单次观察预测区间不同，需说推断目标与不确定计算假设。']
], [n('An observation is 9 and its prediction is 6. What is the residual?','观察9、预测6，残差多少？',3,'Observed minus predicted.','观察减预测。','9−6=3.','9−6=3。'),q('Zero average residual guarantees zero prediction error on every case.','平均残差0保证每例预测误差0。',false,'Positive and negative errors can cancel.','正负误差可抵消。','Use magnitude-based diagnostics as well as the mean.','还需误差幅度诊断。')]);
add('X02.04','Confounding and causal diagrams','混杂与因果图',[['Common cause','共同原因'],['Intervention','干预'],['Collider','碰撞点']], [
['Association means variables vary together in observed data. A causal claim asks what would change under an intervention. A confounder is a common cause influencing both exposure and outcome, creating a noncausal association path. A directed acyclic causal diagram records assumed causal relationships, not relationships automatically proved by correlations.','关联是观察共变，因果问干预后改变。混杂是同时影响暴露和结果的共同原因，形成非因果关联路径。因果DAG记录假定关系，不是相关自动证明的关系。'],
['For C→X and C→Y, comparing Y across X groups can mix the effect of X with differences in C. Under suitable assumptions, adjusting for C can block that backdoor path. However, adjusting for every available variable is not safe: conditioning on a collider X→Z←Y can create an association that was absent beforehand.','C→X且C→Y时，按X比较Y混入C差异；适当假设下调整C阻断后门。但不能所有变量都调整，条件化碰撞点X→Z←Y可引入原不存在关联。'],
['Ice-cream sales and swimming accidents may rise together because warm weather increases both. The diagram weather→sales and weather→swimming exposure→accidents explains association without requiring ice cream to cause accidents. The example does not identify a treatment effect numerically; it shows why a proposed mechanism and measurement of common causes matter.','冰淇淋销量与游泳事故可因暖天气同时增加。天气→销量、天气→游泳暴露→事故，无需冰淇淋致事故即可有关联。例子不数值识别效应，只说明机制与共同原因测量重要。'],
['Causal identification requires assumptions such as adequate adjustment, consistency of treatment definition, and positivity of relevant treatment possibilities. Unmeasured common causes can defeat an adjusted observational comparison. Use the diagram to make assumptions inspectable, then distinguish what data estimate from what the causal assumptions supply. A sophisticated regression cannot repair an unjustified causal graph by itself.','因果识别需足够调整、处理定义一致与相关处理可能性正性等假设。未测共同原因可破坏调整比较。图让假设可查，应分数据估什么、因果假设给什么，复杂回归不能独自修错图。']
], [n('In C→X and C→Y, how many outgoing causal arrows leave C in the diagram?','C→X且C→Y图中，C有几条出因果边？',2,'C is drawn as a common cause of two variables.','C是两变量共同原因。','Two arrows express the two proposed influences.','两边表达两个假定影响。'),q('Adjusting for every measured variable always removes causal bias.','调整所有测得变量总能去因果偏差。',false,'Some variables are colliders or consequences of treatment.','有的变量是碰撞点或处理后果。','Conditioning can create bias or change the estimand.','条件化可引偏或改变目标效应。')]);
add('X02.05','Experiments and observational limitations','实验与观察研究限制',[['Random assignment','随机分配'],['Counterfactual','反事实'],['Selection','选择']], [
['A causal effect compares outcomes under alternative interventions for a defined population. For one unit, only one of those potential outcomes is observed at a time. Random assignment helps create comparable treatment groups in expectation, so differences can estimate an intervention effect under additional design and measurement assumptions. It does not make every finite sample perfectly balanced.','因果效应比较定义总体不同干预结果，同单位同次只能观察一种潜在结果。随机分配在期望上使组可比，配其他设计测量假设可估干预效应，但有限样本不保证完全平衡。'],
['Distinguish random sampling, selecting units from a population, from random assignment, allocating interventions among selected units. The first supports population representation; the second addresses treatment comparability. Blinding can reduce measurement or behavior changes caused by knowing allocation. Attrition and nonadherence can still threaten interpretation even after an excellent randomization procedure.','随机抽样从总体选单位，随机分配给所选单位分干预，前者支持代表，后者支持处理可比。盲法减知分组引起的测量行为变化，失访不依从仍可威胁随机化后的解释。'],
['If an educational exercise randomly assigns twenty learners per group and mean scores are seventy-eight versus seventy-two, the observed difference is six points. Sampling uncertainty, baseline variation, adherence, and the measurement instrument remain relevant. The difference alone does not prove a universal six-point benefit for every learner or a different curriculum.','教育练习每组随机20人，均分78与72，观察差6分。抽样不确定、基线、依从、测量仍相关，不能仅差值就称每人或其他课程普遍提升6分。'],
['Observational studies may be necessary when randomization is infeasible, but then adjustment assumptions deserve particular scrutiny. Predefine outcomes and analysis where possible, report deviations, and distinguish exploratory subgroup findings. Ethical and practical constraints shape study design. In this course, work with fictional or appropriately authorized datasets rather than performing interventions on people without a reviewed and permitted plan.','不能随机时可用观察研究，但调整假设需严审。尽量预定结果分析，报告偏离并区分探索分组。伦理实践约束设计，本课用虚构或适当授权数据，不无审查许可对人干预。']
], [n('Group means are 81 and 74. What is their observed difference?','两组均分81和74，观察差多少？',7,'Subtract the comparison mean.','相减。','81−74=7 points.','81−74=7分。'),q('Random assignment and random sampling serve exactly the same purpose.','随机分配与随机抽样目的完全相同。',false,'One assigns treatment; the other selects the sample.','一个分处理，一个选样本。','Internal comparability and population representation are different goals.','内部可比与总体代表是不同目标。')]);
add('X02.06','Reproducible evidence report','可复现证据报告',[['Claim','主张'],['Analysis lineage','分析链'],['Sensitivity','敏感性']], [
['An evidence report connects a question, data, method, result, and justified conclusion. Lead with the substantive finding while making the measurement and inference boundaries clear. A statistical association should not silently become a causal recommendation. Readers need enough context to judge whether the population, conditions, and outcome match the decision they face.','证据报告连接问题、数据、方法、结果与合理结论。先说实质发现并明确测量推断边界，关联不能悄变因果建议。读者需判断总体条件结果是否对应自身决策。'],
['Preserve analysis lineage from raw records through cleaning, transformations, model fitting, and visualization. Include units, sample counts, missingness, parameter choices, and software versions. A compact report can link to reproducible details instead of burying the conclusion in code, but the linked material must actually regenerate the reported tables and figures.','保留原始到清理、变换、拟合、可视化分析链，含单位数量缺失参数版本。简报告可链接复现细节而不把结论埋代码，但材料必须真能重建表图。'],
['Suppose a mean difference is six points after excluding two invalid records and five points when they are retained under an alternative rule. Reporting both reveals sensitivity to cleaning. It does not automatically invalidate the result, but it limits how precise a claim is supported. Explain why the primary rule was selected independently of which result looked more favorable.','删两无效记录后均差6，另一规则保留时5，同时报告显示清理敏感。并不自动否定结果，但限制精确声明；应说明主规则为何选，不能因结果更好看。'],
['Separate numerical uncertainty, model uncertainty, and limitations of data collection. Give alternative explanations and identify observations that could distinguish them. Bilingual reports should preserve the same claims, units, and qualifications in both languages. End with concrete next checks tied to unresolved questions, not an exaggerated conclusion implying that one dataset settled the entire scientific topic.','分数值、模型、收集限制不确定，给替代解释及区分所需观察。双语保持相同主张单位限定。下一检查应对应未决问题，不夸称一数据集解决整个科学主题。']
], [n('An estimate changes from 6 to 5 under an alternative cleaning rule. What is the absolute change?','替代清理规则使估计6变5，绝对变化多少？',1,'Take the absolute difference.','取差绝对值。','|6−5|=1 point.','|6−5|=1分。'),q('Only the cleaning rule producing the most favorable result should be disclosed.','只应披露结果最有利的清理规则。',false,'Selective reporting hides analytic flexibility.','选择报告隐藏分析自由度。','Report the justified primary rule and relevant sensitivity results.','应报合理主规则和相关敏感性结果。')]);

add('X03.01','Signals and linear systems','信号与线性系统',[['Signal','信号'],['Superposition','叠加'],['Time invariance','时不变性']], [
['A signal is a quantity indexed by time or another independent variable. Continuous-time signals assign values at every time in a domain; discrete-time signals use indexed samples. A system maps an input signal to an output signal. Voltage, displacement, sound pressure, and sampled biological measurements can all be studied using this shared language.','信号是按时间等自变量索引的量，连续时间在域内每时刻取值，离散时间用样本索引。系统把输入信号映到输出，电压、位移、声压、生物采样都可用同语言。'],
['Linearity requires superposition: responding to ax1+bx2 gives a times the response to x1 plus b times the response to x2. Time invariance means delaying an input delays the output by the same amount without otherwise changing it. These are independent properties, so a system can satisfy one while failing the other.','线性要求叠加：输入ax1+bx2的响应等于a倍x1响应加b倍x2响应。时不变是输入延迟只让输出同样延迟，其他不变。两性质独立，可满足一个不满足另一个。'],
['The system y(t)=3x(t) is linear and time-invariant. The system y(t)=x(t)² is time-invariant but nonlinear: input one gives output one, while doubled input gives four rather than two. The system y(t)=t x(t) is linear but time-varying because a delayed input encounters a different multiplying time value.','y=3x线性时不变；y=x²时不变却非线性，输入1输出1，倍增输入输出4非2；y=t x线性却时变，延迟输入遇不同时间乘数。'],
['Causality means present output does not require future input. Memorylessness means output depends only on the current input, a stronger restriction than causality. Stability needs its own definition, such as bounded-input bounded-output behavior. Before using an LTI formula, check linearity, time invariance, initial-state assumptions, and the relevant signal domain rather than assuming every physical device obeys them globally.','因果性指当前输出不需未来输入，无记忆只依当前输入，比因果更强。稳定需另定义，如有界输入有界输出。套LTI公式前查线性时不变初态域，不假定物理器件全局满足。']
], [n('For y=x², what output follows input x=3?','系统y=x²输入3输出多少？',9,'Apply the nonlinear rule.','应用非线性规则。','3²=9.','3²=9。'),q('A time-invariant system must also be linear.','时不变系统必线性。',false,'Time shifting and amplitude superposition test different properties.','时移与幅值叠加检验不同性质。','Squaring is time-invariant but violates superposition.','平方时不变却违反叠加。')],['physics.motion']);
add('X03.02','Convolution and impulse response','卷积与冲激响应',[['Impulse decomposition','冲激分解'],['Convolution sum','卷积和'],['System response','系统响应']], [
['An impulse response describes an LTI system’s response to a unit impulse under the stated initial conditions. Any discrete signal can be written as a sum of shifted impulses weighted by its samples. Linearity scales and adds the corresponding responses, while time invariance shifts them, producing the convolution formula.','冲激响应是给定初态下LTI对单位冲激响应。离散信号可分成按样本加权的移位冲激；线性缩放相加，时不变移位，得到卷积。'],
['For discrete time, y[n]=Σk x[k]h[n−k]. Continuous time replaces the sum with an integral over x(τ)h(t−τ). The reversed shifted argument is essential: it determines which past input contribution arrives at the current output time. A causal impulse response vanishes for negative time, restricting which terms can contribute.','离散y[n]=Σk x[k]h[n−k]，连续换为∫x(τ)h(t−τ)dτ。反向移位参数关键，它决定过去贡献何时到达；因果h在负时为0，限制贡献项。'],
['Let x=[1,2] and h=[1,1], both starting at index zero. Then y[0]=1, y[1]=1×1+2×1=3, and y[2]=2, yielding [1,3,2]. This also describes adding each input sample to the next output sample. Finite lengths two and two produce ordinary convolution length three, not two.','x=[1,2]、h=[1,1]都从0开始，y0=1、y1=1+2=3、y2=2，得[1,3,2]。也就是每输入贡献当前与下一输出；两长2普通卷积长3，不是2。'],
['Convolution’s units include the integration variable in continuous time, so check dimensions when interpreting physical systems. Circular convolution assumes periodic indexing and differs from ordinary linear convolution unless sufficient padding is used. Nonzero initial conditions can add a separate natural response; the convolution with input alone need not describe the complete output of a system already storing energy.','连续卷积单位含积分变量，物理解释需查量纲。循环卷积假周期索引，未充分补零不同于线性卷积。非零初态可增自然响应，单输入卷积未必描述已储能系统全部输出。']
], [n('For x=[2,3] and h=[1,1], what is convolution sample y[1]?','x=[2,3]、h=[1,1]，y[1]多少？',5,'Add both overlapping contributions.','加两重叠贡献。','2×1+3×1=5.','2+3=5。'),q('Convolution of input with impulse response always includes every nonzero initial-state effect automatically.','输入与冲激响应卷积总自动包含所有非零初态影响。',false,'The usual formula assumes the specified zero-state response.','通常公式描述规定零状态响应。','An initial stored state can contribute an additional natural response.','初始储存状态可另贡献自然响应。')]);
add('X03.03','Fourier analysis','傅里叶分析',[['Frequency','频率'],['Orthogonal components','正交分量'],['Sampling','采样']], [
['Fourier analysis represents signals through sinusoidal components. Frequency in hertz counts cycles per second, while angular frequency is ω=2πf radians per second. A periodic signal can be described by a Fourier series of harmonics of its fundamental frequency under appropriate conditions. Nonperiodic signals lead to transform representations rather than one finite list of harmonics.','傅里叶用正弦分量表示信号。赫兹为每秒周期，角频率ω=2πf为弧度每秒。适当条件下周期信号用基频谐波级数，非周期则用变换表示，不是有限谐波清单。'],
['Orthogonality lets integration isolate one sinusoidal coefficient from the others over a full period. The coefficients encode amplitude and phase, not just which frequencies appear. For an LTI system, each complex exponential retains its frequency and is scaled by the frequency response, turning convolution in time into multiplication in the frequency domain.','正交性使全周期积分分离各系数，系数含幅值相位，不只是有哪些频率。LTI对复指数保持频率并按频响缩放，时域卷积转频域乘法。'],
['A signal sin(2π·5t) completes five cycles each second and has period 0.2 seconds. Sampling at twenty samples per second gives four samples per cycle. A perfectly bandlimited signal with highest frequency below half the sampling rate can be reconstructed in the ideal theorem; finite records and real filters introduce additional limitations.','sin(2π·5t)每秒五周期，周期0.2秒。每秒20样本每周期四样本。理想定理下最高频严格低于采样率一半的带限信号可重建，但有限记录真实滤波另有限制。'],
['Aliasing makes different continuous frequencies produce indistinguishable samples when sampling assumptions fail. Anti-alias filtering must precede sampling, because postprocessing cannot generally recover already-confused components. Finite observation windows cause spectral leakage, so a discrete transform peak is not an infinitely precise frequency measurement. Report sample rate, record length, windowing, and amplitude normalization when interpreting spectra.','违采样条件会混叠，使不同连续频率同样本。抗混叠滤波要在采样前，后处理一般不能复原已混淆分量。有限窗有泄漏，DFT峰非无限精确频率，应报采样率时长窗与幅值归一。']
], [n('What is the period in seconds of a 4 Hz sinusoid?','4Hz正弦周期几秒？',0.25,'Period is the reciprocal of frequency.','周期为频率倒数。','1/4=0.25 seconds.','1/4=0.25秒。'),q('Anti-alias filtering can always be postponed until after sampling with no loss.','抗混叠滤波总可无损推迟到采样后。',false,'Aliased components have already become indistinguishable.','混叠后分量已不可区分。','Filtering before sampling limits frequencies that would fold together.','采样前滤波限制会折叠混合的频率。')]);
add('X03.04','Laplace and frequency response','拉普拉斯变换与频率响应',[['Complex frequency','复频率'],['Transfer function','传递函数'],['Pole','极点']], [
['The Laplace transform weights a signal by an exponential involving a complex variable s. It generalizes frequency analysis to include growth and decay. A one-sided transform is useful for initial-value problems, but its derivative rule contains initial-condition terms. Omitting them silently changes the modeled problem from its actual initial state.','拉普拉斯用复变量s指数加权信号，把频率扩展为增长衰减。单边变换适合初值问题，但导数规则含初态项，漏掉就悄悄改初态。'],
['For an LTI differential equation with zero initial conditions, the transfer function H(s) is output transform divided by input transform. Poles occur where its denominator vanishes after valid simplification, and zeros where its numerator vanishes. The region of convergence and causality assumptions matter; a rational formula alone does not specify every possible time-domain signal.','零初态LTI微分方程传递函数H为输出变换除输入。有效化简后分母零为极点，分子零为零点；收敛域与因果假设重要，单有有理式不完全规定时域信号。'],
['For y′+2y=x with y(0)=0, transforming gives (s+2)Y=X, so H(s)=1/(s+2). Its causal impulse response is e^(−2t) for nonnegative time. The pole at −2 corresponds to decay. At zero frequency, H(0)=1/2, giving the steady response to a constant input when stability conditions hold.','y′+2y=x且y(0)=0，得(s+2)Y=X，H=1/(s+2)，因果冲激为非负时e^(−2t)。极点−2对应衰减；稳定时零频增益1/2给常输入稳态。'],
['For stable systems with suitable convergence, evaluate H(jω) to obtain frequency response amplitude and phase. Do not infer complete internal stability solely from a simplified input-output transfer if unstable internal modes were canceled. Track units and initial conditions when translating a physical circuit or mechanical model into algebra; symbolic manipulation is useful only when it preserves those assumptions.','稳定且收敛适当时H(jω)给幅相频响。若化简抵消不稳定内模，不能仅输入输出传函推全内部稳定。物理电路机械代数化需保单位初态，符号操作只有保假设才有效。']
], [n('For H(s)=1/(s+4), what is the zero-frequency gain H(0)?','H(s)=1/(s+4)，H(0)是多少？',0.25,'Substitute s=0.','代s=0。','1/4=0.25.','1/4=0.25。'),q('Transforming a derivative in an initial-value problem never introduces an initial-condition term.','初值问题变换导数永不产生初态项。',false,'The one-sided derivative rule includes the initial value.','单边导数规则含初值。','For example, L{y′}=sY−y(0) under the usual conditions.','通常L{y′}=sY−y(0)。')]);
add('X03.05','Feedback and stability','反馈与稳定性',[['Error signal','误差信号'],['Closed-loop pole','闭环极点'],['Stability margin','稳定裕度']], [
['Feedback measures output and uses its difference from a reference to choose an input. Negative feedback subtracts measured output from the reference before applying a controller. It can improve tracking and disturbance rejection, but delays, phase shifts, and excessive gain can destabilize the closed loop. The sign in a diagram alone does not guarantee stability.','反馈测输出并用与目标之差选输入，负反馈先相减再控制。可改善跟踪抗扰，但延迟、相移、过大增益可失稳，图上负号不保证稳定。'],
['For a plant G and controller C with unity negative feedback, the closed-loop transfer from reference to output is CG/(1+CG), under the linear zero-state assumptions. The characteristic equation 1+CG=0 determines closed-loop poles after accounting for internal dynamics. Continuous-time stable modes decay, requiring poles in the left half-plane for the usual finite-dimensional linear setting.','单位负反馈、线性零态下目标到输出传函CG/(1+CG)，特征1+CG=0决定闭环极点，同时需考虑内部动态。通常有限维连续线性稳定模衰减，极点在左半平面。'],
['For plant y′=−y+u and proportional control u=K(r−y), the closed equation is y′=−(1+K)y+Kr. With K=3 and constant r=1, the pole is −4 and steady output is 3/4. Response becomes faster than the original decay, but a nonzero steady tracking error of one-quarter remains.','y′=−y+u配u=K(r−y)，得y′=−(1+K)y+Kr。K=3、r=1时极点−4，稳态3/4，比原衰减快，但仍有1/4稳态误差。'],
['Stability margins quantify tolerance to gain or phase changes within a specified model. Sensor noise and actuator saturation can invalidate ideal linear predictions. A controller should be evaluated for transients, overshoot, settling, and disturbances, not only final value. Simulation across plausible parameter variations helps expose fragility, but a finite sample of stable simulations is not a universal stability proof.','稳定裕度量化模型内对增益相位变化容忍，噪声饱和可破坏理想线性预测。评控制需看过渡、超调、稳定时间、扰动，不只终值。参数模拟可揭脆弱，但有限稳定样本非普遍证明。']
], [n('For the worked plant with K=1 and r=1, what is steady output K/(1+K)?','例题系统K=1、r=1，稳态K/(1+K)多少？',0.5,'Substitute K=1.','代K=1。','1/(1+1)=0.5.','1/2=0.5。'),q('Negative feedback can never destabilize a system.','负反馈永远不能使系统失稳。',false,'Delay and phase shift can reverse its effective effect.','延迟相移可改变有效作用。','Stability depends on the complete loop dynamics and gain.','稳定取决于完整环动态与增益。')]);
add('X03.06','Control design and simulation','控制设计与模拟',[['PID terms','PID各项'],['Saturation','饱和'],['Validation scenario','验证场景']], [
['A controller design begins with explicit goals such as tracking accuracy, settling time, overshoot, actuator limits, and disturbance rejection. A proportional term reacts to current error, an integral term accumulates error, and a derivative term responds to its rate of change. These terms have different units and effects; combining arbitrary numerical gains without dimensional interpretation is misleading.','控制设计先定精度、稳定时间、超调、执行器限额和抗扰。比例看当前误差，积分累积，微分看变化率，各项单位作用不同，不能不看量纲随意拼增益。'],
['Integral action can remove constant steady error under suitable stable conditions, but actuator saturation can let the integral accumulate excessively, called windup. Anti-windup designs account for the difference between requested and actual input. Derivative action can amplify measurement noise, so practical implementations often use filtered measurements and carefully defined sampling behavior.','适当稳定条件下积分消常值稳态误差，但执行器饱和时可积分过积。抗饱和设计考虑请求与实际输入差。微分可放大噪声，实践常滤测量并明确采样。'],
['Suppose a heater controller requests input ten but the actuator can supply at most four. The physical model must use four, not ten, or the simulated temperature response overstates control authority. If accumulated error keeps growing during saturation, recovery may overshoot after the target is reached. This is a model-interface issue as much as a gain-selection issue.','加热控制请求10但执行器最多4，物理模型必须用4，否则高估控制能力。饱和时误差继续累积，到目标后可能超调，既是增益问题，也是模型接口问题。'],
['Simulate step changes, disturbances, sensor noise, parameter variation, and startup conditions. Refine numerical time steps to distinguish controller instability from solver instability. Keep software tests for units, limits, and sign conventions, and separate simulated results from hardware validation. A controller verified for an ideal teaching plant should not be treated as a ready design for an unrelated physical device.','模拟阶跃、扰动、噪声、参数和启动。缩数值步区分控制不稳与求解器不稳。单位、限额、符号需软件检查，区分模拟与硬件验证。理想教学对象控制器不能当无关设备现成设计。']
], [n('An actuator saturates at 4 units and receives a request for 10. What actual input should the model apply?','执行器上限4，请求10，模型应施加多少实际输入？',4,'Apply the physical limit.','应用物理上限。','The actuator can provide only four units.','执行器只能提供4。'),q('A smaller numerical time step can help distinguish solver artifacts from controller dynamics.','缩小数值步可帮助区分求解伪影与控制动态。',true,'Check convergence before interpreting a simulated oscillation.','解释模拟振荡前先查收敛。','A disappearing instability under refinement may be numerical rather than physical.','缩步后消失的不稳定可能数值而非物理。')]);

add('X04.01','Question selection and literature reading','问题选择与文献阅读',[['Research question','研究问题'],['Primary evidence','原始证据'],['Claim decomposition','主张分解']], [
['A research question identifies a phenomenon, comparison, or uncertainty that evidence could resolve. Narrow the scope until the variables, conditions, and possible outcomes are clear. “Understand all motion” is too broad for one project; “compare two numerical integrators on pendulum energy drift under stated step sizes” defines a tractable investigation.','研究问题指定证据可解决的现象比较或未知，缩范围直到变量条件结果清晰。“理解全部运动”过广，“比较两积分器在给定步长的摆能量漂移”可操作。'],
['Read primary sources for the original method and evidence, then use reviews to understand context. Separate an author’s observation, model assumption, interpretation, and speculation. Record definitions and conditions because apparently conflicting results may use different populations, parameter ranges, or meanings of the same term. A citation is a route to evidence, not a substitute for assessing it.','原始来源看方法证据，综述看背景。分观察、假设、解释、猜测，记录定义条件，因为冲突可能来自总体、参数或术语不同。引用是通证据路径，不替代评估。'],
['For a pendulum paper, note whether the model uses the small-angle approximation sinθ≈θ. A reported period independent of amplitude may follow from that approximation, while a nonlinear study reports amplitude dependence. The two claims are not contradictory until their model assumptions and measurement ranges are aligned. This reading step prevents designing a project around a false disagreement.','读摆文献时查是否小角sinθ≈θ。周期不依幅值可能来自近似，非线性研究说依幅值；未统一模型量程前不矛盾。这一步防围绕假冲突立项。'],
['Build a short annotated source list recording what each source supports and what remains unclear. Prefer questions with accessible prerequisites, feasible evidence collection, and a meaningful negative result. Avoid promising novelty before checking prior work. A well-reproduced known result with transparent limitations is a legitimate learning project and a stronger foundation than an unsupported claim of discovery.','建注释来源表，写各支持什么、哪些未知。选前提可学、证据可得、否定结果也有意义的问题。查前人前不承诺新颖；透明复现已知结果是正当学习，强于无证发现声明。']
], [n('A project compares two integrators at three step sizes. How many method-step configurations are required?','两积分器、三步长，共几种方法步长配置？',6,'Combine each method with each step size.','每方法配每步长。','2×3=6 configurations.','2×3=6。'),q('Two papers with different modeling assumptions must contradict each other if their numerical conclusions differ.','模型假设不同论文数值结论不同就必矛盾。',false,'Claims are conditional on their assumptions.','主张依赖条件。','Align domains and assumptions before comparing the results.','先统一域和假设再比较。')]);
add('X04.02','Prerequisite bridge plan','先修知识桥接计划',[['Dependency','依赖'],['Diagnostic evidence','诊断证据'],['Minimal bridge','最小桥接']], [
['A bridge plan identifies the concepts needed for a specific project and the current evidence that the learner understands them. Dependencies are concept-level relationships, not a requirement to finish every course bearing a related subject name. The goal is a sufficient foundation for the task while keeping important gaps visible.','桥接计划确定项目所需概念及当前理解证据。依赖是概念关系，不要求把相关学科整课全修。目标是足够基础，同时显露重要缺口。'],
['Start from the target operation and work backward. Simulating a spring requires force balance, position and velocity states, derivatives, units, and numerical stepping. Each concept may depend on earlier ideas such as signed numbers or functions. Mark prerequisites as demonstrated, uncertain, or not yet learned rather than treating one correct recognition question as complete mastery.','从目标操作逆推。弹簧模拟需力平衡、位置速度状态、导数、单位、数值步，各又依有符号数函数等。标已展示、不确定、未学，不能一道识别题对就当掌握。'],
['A learner comfortable with algebra but new to derivatives can first interpret velocity as position change per time, then study the derivative limit, then connect x′=v to an update rule. This route uses both physics intuition and calculus precision. Skipping the limit entirely may produce executable code without understanding what approximation the time step represents.','代数熟而导数新者可先速度是位置每时间变化，再学导数极限，再连x′=v与更新。路线结合物理直觉和微积分精确；跳极限可能写出代码却不懂时间步近似什么。'],
['For every bridge, choose a small explanation task and a fresh application. Reassess only the uncertain dependency rather than restarting an entire subject. Preserve alternate routes when a concept has several sufficient foundations. A dependency map should expose immediate needs and longer routes separately, so planning supports learning instead of becoming a dense graph that demands expertise to interpret.','每桥配解释任务与新应用，只重查不确定依赖而不重开全科。概念有多条足够基础时保替代路线。地图分直接需要与长路线，支持学习而非专家才能读懂的密图。']
], [n('A project requires five concepts, with three demonstrated and one uncertain. How many are definitely not yet learned under this classification?','项目五概念，三已展示、一不确定，明确未学几项？',1,'Account for all three categories.','总数扣前两类。','5−3−1=1 concept is classified as not yet learned.','5−3−1=1。'),q('One successful recognition question is sufficient evidence of complete conceptual mastery.','一道识别题答对足以证明完全概念掌握。',false,'Recognition can occur without explanation or transfer.','识别可不含解释迁移。','Use multiple forms of evidence and retain uncertainty where needed.','需多种证据并保必要不确定。')]);
add('X04.03','Model or experiment design','模型或实验设计',[['Operational definition','操作定义'],['Control','控制'],['Sensitivity','敏感性']], [
['A design translates a question into measurable variables and a procedure capable of distinguishing explanations. Operational definitions specify how abstract concepts are observed, such as defining numerical energy drift as the maximum relative deviation from initial energy over a fixed interval. Without this step, different implementations may report different quantities under the same label.','设计把问题转成可测变量和可区分解释的程序。操作定义说明抽象如何观察，如固定时段能量相对初值最大偏差定义漂移。否则同名可报不同量。'],
['List independent variables, outcomes, controlled conditions, and possible confounders. A computational experiment must control model equations and initial state when comparing numerical methods. A physical experiment additionally needs calibration, repeated observations, and a measurement protocol. A control condition provides a meaningful comparison; it is not merely a second run with unrelated settings.','列自变量、结果、控制和混杂。计算比方法需固定方程初态；物理实验还需校准、重复、测量协议。对照需有意义，不是另一组无关设置。'],
['To compare Euler and a higher-order integrator, use the same pendulum parameters, initial angle, time horizon, and output metric. Vary time step systematically for both. If one method uses a much smaller step, lower error may reflect extra computational work rather than a better method at equal cost. Measure runtime or function evaluations alongside accuracy.','比Euler与高阶积分器需同摆参数初角时长指标，对两者系统变步。若一法步更小，低误差可能只是更多计算，而非等成本更好，应同时测时间或函数求值数。'],
['Predict outcomes under at least two plausible explanations before collecting evidence. Choose enough variation to expose the distinction, and identify conditions where the model should fail. Avoid changing the success criterion after seeing results without disclosing that change. A design can be revised during learning, but exploratory revisions and preplanned confirmatory checks should remain distinguishable in the final report.','采证前预测至少两种解释的结果，选足变化区分并标预期失效条件。看结果后改成功标准需披露。学习可改设计，但最终要分探索修改与预计划确认检查。']
], [n('Two solvers each run at four step sizes with three repetitions. How many runs are planned?','两求解器、四步长、各三重复，共几次运行？',24,'Multiply independent design factors.','相乘设计因素。','2×4×3=24 runs.','2×4×3=24。'),q('Comparing solver accuracy at very different computational costs automatically establishes equal-cost superiority.','在差异巨大成本下比较精度自动证明等成本更优。',false,'Cost is part of the comparison condition.','成本是比较条件之一。','Measure an accuracy-cost trade-off under comparable budgets.','应在可比预算测精度成本权衡。')]);
add('X04.04','Implementation and evidence collection','实现与证据采集',[['Instrumented implementation','带测量实现'],['Raw evidence','原始证据'],['Quality gate','质量关卡']], [
['Implementation should make the proposed procedure concrete without changing the research question silently. Separate the scientific calculation from measurement and reporting code. Instrumentation records inputs, versions, timing boundaries, and outputs needed to evaluate the claim. Excessive instrumentation can perturb performance, so document what was measured and how measurement overhead was handled.','实现把程序具体化，不悄改问题。分科学计算与测量报告，记录输入、版本、计时边界和输出。测量本身可扰性能，需说明测什么和如何处理开销。'],
['Preserve raw evidence before aggregation. For simulations, save parameter sets and checksums or identifiers for input data; for observations, retain units and collection context. Validate records as they arrive so a failed instrument or truncated output is not discovered only after all trials finish. Invalid trials need explicit reasons rather than silent deletion.','汇总前保原始证据，模拟存参数输入标识，观察保单位情境。边采边验证，避免全做完才发现仪器坏或截断。无效试验需明确原因，不悄删除。'],
['A timing experiment may separate setup, warmup, computation, and file writing. If the question concerns solver runtime, including a slow plot export in one method but not another biases comparison. Record each phase or apply the same boundary consistently. Repeat runs in an order that reduces systematic effects from warming hardware or changing background load.','计时可分准备、预热、计算、写文件。若问求解器运行，一法含慢绘图导出另一不含会偏。应各阶段记或统一边界，重复顺序减少硬件预热后台变化系统影响。'],
['Use early quality gates: known small cases, dimension checks, conservation checks, and expected failure behavior. These detect implementation defects before expensive evidence collection. A completed script is not itself a successful experiment; outputs must satisfy the planned validity criteria. Record interruptions and deviations so the final interpretation can account for the actual process rather than an idealized version of it.','早设质量关卡：已知小例、量纲、守恒、预期失败，防昂贵采证前有实现缺陷。脚本完成不等于实验成功，输出需满足有效条件。记录打断偏离，让解释对应真实而非理想过程。']
], [n('A run takes 2 s setup, 5 s computation, and 3 s export. Under a computation-only metric, what time is reported?','运行准备2秒、计算5秒、导出3秒，仅计算指标应报几秒？',5,'Use the predefined measurement boundary.','用预定计时边界。','Only the five-second computation phase belongs to that metric.','仅五秒计算属于该指标。'),q('Invalid trials may be silently removed because they make a report less tidy.','无效试验可因使报告不整齐而悄悄删除。',false,'Exclusion affects interpretation and reproducibility.','排除影响解释复现。','Record the reason and count, then apply consistent rules.','记录理由数量并一致处理。')]);
add('X04.05','Critique, replication and revision','批判、重复研究与修订',[['Reproduction','计算复现'],['Replication','独立重复'],['Alternative explanation','替代解释']], [
['Critique tests whether evidence supports a claim under its stated assumptions. Computational reproduction reruns the original analysis with its data and methods; replication collects or uses independent evidence addressing the same question. Terminology varies by field, so state the intended meaning. Agreement under one procedure does not automatically establish generality across conditions.','批判检验证据在假设下是否支持主张。计算复现重跑原数据方法，独立重复用新证据问同问题，领域术语可异，需声明含义。一程序一致不自动普遍适用。'],
['Inspect the entire chain from measurement to inference. Ask whether data were selected, whether a comparison baseline was appropriate, whether uncertainty was quantified, and whether another mechanism predicts the same observation. Strong critique identifies a specific vulnerable inference and an informative check, rather than merely expressing skepticism or confidence about the conclusion.','检查测量到推断链，问选择、基线、不确定及替代机制。好批判指出具体脆弱推理和有信息检查，不只是泛泛怀疑或信任结论。'],
['If two implementations agree on a pendulum simulation, they may share the same wrong acceleration sign. Checking small-angle oscillation against the expected restoring direction and an analytic period provides independent structure. If energy grows as the time step shrinks, investigate both the model and diagnostic calculation rather than assuming numerical instability is the only explanation.','两摆程序一致可能共用错误加速度符号。检查小角恢复方向和解析周期提供独立结构。若缩步能量仍长，需查模型与诊断，不能只认数值不稳。'],
['When a result fails replication, examine differences in inputs, conditions, implementation, and uncertainty before declaring fraud or impossibility. Revise the model or narrow the claim when evidence warrants it. Keep prior results and revisions traceable. A negative result can be valuable when it rules out a plausible explanation or reveals the boundary of a method under clearly specified conditions.','重复失败时先查输入条件实现与不确定，不立即指欺诈或不可能。证据需要时改模型或缩主张，保版本可追踪。否定结果若排除解释或揭方法边界，也有价值。']
], [n('An independent check disagrees with two implementations that share one formula. How many independent formula sources do those two implementations provide?','两实现共用同公式与独立检查冲突，这两实现提供几个独立公式来源？',1,'Shared derivation is one source of assumptions.','共享推导是同一假设来源。','They supply one shared formula source, not two independent derivations.','是一个共享公式来源，不是两份独立推导。'),q('A failed replication alone proves intentional misconduct.','重复失败本身证明故意不端。',false,'Many methodological and contextual differences can explain failure.','许多方法情境差异可解释。','Investigate evidence and conditions before attributing intent.','归因意图前先调查证据条件。')]);
add('X04.06','Bilingual presentation and open questions','双语展示与开放问题',[['Claim equivalence','主张等价'],['Visual argument','视觉论证'],['Open question','开放问题']], [
['A research presentation should communicate the question, method, evidence, conclusion, and limitations in a sequence the audience can assess. Bilingual delivery requires preserving meaning, not matching word count. Definitions, units, quantifiers, and uncertainty statements must remain equivalent across languages, especially where one omitted condition changes a mathematical or scientific claim.','展示按可评顺序讲问题、方法、证据、结论、限制。双语保意义非字数，定义单位量词不确定须等价，一项条件遗漏可能改数学科学主张。'],
['Use a small number of visuals that each answer a clear question. A dependency diagram explains required concepts; a graph compares measured outcomes; a table lists assumptions or parameter values. Label simulations, measurements, and schematic illustrations differently. Every visual should include enough context to be understood without relying on an enthusiastic spoken interpretation.','每图回答清楚问题：依赖图讲前提，曲线比结果，表列假设参数。模拟、测量、示意应区分标签，图要有足上下文，不依赖热情口述才能理解。'],
['An English statement “error decreased approximately linearly with step size over the tested range” should not become Chinese “the method is always first-order accurate” without further proof. The latter removes the empirical range and strengthens a measured trend into a universal theorem. A bilingual glossary and side-by-side claim check help catch such shifts.','英文“测试范围内误差近似随步长线性下降”不能译成“方法永远一阶精确”，后者去掉实测范围并把趋势强化为普遍定理。术语表和并排主张核对可发现这种变化。'],
['End with open questions tied to evidence: an untested parameter regime, an alternative model, or an unresolved error source. State what next observation would reduce uncertainty and which prerequisites it requires. Share reproducible artifacts only within authorized publication scope and with appropriate source attribution. A strong presentation makes both achievement and remaining work concrete, allowing another learner to continue the investigation responsibly.','开放问题应系证据，如未测参数域、替代模型、未明误差，并说何观察可减疑及所需前提。复现材料只在授权发布范围内分享并署来源。好展示让成果与剩余具体，便他人负责继续。']
], [n('A report tests three of five planned parameter regimes. How many regimes should remain explicitly open?','计划五参数域，只测试三，几域应明确保留开放？',2,'Subtract tested regimes from the plan.','计划减已测。','5−3=2 regimes lack direct evidence.','5−3=2域缺直接证据。'),q('Translation may safely strengthen a tested empirical trend into a universal theorem.','翻译可以安全把实测趋势强化为普遍定理。',false,'That changes the claim and its evidence requirements.','这改变主张与证据要求。','Preserve tested ranges, qualifiers, and uncertainty in both languages.','两语言都应保测试范围、限定与不确定。')]);

// A fresh application supplements the familiar worked MST example; new IDs preserve old attempt meaning.
